/** 构建以 symbol 与 6 位代码为键的股票映射 */
export function buildStockMap(stocks: StockInfo[]): Map<string, StockInfo> {
  const map = new Map<string, StockInfo>()
  for (const stock of stocks) {
    map.set(stock.symbol, stock)
    const codeMatch = stock.symbol.match(/(\d{6})/)
    if (codeMatch?.[1]) {
      map.set(codeMatch[1], stock)
    }
  }
  return map
}

function normalizeNewsArticle(
  article: Pick<NewsArticle, 'title' | 'content'>,
): NewsArticle {
  const partial = article as Partial<NewsArticle>
  const id = partial.id ?? `news_${generateId()}`
  const now = new Date().toISOString()
  return {
    id,
    title: article.title ?? '',
    content: article.content ?? '',
    url: partial.url ?? '',
    source: partial.source ?? '',
    category: partial.category ?? '',
    publishTime: partial.publishTime ?? now,
    fetchTime: partial.fetchTime ?? now,
    sentiment: partial.sentiment ?? 'neutral',
    sentimentConfidence: partial.sentimentConfidence ?? 0,
    relatedStocks: partial.relatedStocks ?? [],
    keywords: partial.keywords ?? [],
    hash: partial.hash ?? '',
  }
}

function matchText(
  text: string,
  source: 'title' | 'content',
  stockMap: Map<string, StockInfo>,
  config: Required<LinkerConfig>,
): StockLink[] {
  const sourceWeight = source === 'title' ? config.titleWeight : config.contentWeight
  const stocks = Array.from(new Set(stockMap.values()))
  const links: StockLink[] = []

  for (const stock of stocks) {
    const candidates: StockLink[] = []

    if (config.enableExactCode) {
      const codePattern = /\b(\d{6})\b/g
      let match: RegExpExecArray | null
      while ((match = codePattern.exec(text)) !== null) {
        const code = match[1]
        if (!code) continue
        const matchedStock = stockMap.get(code) ?? stockMap.get(`${code}.SH`) ?? stockMap.get(`${code}.SZ`)
        if (matchedStock && matchedStock.symbol === stock.symbol) {
          candidates.push({
            symbol: stock.symbol,
            name: stock.name,
            matchType: 'exact_code',
            confidence: Math.min(1, MATCH_CONFIDENCE_BASE.exact_code * sourceWeight),
            source,
            matchedKeyword: code,
          })
        }
      }
    }

    if (config.enableExactName && text.includes(stock.name)) {
      candidates.push({
        symbol: stock.symbol,
        name: stock.name,
        matchType: 'exact_name',
        confidence: Math.min(1, MATCH_CONFIDENCE_BASE.exact_name * sourceWeight),
        source,
        matchedKeyword: stock.name,
      })
    }

    if (config.enableFuzzy && stock.name.length >= 2) {
      for (let len = 2; len <= Math.min(4, stock.name.length); len++) {
        const prefix = stock.name.slice(0, len)
        if (text.includes(prefix)) {
          candidates.push({
            symbol: stock.symbol,
            name: stock.name,
            matchType: 'fuzzy_name',
            confidence: Math.min(1, MATCH_CONFIDENCE_BASE.fuzzy_name * sourceWeight),
            source,
            matchedKeyword: prefix,
          })
          break
        }
      }
    }

    if (config.enableIndustry && stock.industry) {
      const keywords = DEFAULT_INDUSTRY_KEYWORDS[stock.industry] ?? []
      for (const keyword of keywords) {
        if (text.includes(keyword)) {
          candidates.push({
            symbol: stock.symbol,
            name: stock.name,
            matchType: 'industry',
            confidence: Math.min(1, MATCH_CONFIDENCE_BASE.industry * sourceWeight),
            source,
            matchedKeyword: keyword,
          })
        }
      }
    }

    if (candidates.length > 0) {
      const best = candidates.sort((a, b) => b.confidence - a.confidence)[0]!
      if (best.confidence >= config.confidenceThreshold) {
        links.push(best)
      }
    }
  }

  return links
}

/** 对单篇资讯进行股票关联，返回 links 并填充 article.relatedStocks */
export function linkArticleToStocks(
  article: Pick<NewsArticle, 'title' | 'content'>,
  stocks: StockInfo[],
  config?: Partial<LinkerConfig>,
): { article: NewsArticle; links: StockLink[]; maps: NewsStockMap[] } {
  const fullConfig = { ...DEFAULT_LINKER_CONFIG, ...config }
  const stockMap = buildStockMap(stocks)
  const fullArticle = normalizeNewsArticle(article)

  const titleLinks = matchText(fullArticle.title, 'title', stockMap, fullConfig)
  const contentLinks = matchText(fullArticle.content, 'content', stockMap, fullConfig)

  const bestBySymbol = new Map<string, StockLink>()
  for (const link of [...titleLinks, ...contentLinks]) {
    const existing = bestBySymbol.get(link.symbol)
    if (!existing || link.confidence > existing.confidence) {
      bestBySymbol.set(link.symbol, link)
    }
  }

  const links = Array.from(bestBySymbol.values())
    .sort((a, b) => b.confidence - a.confidence)
    .slice(0, fullConfig.maxLinks)

  fullArticle.relatedStocks = links.map((link) => link.symbol)

  const maps: NewsStockMap[] = links.map((link) => ({
    id: `${link.symbol}_${fullArticle.id}`,
    symbol: link.symbol,
    newsId: fullArticle.id,
    relevanceScore: link.confidence,
    isTitleMatch: link.source === 'title',
    isContentMatch: link.source === 'content',
    industryMatch: link.matchType === 'industry',
  }))

  return { article: fullArticle, links, maps }
}

/**
 * PWA Service Worker 注册模块
 * 质量门禁 #11 - PWA 离线验证
 *
 * 职责：
 * 1. 检测浏览器是否支持 Service Worker
 * 2. 注册 SW 并监控注册状态（成功/失败/更新）
 * 3. 导出状态供外部查询和测试
 */

export type SWRegistrationStatus =
  | 'unsupported'
  | 'registering'
  | 'registered'
  | 'updated'
  | 'error'

/** 全局注册状态，供外部查询 */
let currentStatus: SWRegistrationStatus = 'unsupported'
let registration: ServiceWorkerRegistration | null = null

/**
 * 获取当前 SW 注册状态
 */
export function getSWStatus(): SWRegistrationStatus {
  return currentStatus
}

/**
 * 获取 SW 注册实例（如果有）
 */
export function getSWRegistration(): ServiceWorkerRegistration | null {
  return registration
}

/**
 * 注册 Service Worker
 *
 * 仅在生产环境且有 SW 文件时执行注册。
 * 注册过程通过 console 明确输出状态日志。
 *
 * @param swUrl - Service Worker 文件路径，默认 '/sw.js'
 * @returns Promise<ServiceWorkerRegistration | null>
 */
export async function registerServiceWorker(
  swUrl = '/sw.js',
): Promise<ServiceWorkerRegistration | null> {
  // 检测浏览器支持
  if (!('serviceWorker' in navigator)) {
    console.warn('[PWA] Service Worker 不受当前浏览器支持')
    currentStatus = 'unsupported'
    return null
  }

  currentStatus = 'registering'
  console.info('[PWA] 正在注册 Service Worker ...', swUrl)

  try {
    const reg = await navigator.serviceWorker.register(swUrl)
    registration = reg

    // ---- 注册成功 ----
    console.info('[PWA] Service Worker 注册成功 (scope:', reg.scope, ')')

    // 检查是否有更新等待激活
    if (reg.waiting) {
      currentStatus = 'updated'
      console.info('[PWA] 发现新版本 SW 等待激活')
    } else if (reg.active) {
      currentStatus = 'registered'
      console.info('[PWA] SW 已激活并运行中')
    }

    // 监听后续更新
    reg.addEventListener('updatefound', () => {
      const newWorker = reg.installing
      if (!newWorker) return

      newWorker.addEventListener('statechange', () => {
        if (
          newWorker.state === 'installed' &&
          navigator.serviceWorker.controller
        ) {
          // 已有 SW 在运行，新 SW 安装完成 => 有更新可用
          currentStatus = 'updated'
          console.info('[PWA] 新版本 SW 安装完成，刷新页面后生效')
        }
      })
    })

    // 监听 controller 变化（用户接受了更新）
    reg.addEventListener('controllerchange', () => {
      console.info('[PWA] 新 SW 已接管页面控制权')
    })

    return reg
  } catch (err) {
    currentStatus = 'error'
    const message = err instanceof Error ? err.message : String(err)
    console.error('[PWA] Service Worker 注册失败:', message)
    return null
  }
}

/**
 * 清理残留的旧版 Service Worker。
 *
 * 当项目不再提供 sw.js 时，浏览器中已注册的旧 SW 仍会拦截网络请求，
 * 导致 fetch 失败被 SW 放大为网络错误。此函数在应用初始化时自动注销旧 SW。
 */
async function cleanupStaleServiceWorker(): Promise<void> {
  if (!('serviceWorker' in navigator)) return

  try {
    const registrations = await navigator.serviceWorker.getRegistrations()
    if (registrations.length === 0) return

    // 检查当前作用域的 SW 脚本是否仍可访问
    const response = await fetch('/sw.js', { method: 'HEAD', cache: 'no-cache' }).catch(() => null)
    if (response && response.ok) return // sw.js 存在，无需清理

    // sw.js 不存在，注销所有残留的 SW
    console.info(`[PWA] sw.js 不存在，清理 ${registrations.length} 个残留 Service Worker ...`)
    await Promise.all(
      registrations.map((reg) =>
        reg.unregister().then((ok) => {
          if (ok) console.info('[PWA] SW 注销成功:', reg.scope)
        }),
      ),
    )
    currentStatus = 'unsupported'
  } catch (err) {
    console.warn('[PWA] 清理残留 SW 失败:', err)
  }
}

/**
 * 在 App 初始化时调用，自动注册 SW（仅生产环境）。
 * 开发环境下自动清理残留旧版 SW。
 */
export function initPWA(): void {
  if (import.meta.env.PROD) {
    registerServiceWorker().catch((err) => {
      console.error('[PWA] initPWA 异常:', err)
    })
  } else {
    console.info('[PWA] 开发环境跳过 Service Worker 注册')
    currentStatus = 'unsupported'
    // 开发环境下清理旧版残留 SW，防止拦截请求产生错误
    cleanupStaleServiceWorker().catch((err) => {
      console.warn('[PWA] cleanupStaleServiceWorker 异常:', err)
    })
  }
}

/**
 * HotSectorAnalyzer — 热门板块五维评分引擎
 *
 * 基于双策略体系，对热门板块标的进行五维评分：
 * - 动量强度 (momentum):        35%
 * - 情绪热度 (sentiment):       25%
 * - 技术突破 (breakout):         20%
 * - 估值风险 (valuationRisk):    15%
 * - 大盘环境 (marketEnv):        5%
 *
 * 输出：HotSectorScore { overallScore: 0-5, signal: 'buy'|'hold'|'avoid' }
 *
 * @module services/scoring/hotSectorAnalyzer
 * @created 2026-06-27 - 基于双策略体系修正
 */

import { ENVELOPE_ACTION, ENVELOPE_TARGET, MODULE_ID } from '@/config/dbConfig'
import { getDefaultDualStrategyRuleConfig, type DualStrategyRuleConfig } from '@/config/dualStrategyRules'
import { HOT_SECTOR_THRESHOLDS } from '@/config/thresholds'
import { EnvelopeFactory } from '@/core/envelope'
import { dataLayer } from '@/data/dataLayer'
import { checkStrategyScoreFreshness } from '@/core/freshnessGuard'
import type { DataLayerResult, HotSectorScore, Stock } from '@/data/types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

// ============================================================
// 输入类型
// ============================================================

export interface MomentumInput {
  /** 板块强度评分 0-5 */
  sectorStrengthScore: number
  /** 涨跌幅排名（1=最高） */
  priceChangeRank: number
  /** 成交量放大倍数（近5日/近20日） */
  volumeExpansion: number
  /** 资金连续流入天数 */
  consecutiveInflow: number
  /** 相对强弱 RS 值 */
  relativeStrength: number
}

export interface SentimentInput {
  /** 舆情热度排名（1=最高） */
  sentimentRank: number
  /** 散户情绪 0-1（1=极度乐观） */
  retailSentiment: number
  /** 龙虎榜机构买入家数 */
  institutionBuyCount: number
  /** 涨停板数量 */
  limitUpCount: number
}

export interface BreakoutInput {
  /** 是否有突破形态 */
  hasBreakoutPattern: boolean
  /** RSI 信号方向（多头/空头/中性，基于 RSI 阈值推导） */
  rsiSignal: 'bullish' | 'bearish' | 'neutral'
  /** RSI(14) 值 */
  rsi: number
  /** 价格是否站上 MA20 */
  priceAboveMA20: boolean
  /** 价格是否站上 MA60 */
  priceAboveMA60: boolean
}

export interface ValuationRiskInput {
  /** 当前 PE */
  pe: number
  /** PB 历史分位 0-100 */
  pbPercentile: number
  /** 市值（亿元） */
  marketCap: number
  /** 股息率 % */
  dividendYield: number
}

export interface MarketEnvInput {
  /** 大盘趋势 */
  marketTrend: 'bull' | 'bear' | 'sideways'
  /** 系统性风险等级 */
  systemicRisk: 'low' | 'medium' | 'high'
}

/** 各维度计算所需的聚合输入 */
export interface HotSectorAnalyzerInput {
  symbol: string
  sectorName: string
  momentum: MomentumInput
  sentiment: SentimentInput
  breakout: BreakoutInput
  valuationRisk: ValuationRiskInput
  marketEnv: MarketEnvInput
}

// ============================================================
// 输出类型复用 data/types.ts 中的 HotSectorScore
// 维度映射：breakout → technical，valuationRisk → valuation，composite 为加权综合分
// ============================================================

export type { HotSectorScore }

// ============================================================
// 权重常量
// ============================================================

const WEIGHTS = {
  momentum: HOT_SECTOR_THRESHOLDS.WEIGHT_MOMENTUM,
  sentiment: HOT_SECTOR_THRESHOLDS.WEIGHT_SENTIMENT,
  breakout: HOT_SECTOR_THRESHOLDS.WEIGHT_BREAKOUT,
  valuationRisk: HOT_SECTOR_THRESHOLDS.WEIGHT_VALUATION_RISK,
  marketEnv: HOT_SECTOR_THRESHOLDS.WEIGHT_MARKET_ENV,
} as const

// ============================================================
// 维度评分函数
// ============================================================

function clampScore(value: number): number {
  return Math.max(
    HOT_SECTOR_THRESHOLDS.SCORE_MIN,
    Math.min(HOT_SECTOR_THRESHOLDS.SCORE_MAX, value),
  )
}

/**
 * 动量强度评分（权重 35%）
 *
 * 评分逻辑：
 * - 板块强度分直接映射到 0-5
 * - 排名越靠前加分越多（top10 → +1.5, top50 → 0）
 * - 量比 > 2.0 → +1, 1.0-2.0 → +0.5
 * - 资金连续流入 3 天以上 → +0.5
 * - RS 值偏离中位数映射
 */
export function calculateMomentum(data: MomentumInput): number {
  if (
    data.sectorStrengthScore < HOT_SECTOR_THRESHOLDS.SCORE_MIN ||
    data.sectorStrengthScore > HOT_SECTOR_THRESHOLDS.SCORE_MAX
  ) {
    return HOT_SECTOR_THRESHOLDS.SCORE_MIN
  }

  let score = data.sectorStrengthScore

  // 排名加分
  if (data.priceChangeRank <= HOT_SECTOR_THRESHOLDS.MOMENTUM_RANK_TOP10) {
    score += HOT_SECTOR_THRESHOLDS.MOMENTUM_RANK_TOP10_BONUS
  } else if (data.priceChangeRank <= HOT_SECTOR_THRESHOLDS.MOMENTUM_RANK_TOP30) {
    score += HOT_SECTOR_THRESHOLDS.MOMENTUM_RANK_TOP30_BONUS
  } else if (data.priceChangeRank <= HOT_SECTOR_THRESHOLDS.MOMENTUM_RANK_TOP50) {
    score += HOT_SECTOR_THRESHOLDS.MOMENTUM_RANK_TOP50_BONUS
  }

  // 成交量放大加分
  if (data.volumeExpansion >= HOT_SECTOR_THRESHOLDS.MOMENTUM_VOLUME_EXPANSION_HIGH) {
    score += HOT_SECTOR_THRESHOLDS.MOMENTUM_VOLUME_EXPANSION_HIGH_BONUS
  } else if (data.volumeExpansion >= HOT_SECTOR_THRESHOLDS.MOMENTUM_VOLUME_EXPANSION_MEDIUM) {
    score += HOT_SECTOR_THRESHOLDS.MOMENTUM_VOLUME_EXPANSION_MEDIUM_BONUS
  }

  // 资金连续流入
  if (data.consecutiveInflow >= HOT_SECTOR_THRESHOLDS.MOMENTUM_CONSECUTIVE_INFLOW_DAYS) {
    score += HOT_SECTOR_THRESHOLDS.MOMENTUM_CONSECUTIVE_INFLOW_BONUS
  }

  // RS 映射：中性基准 → 0，极端 0/100 → 按比例
  const rsDeviation =
    Math.abs(data.relativeStrength - HOT_SECTOR_THRESHOLDS.MOMENTUM_RS_BASE) /
    HOT_SECTOR_THRESHOLDS.MOMENTUM_RS_BASE
  score += rsDeviation * HOT_SECTOR_THRESHOLDS.MOMENTUM_RS_DEVIATION_MULTIPLIER

  return clampScore(score)
}

/**
 * 情绪热度评分（权重 25%）
 *
 * 评分逻辑：
 * - 舆情排名 top5 → 5，top20 → 3，top50 → 1.5
 * - 散户情绪极度乐观/悲观 → 低分（过热/恐慌），中性 → 高分
 * - 机构买入家数 ≥ 5 → +1.5，≥ 2 → +0.5
 * - 涨停板数量 ≥ 10 → +1，≥ 3 → +0.5
 */
export function calculateSentiment(data: SentimentInput): number {
  if (data.sentimentRank < HOT_SECTOR_THRESHOLDS.RANK_MIN) {
    return HOT_SECTOR_THRESHOLDS.SCORE_MIN
  }

  let score = HOT_SECTOR_THRESHOLDS.SCORE_MIN

  // 舆情排名映射
  if (data.sentimentRank <= HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP5) {
    score = HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP5_SCORE
  } else if (data.sentimentRank <= HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP10) {
    score = HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP10_SCORE
  } else if (data.sentimentRank <= HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP20) {
    score = HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP20_SCORE
  } else if (data.sentimentRank <= HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP50) {
    score = HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_TOP50_SCORE
  } else {
    score = HOT_SECTOR_THRESHOLDS.SENTIMENT_RANK_OTHER_SCORE
  }

  // 散户情绪过热惩罚（极度乐观，视为风险）
  if (data.retailSentiment > HOT_SECTOR_THRESHOLDS.SENTIMENT_RETAIL_OVERHEATED) {
    score -= HOT_SECTOR_THRESHOLDS.SENTIMENT_RETAIL_OVERHEATED_PENALTY
  } else if (data.retailSentiment < HOT_SECTOR_THRESHOLDS.SENTIMENT_RETAIL_PANIC) {
    // 极度恐慌也可能是机会
    score -= HOT_SECTOR_THRESHOLDS.SENTIMENT_RETAIL_PANIC_PENALTY
  }

  // 机构买入加分
  if (data.institutionBuyCount >= HOT_SECTOR_THRESHOLDS.SENTIMENT_INSTITUTION_BUY_HIGH) {
    score += HOT_SECTOR_THRESHOLDS.SENTIMENT_INSTITUTION_BUY_HIGH_BONUS
  } else if (data.institutionBuyCount >= HOT_SECTOR_THRESHOLDS.SENTIMENT_INSTITUTION_BUY_MEDIUM) {
    score += HOT_SECTOR_THRESHOLDS.SENTIMENT_INSTITUTION_BUY_MEDIUM_BONUS
  }

  // 涨停板加分
  if (data.limitUpCount >= HOT_SECTOR_THRESHOLDS.SENTIMENT_LIMIT_UP_HIGH) {
    score += HOT_SECTOR_THRESHOLDS.SENTIMENT_LIMIT_UP_HIGH_BONUS
  } else if (data.limitUpCount >= HOT_SECTOR_THRESHOLDS.SENTIMENT_LIMIT_UP_MEDIUM) {
    score += HOT_SECTOR_THRESHOLDS.SENTIMENT_LIMIT_UP_MEDIUM_BONUS
  }

  return clampScore(score)
}

/**
 * 技术突破评分（权重 20%）
 *
 * 评分逻辑：
 * - 突破形态 → +2
 * - MACD 金叉 → +1.5，死叉 → -1
 * - RSI 50-70 为最佳区间，极端值惩罚
 * - 均线多头排列（价格 > MA20 > MA60）→ +1
 */
export function calculateBreakout(data: BreakoutInput): number {
  let score = HOT_SECTOR_THRESHOLDS.BREAKOUT_NEUTRAL_BASE

  // 突破形态
  if (data.hasBreakoutPattern) {
    score += HOT_SECTOR_THRESHOLDS.BREAKOUT_PATTERN_BONUS
  }

  // RSI 信号方向
  if (data.rsiSignal === 'bullish') {
    score += HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_SIGNAL_BULLISH_BONUS
  } else if (data.rsiSignal === 'bearish') {
    score -= HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_SIGNAL_BEARISH_PENALTY
  }

  // RSI 评分：最佳区间，极端值惩罚
  if (
    data.rsi >= HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_OPTIMAL_LOW &&
    data.rsi <= HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_OPTIMAL_HIGH
  ) {
    score += HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_OPTIMAL_BONUS
  } else if (data.rsi > HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_OVERBOUGHT) {
    score -= HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_OVERBOUGHT_PENALTY // 超买
  } else if (data.rsi < HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_OVERSOLD) {
    score -= HOT_SECTOR_THRESHOLDS.BREAKOUT_RSI_OVERSOLD_PENALTY // 超卖但无反弹
  }

  // 均线多头排列
  if (data.priceAboveMA20 && data.priceAboveMA60) {
    score += HOT_SECTOR_THRESHOLDS.BREAKOUT_MA_ALIGNMENT_BONUS
  } else if (!data.priceAboveMA20 && !data.priceAboveMA60) {
    score -= HOT_SECTOR_THRESHOLDS.BREAKOUT_MA_MISALIGNMENT_PENALTY
  }

  return clampScore(score)
}

/**
 * 估值风险评分（权重 15%）
 *
 * 评分逻辑：
 * - PE < 10 → 5，10-20 → 4-3，20-50 → 3-2，> 50 → 1-0
 * - PB 分位越低越好：< 20% → +1，> 80% → -1
 * - 市值越大流动性越好 → 加分
 * - 股息率 > 3% → +1，> 1.5% → +0.5
 */
export function calculateValuationRisk(data: ValuationRiskInput): number {
  let score = HOT_SECTOR_THRESHOLDS.SCORE_MIN

  // PE 评分
  if (data.pe <= HOT_SECTOR_THRESHOLDS.VALUATION_PE_NEGATIVE) {
    score = HOT_SECTOR_THRESHOLDS.VALUATION_PE_NEGATIVE_SCORE // 亏损
  } else if (data.pe < HOT_SECTOR_THRESHOLDS.VALUATION_PE_LOW) {
    score = HOT_SECTOR_THRESHOLDS.VALUATION_PE_LOW_SCORE
  } else if (data.pe < HOT_SECTOR_THRESHOLDS.VALUATION_PE_MEDIUM_LOW) {
    score = HOT_SECTOR_THRESHOLDS.VALUATION_PE_MEDIUM_LOW_SCORE
  } else if (data.pe < HOT_SECTOR_THRESHOLDS.VALUATION_PE_MEDIUM) {
    score = HOT_SECTOR_THRESHOLDS.VALUATION_PE_MEDIUM_SCORE
  } else if (data.pe < HOT_SECTOR_THRESHOLDS.VALUATION_PE_HIGH) {
    score = HOT_SECTOR_THRESHOLDS.VALUATION_PE_HIGH_SCORE
  } else if (data.pe < HOT_SECTOR_THRESHOLDS.VALUATION_PE_VERY_HIGH) {
    score = HOT_SECTOR_THRESHOLDS.VALUATION_PE_VERY_HIGH_SCORE
  } else {
    score = HOT_SECTOR_THRESHOLDS.VALUATION_PE_EXTREME_SCORE
  }

  // PB 分位
  if (data.pbPercentile < HOT_SECTOR_THRESHOLDS.VALUATION_PB_PERCENTILE_LOW) {
    score += HOT_SECTOR_THRESHOLDS.VALUATION_PB_LOW_BONUS
  } else if (data.pbPercentile > HOT_SECTOR_THRESHOLDS.VALUATION_PB_PERCENTILE_HIGH) {
    score -= HOT_SECTOR_THRESHOLDS.VALUATION_PB_HIGH_PENALTY
  }

  // 市值流动性
  if (data.marketCap > HOT_SECTOR_THRESHOLDS.VALUATION_MARKET_CAP_LARGE) {
    score += HOT_SECTOR_THRESHOLDS.VALUATION_MARKET_CAP_LARGE_BONUS
  } else if (data.marketCap < HOT_SECTOR_THRESHOLDS.VALUATION_MARKET_CAP_SMALL) {
    score -= HOT_SECTOR_THRESHOLDS.VALUATION_MARKET_CAP_SMALL_PENALTY
  }

  // 股息率
  if (data.dividendYield > HOT_SECTOR_THRESHOLDS.VALUATION_DIVIDEND_YIELD_HIGH) {
    score += HOT_SECTOR_THRESHOLDS.VALUATION_DIVIDEND_YIELD_HIGH_BONUS
  } else if (data.dividendYield > HOT_SECTOR_THRESHOLDS.VALUATION_DIVIDEND_YIELD_MEDIUM) {
    score += HOT_SECTOR_THRESHOLDS.VALUATION_DIVIDEND_YIELD_MEDIUM_BONUS
  }

  return clampScore(score)
}

/**
 * 大盘环境评分（权重 5%）
 *
 * 评分逻辑：
 * - 牛市 → 5，震荡 → 3，熊市 → 1
 * - 系统性风险低 → +1，高 → -2
 */
export function calculateMarketEnv(data: MarketEnvInput): number {
  let score = HOT_SECTOR_THRESHOLDS.SCORE_MIN

  switch (data.marketTrend) {
    case 'bull':
      score = HOT_SECTOR_THRESHOLDS.MARKET_ENV_BULL_SCORE
      break
    case 'sideways':
      score = HOT_SECTOR_THRESHOLDS.MARKET_ENV_SIDEWAYS_SCORE
      break
    case 'bear':
      score = HOT_SECTOR_THRESHOLDS.MARKET_ENV_BEAR_SCORE
      break
  }

  switch (data.systemicRisk) {
    case 'low':
      score += HOT_SECTOR_THRESHOLDS.MARKET_ENV_SYSTEMIC_RISK_LOW_BONUS
      break
    case 'medium':
      // 不调整
      break
    case 'high':
      score -= HOT_SECTOR_THRESHOLDS.MARKET_ENV_SYSTEMIC_RISK_HIGH_PENALTY
      break
  }

  return clampScore(score)
}

// ============================================================
// 综合评分
// ============================================================

/**
 * 执行五维综合评分，输出 HotSectorScore。
 */
export function analyze(input: HotSectorAnalyzerInput): HotSectorScore {
  const momentum = calculateMomentum(input.momentum)
  const sentiment = calculateSentiment(input.sentiment)
  const breakout = calculateBreakout(input.breakout)
  const valuationRisk = calculateValuationRisk(input.valuationRisk)
  const marketEnv = calculateMarketEnv(input.marketEnv)

  const overallScore =
    momentum * WEIGHTS.momentum +
    sentiment * WEIGHTS.sentiment +
    breakout * WEIGHTS.breakout +
    valuationRisk * WEIGHTS.valuationRisk +
    marketEnv * WEIGHTS.marketEnv

  const rounded =
    Math.round(overallScore * HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION) /
    HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION

  let action: HotSectorScore['action']
  if (rounded >= HOT_SECTOR_THRESHOLDS.ACTION_IMMEDIATE_THRESHOLD) {
    action = 'immediate'
  } else if (rounded >= HOT_SECTOR_THRESHOLDS.ACTION_PROBE_THRESHOLD) {
    action = 'probe'
  } else {
    action = 'ignore'
  }

  return {
    symbol: input.symbol,
    name: input.sectorName,
    score: rounded,
    dimensions: {
      momentum:
        Math.round(momentum * HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION) /
        HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION,
      sentiment:
        Math.round(sentiment * HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION) /
        HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION,
      technical:
        Math.round(breakout * HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION) /
        HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION,
      valuation:
        Math.round(valuationRisk * HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION) /
        HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION,
      composite: rounded,
      marketEnv:
        Math.round(marketEnv * HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION) /
        HOT_SECTOR_THRESHOLDS.SCORE_ROUNDING_PRECISION,
    },
    action,
    calculatedAt: Date.now(),
    dataVersion: HOT_SECTOR_THRESHOLDS.DATA_VERSION,
  }
}

// ============================================================
// 数据获取与编排
// ============================================================

function computeMA(closes: number[], period: number): number | undefined {
  if (closes.length < period) return undefined
  const slice = closes.slice(-period)
  return slice.reduce((a, b) => a + b, 0) / period
}

function computeRSI(
  closes: number[],
  period: number = HOT_SECTOR_THRESHOLDS.RSI_PERIOD,
): number | undefined {
  if (closes.length < period + 1) return undefined
  const window = closes.slice(-(period + 1))
  let gains = 0
  let losses = 0
  for (let i = 1; i < window.length; i++) {
    const delta = window[i]! - window[i - 1]!
    if (delta > 0) gains += delta
    else losses -= delta
  }
  if (losses === HOT_SECTOR_THRESHOLDS.SCORE_MIN)
    return HOT_SECTOR_THRESHOLDS.RSI_MAX
  return (
    HOT_SECTOR_THRESHOLDS.RSI_MAX -
    HOT_SECTOR_THRESHOLDS.RSI_MAX /
      (HOT_SECTOR_THRESHOLDS.RSI_FORMULA_OFFSET + gains / losses)
  )
}

/**
 * 根据 symbol 从 dataLayer 获取数据并执行五维评分。
 * 返回 null 表示数据不足无法评分。
 */
export async function analyzeBySymbol(symbol: string): Promise<HotSectorScore | null> {
  logger.info(`[hotSectorAnalyzer] 开始分析 ${symbol}`)

  const [stock, quotes, v6Score] = await Promise.all([
    dataLayer.stocks.get(symbol),
    dataLayer.dailyQuotes.get(symbol).catch(() => undefined),
    dataLayer.v6Scores.get(symbol).catch(() => undefined),
  ])

  if (!stock) {
    logger.warn(`[hotSectorAnalyzer] 股票数据缺失: ${symbol}`)
    return null
  }

  const now = Date.now()
  const v6CalculatedAt = v6Score?.calculatedAt ?? now
  const freshness = checkStrategyScoreFreshness(now, v6CalculatedAt, 'hot_sector_score')
  logger.info(`[hotSectorAnalyzer] ${symbol} freshness check`, {
    valid: freshness.valid,
    outputTime: freshness.outputTime,
    inputTime: freshness.inputTime,
  })

  const hasQuotes =
    quotes !== undefined && quotes.history.length >= HOT_SECTOR_THRESHOLDS.KLINE_MIN_DAYS
  const closes = hasQuotes ? quotes!.history.map((b) => b.close) : []
  const latest = hasQuotes ? closes[closes.length - 1]! : stock.price ?? HOT_SECTOR_THRESHOLDS.SCORE_MIN
  const ma20 = hasQuotes ? computeMA(closes, HOT_SECTOR_THRESHOLDS.MA20_PERIOD) : undefined
  const ma60 = hasQuotes ? computeMA(closes, HOT_SECTOR_THRESHOLDS.MA60_PERIOD) : undefined
  const rsi = hasQuotes ? computeRSI(closes) : undefined

  const volumes = hasQuotes ? quotes!.history.map((b) => b.volume) : []
  const recentAvgVol =
    volumes.length >= HOT_SECTOR_THRESHOLDS.VOLUME_RECENT_DAYS
      ? volumes
          .slice(-HOT_SECTOR_THRESHOLDS.VOLUME_RECENT_DAYS)
          .reduce((a, b) => a + b, 0) / HOT_SECTOR_THRESHOLDS.VOLUME_RECENT_DAYS
      : HOT_SECTOR_THRESHOLDS.SCORE_MIN
  const pastAvgVol =
    volumes.length >= HOT_SECTOR_THRESHOLDS.VOLUME_PAST_TOTAL_DAYS
      ? volumes
          .slice(-HOT_SECTOR_THRESHOLDS.VOLUME_PAST_TOTAL_DAYS, -HOT_SECTOR_THRESHOLDS.VOLUME_RECENT_DAYS)
          .reduce((a, b) => a + b, 0) / HOT_SECTOR_THRESHOLDS.VOLUME_PAST_DAYS
      : HOT_SECTOR_THRESHOLDS.VOLUME_DEFAULT_PAST_AVG
  const volumeExpansion =
    pastAvgVol > HOT_SECTOR_THRESHOLDS.VOLUME_EXPANSION_ZERO_THRESHOLD
      ? recentAvgVol / pastAvgVol
      : HOT_SECTOR_THRESHOLDS.VOLUME_DEFAULT_EXPANSION

  const momentum: MomentumInput = {
    sectorStrengthScore:
      v6Score?.factors?.动量 ?? HOT_SECTOR_THRESHOLDS.DEFAULT_SECTOR_STRENGTH_SCORE,
    priceChangeRank: hasQuotes
      ? Math.max(
          HOT_SECTOR_THRESHOLDS.RANK_MIN,
          HOT_SECTOR_THRESHOLDS.SECTOR_RANK_BASE - (closes.length % HOT_SECTOR_THRESHOLDS.SECTOR_RANK_BASE),
        )
      : HOT_SECTOR_THRESHOLDS.DEFAULT_PRICE_CHANGE_RANK,
    volumeExpansion,
    consecutiveInflow: HOT_SECTOR_THRESHOLDS.SCORE_MIN, // 需外部资金流数据填充
    relativeStrength: rsi ?? HOT_SECTOR_THRESHOLDS.RSI_DEFAULT,
  }

  const sentiment: SentimentInput = {
    sentimentRank: Math.max(
      HOT_SECTOR_THRESHOLDS.RANK_MIN,
      HOT_SECTOR_THRESHOLDS.SECTOR_RANK_BASE -
        Math.floor((v6Score?.score ?? HOT_SECTOR_THRESHOLDS.DEFAULT_V6_SCORE) * HOT_SECTOR_THRESHOLDS.SECTOR_RANK_MULTIPLIER),
    ),
    retailSentiment: HOT_SECTOR_THRESHOLDS.DEFAULT_RETAIL_SENTIMENT, // 默认中性
    institutionBuyCount: HOT_SECTOR_THRESHOLDS.SCORE_MIN, // 需外部龙虎榜数据填充
    limitUpCount: HOT_SECTOR_THRESHOLDS.SCORE_MIN, // 需外部涨停数据填充
  }

  const breakout: BreakoutInput = {
    hasBreakoutPattern: ma20 !== undefined && latest > ma20,
    rsiSignal:
      (rsi ?? HOT_SECTOR_THRESHOLDS.RSI_DEFAULT) > HOT_SECTOR_THRESHOLDS.RSI_SIGNAL_BULLISH_THRESHOLD
        ? 'bullish'
        : (rsi ?? HOT_SECTOR_THRESHOLDS.RSI_DEFAULT) < HOT_SECTOR_THRESHOLDS.RSI_SIGNAL_BEARISH_THRESHOLD
          ? 'bearish'
          : 'neutral',
    rsi: rsi ?? HOT_SECTOR_THRESHOLDS.RSI_DEFAULT,
    priceAboveMA20: ma20 !== undefined && latest > ma20,
    priceAboveMA60: ma60 !== undefined && latest > ma60,
  }

  const valuationRisk: ValuationRiskInput = {
    pe: stock.pe ?? HOT_SECTOR_THRESHOLDS.SCORE_MIN,
    pbPercentile:
      stock.pb !== undefined
        ? Math.min(
            HOT_SECTOR_THRESHOLDS.PB_PERCENTILE_MAX,
            Math.max(
              HOT_SECTOR_THRESHOLDS.PB_PERCENTILE_MIN,
              (stock.pb / HOT_SECTOR_THRESHOLDS.PB_PERCENTILE_REFERENCE) * HOT_SECTOR_THRESHOLDS.PB_PERCENTILE_MAX,
            ),
          )
        : HOT_SECTOR_THRESHOLDS.DEFAULT_PB_PERCENTILE,
    marketCap:
      (stock.marketCap ?? HOT_SECTOR_THRESHOLDS.SCORE_MIN) / HOT_SECTOR_THRESHOLDS.MARKET_CAP_YUAN_TO_BILLION, // 转为亿元
    dividendYield: HOT_SECTOR_THRESHOLDS.SCORE_MIN, // 需外部数据填充
  }

  const marketEnv: MarketEnvInput = {
    marketTrend: HOT_SECTOR_THRESHOLDS.DEFAULT_MARKET_TREND,
    systemicRisk: HOT_SECTOR_THRESHOLDS.DEFAULT_SYSTEMIC_RISK,
  }

  return analyze({
    symbol,
    sectorName:
      stock.sector ?? stock.industryCode ?? HOT_SECTOR_THRESHOLDS.DEFAULT_SECTOR_NAME,
    momentum,
    sentiment,
    breakout,
    valuationRisk,
    marketEnv,
  })
}

/**
 * 批量分析多只股票。
 */
export async function analyzeBatch(symbols: string[]): Promise<HotSectorScore[]> {
  const results: HotSectorScore[] = []
  const settled = await Promise.allSettled(symbols.map((symbol) => analyzeBySymbol(symbol)))
  for (const result of settled) {
    if (result.status === 'fulfilled' && result.value) {
      results.push(result.value)
    }
  }
  logger.info(`[hotSectorAnalyzer] 批量分析完成: ${results.length}/${symbols.length}`)
  return results
}

export interface HotSectorAnalyzerOptions {
  ruleConfig?: DualStrategyRuleConfig
}

/**
 * 对股票列表执行热门板块策略分析。
 *
 * 过滤逻辑：
 * - 只保留 V6 评分不低于 hotSectorV6Min 的股票
 * - 为每只股票计算 HotSectorScore 并持久化
 */
export async function analyzeHotSectors(
  stocks: Stock[],
  options: HotSectorAnalyzerOptions = {},
): Promise<DataLayerResult<HotSectorScore[]>> {
  const ruleConfig = options.ruleConfig ?? getDefaultDualStrategyRuleConfig()
  const filtered: string[] = []

  const v6Settled = await Promise.allSettled(
    stocks.map((stock) => dataLayer.v6Scores.get(stock.symbol).catch(() => undefined))
  )
  for (let i = 0; i < stocks.length; i++) {
    const result = v6Settled[i]!
    const v6Score = result.status === 'fulfilled' ? result.value : undefined
    if ((v6Score?.score ?? HOT_SECTOR_THRESHOLDS.SCORE_MIN) >= ruleConfig.hotSectorV6Min) {
      filtered.push(stocks[i]!.symbol)
    }
  }

  const scores = await analyzeBatch(filtered)

  // 动态导入 dataBridge 避免循环依赖（databridge.ts 也引用了 hotSectorAnalyzer）
  const { dataBridge } = await import('@/core/databridge')

  for (const score of scores) {
    if (score.dataVersion == null) {
      logger.warn('[hotSectorAnalyzer] 字段缺失，使用默认值', { field: 'dataVersion', context: `symbol=${score.symbol}` })
    }
    const baseVersion = score.dataVersion ?? 0
    score.dataVersion = baseVersion + 1
    try {
      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.analyzer,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.saveHotSectorScores,
          traceId: `hs-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        },
        score,
      )
      await dataBridge.forward(envelope)
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      logger.error(`[hotSectorAnalyzer] DataBridge.forward failed for ${score.symbol}`, { error: message })
    }
  }

  return { success: true, data: scores }
}

/**
 * 获取指定 symbol 最新的一条 HotSectorScore。
 */
export async function getLatestHotSectorScore(symbol: string): Promise<HotSectorScore | undefined> {
  return dataLayer.hotSectorScores.get(symbol).catch(() => undefined)
}

import { calculateWeightedScore, getEnabledIndustryFactorNames } from '@/config/scoreFactors'
import { dataLayer } from '@/data/dataLayer'
import type { IndustryDimensionScore, IndustryScore } from '@/data/types'
import { getSectorSkillMap } from '@/data/sectorSkillData'
import type { LlmConfig } from '@/config/llmConfig'
import { chat, LlmApiError, LlmConfigError } from '@/services/llm/llmGateway'
import { buildIndustryScorePrompt } from './industryScorePrompt'

const DIMENSION_NAMES = getEnabledIndustryFactorNames()

export interface RunIndustryScoreInput {
  code: string
  files: File[]
  reportText: string
  llmConfig?: Partial<LlmConfig>
}

export type IndustryScoreStep =
  | 'fetchSectorData'
  | 'readSupplementaryFiles'
  | 'prepareReportText'
  | 'llmAnalysis'
  | 'parseScore'
  | 'saveResult'

export interface IndustryScoreStepStatus {
  step: IndustryScoreStep
  status: 'pending' | 'running' | 'done' | 'error'
  message?: string
}

export type IndustryScoreProgressCallback = (status: IndustryScoreStepStatus) => void

function readFileAsText(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => {
      resolve(typeof reader.result === 'string' ? reader.result : '')
    }
    reader.onerror = () => {
      reject(new Error(`读取文件 ${file.name} 失败`))
    }
    reader.readAsText(file)
  })
}

async function readSupplementaryFiles(files: File[]): Promise<string[]> {
  const results = await Promise.all(
    files.map(async (file) => {
      const text = await readFileAsText(file)
      return `文件名: ${file.name}\n内容:\n${text}`
    }),
  )
  return results
}

interface RawDimension {
  name?: string
  score?: number | null
  rationale?: string
  evidence?: string[]
}

interface RawScoreOutput {
  dimensions?: RawDimension[]
  summary?: string
  basis?: string
  missingFields?: string[]
}

function extractJsonFromMarkdown(content: string): string {
  const match = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/)
  if (match && match[1]) {
    return match[1].trim()
  }
  return content.trim()
}

function parseRawScoreOutput(content: string): RawScoreOutput {
  const jsonText = extractJsonFromMarkdown(content)
  try {
    const parsed = JSON.parse(jsonText) as RawScoreOutput
    return parsed
  } catch {
    throw new LlmApiError('LLM 返回内容不是合法 JSON')
  }
}

function normalizeDimensionScore(raw: RawDimension, fallbackName: string): IndustryDimensionScore {
  const name = typeof raw.name === 'string' && raw.name.length > 0
    ? raw.name
    : fallbackName
  const score = typeof raw.score === 'number' ? Math.max(1, Math.min(5, raw.score)) : null
  const rationale = typeof raw.rationale === 'string' ? raw.rationale : '未提供评分依据'
  const evidence = Array.isArray(raw.evidence)
    ? raw.evidence.filter((item): item is string => typeof item === 'string')
    : []

  return {
    name,
    score,
    rationale,
    evidence,
    weight: 1 / DIMENSION_NAMES.length,
  }
}

function normalizeScoreOutput(raw: RawScoreOutput): {
  dimensions: IndustryDimensionScore[]
  summary: string
  basis: string
  missingFields: string[]
} {
  const rawDimensions = Array.isArray(raw.dimensions) ? raw.dimensions : []
  const dimensions = DIMENSION_NAMES.map((expectedName) => {
    const found = rawDimensions.find(
      (d) => typeof d.name === 'string' && d.name.includes(expectedName),
    )
    return found
      ? normalizeDimensionScore(found, expectedName)
      : normalizeDimensionScore({ name: expectedName, score: null, rationale: '数据缺失，未参与评分' }, expectedName)
  })

  const summary = typeof raw.summary === 'string' ? raw.summary : '未生成总结'
  const basis = typeof raw.basis === 'string' ? raw.basis : '未生成评分依据'
  const missingFields = Array.isArray(raw.missingFields)
    ? raw.missingFields.filter((item): item is string => typeof item === 'string')
    : []

  return { dimensions, summary, basis, missingFields }
}

function calculateOverallScore(dimensions: IndustryDimensionScore[]): number | null {
  return calculateWeightedScore(
    dimensions.map((d) => ({ name: d.name, score: d.score })),
    getEnabledIndustryFactorNames().map((name) => ({ name, weight: 1, enabled: true } as const)),
  )
}

export async function runIndustryScore(
  input: RunIndustryScoreInput,
  onProgress?: IndustryScoreProgressCallback,
): Promise<{ success: boolean; data?: IndustryScore; error?: string }> {
  const { code, files, reportText, llmConfig } = input

  let currentStep: IndustryScoreStep = 'fetchSectorData'

  const reportProgress = (step: IndustryScoreStep, status: IndustryScoreStepStatus['status'], message?: string): void => {
    onProgress?.({ step, status, message })
  }

  try {
    currentStep = 'fetchSectorData'
    reportProgress(currentStep, 'running', '读取行业 SKILL 数据...')
    const sectorMap = getSectorSkillMap()
    const sector = sectorMap[code]
    if (!sector) {
      throw new LlmConfigError(`未找到行业/赛道: ${code}`)
    }
    reportProgress(currentStep, 'done', `已读取 ${sector.name}`)

    currentStep = 'readSupplementaryFiles'
    reportProgress(currentStep, 'running', `读取 ${files.length} 个补充文件...`)
    const supplementaryTexts = await readSupplementaryFiles(files)
    reportProgress(currentStep, 'done', `已读取 ${files.length} 个文件`)

    currentStep = 'prepareReportText'
    reportProgress(currentStep, 'running', '整理行业报告资料...')
    reportProgress(currentStep, 'done', reportText ? '已整理报告资料' : '未提供报告资料')

    currentStep = 'llmAnalysis'
    reportProgress(currentStep, 'running', '调用大模型进行行业评分分析...')
    const messages = buildIndustryScorePrompt({ sector, supplementaryTexts, reportText })
    const response = await chat(messages, llmConfig)
    reportProgress(currentStep, 'done', `模型 ${response.model} 返回分析结果`)

    currentStep = 'parseScore'
    reportProgress(currentStep, 'running', '解析评分结果...')
    const rawOutput = parseRawScoreOutput(response.content)
    const normalized = normalizeScoreOutput(rawOutput)
    const overallScore = calculateOverallScore(normalized.dimensions)
    reportProgress(currentStep, 'done', overallScore !== null ? `综合分 ${overallScore}` : '综合分无法计算')

    const score: IndustryScore = {
      code,
      name: sector.name,
      overallScore,
      dimensionScores: normalized.dimensions,
      summary: normalized.summary,
      basis: normalized.basis,
      missingFields: normalized.missingFields,
      sectorSnapshot: {
        composite: sector.composite,
        recommendation: sector.recommendation,
        positionPct: sector.positionPct,
        subTracks: sector.subTracks.map((track) => track.name),
      },
      configSnapshot: {
        model: llmConfig?.model ?? '',
        baseURL: llmConfig?.baseURL ?? '',
      },
      modelResponse: response.content,
      scoredAt: Date.now(),
    }

    currentStep = 'saveResult'
    reportProgress(currentStep, 'running', '保存评分结果...')
    const saveResult = await dataLayer.industryScores.save(score)
    if (!saveResult.success) {
      reportProgress(currentStep, 'error', saveResult.error ?? '保存失败')
      return { success: false, error: saveResult.error ?? '保存评分结果失败' }
    }
    reportProgress(currentStep, 'done', '评分结果已保存')

    return { success: true, data: score }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    if (error instanceof LlmConfigError || error instanceof LlmApiError) {
      reportProgress(currentStep, 'error', message)
    } else {
      reportProgress(currentStep, 'error', message)
    }
    return { success: false, error: message }
  }
}

import { calculateWeightedScore, getEnabledStockFactorNames } from '@/config/scoreFactors'
import { dataLayer } from '@/data/dataLayer'
import type { DataLayerResult, DimensionScore, IntelligentScore, Stock } from '@/data/types'
import type { LlmConfig, LlmTransparencyConfig } from '@/config/llmConfig'
import { chat, LlmApiError } from '@/services/llm/llmGateway'
import { buildIntelligentScorePrompt } from './intelligentScorePrompt'

const DIMENSION_NAMES = getEnabledStockFactorNames()

export interface RunIntelligentScoreInput {
  symbol: string
  files: File[]
  reportText: string
  llmConfig?: Partial<LlmConfig>
  /** LLM 透明度配置（包含 enableLlm 和 factorOverrides） */
  transparencyConfig?: LlmTransparencyConfig
}

export interface ScoreStepStatus {
  step: ScoreStep
  status: 'pending' | 'running' | 'done' | 'error'
  message?: string
}

export type ScoreStep =
  | 'fetchBasicData'
  | 'readSupplementaryFiles'
  | 'prepareReportText'
  | 'llmAnalysis'
  | 'parseScore'
  | 'saveResult'

export type ScoreProgressCallback = (status: ScoreStepStatus) => void

function readFileAsText(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => {
      resolve(typeof reader.result === 'string' ? reader.result : '')
    }
    reader.onerror = () => {
      reject(new Error(`读取文件 ${file.name} 失败`))
    }
    reader.readAsText(file)
  })
}

async function readSupplementaryFiles(files: File[]): Promise<string[]> {
  const results = await Promise.all(
    files.map(async (file) => {
      const text = await readFileAsText(file)
      return `文件名: ${file.name}\n内容:\n${text}`
    }),
  )
  return results
}

function detectMissingBasicFields(stock: Stock | undefined): string[] {
  if (!stock) return ['stock']
  const missing: string[] = []
  if (stock.price === undefined || stock.price === null) missing.push('price')
  if (stock.pe === undefined || stock.pe === null) missing.push('pe')
  if (stock.pb === undefined || stock.pb === null) missing.push('pb')
  if (stock.roe === undefined || stock.roe === null) missing.push('roe')
  if (stock.marketCap === undefined || stock.marketCap === null) missing.push('marketCap')
  return missing
}

interface RawDimension {
  name?: string
  score?: number | null
  rationale?: string
  evidence?: string[]
}

interface RawScoreOutput {
  dimensions?: RawDimension[]
  summary?: string
  basis?: string
  missingFields?: string[]
}

function extractJsonFromMarkdown(content: string): string {
  const match = content.match(/```(?:json)?\s*([\s\S]*?)\s*```/)
  if (match && match[1]) {
    return match[1].trim()
  }
  return content.trim()
}

function parseRawScoreOutput(content: string): RawScoreOutput {
  const jsonText = extractJsonFromMarkdown(content)
  try {
    const parsed = JSON.parse(jsonText) as RawScoreOutput
    return parsed
  } catch {
    throw new LlmApiError('LLM 返回内容不是合法 JSON')
  }
}

function normalizeDimensionScore(raw: RawDimension, fallbackName: string): DimensionScore {
  const name = typeof raw.name === 'string' && raw.name.length > 0
    ? raw.name
    : fallbackName
  const score = typeof raw.score === 'number' ? Math.max(1, Math.min(5, raw.score)) : null
  const rationale = typeof raw.rationale === 'string' ? raw.rationale : '未提供评分依据'
  const evidence = Array.isArray(raw.evidence)
    ? raw.evidence.filter((item): item is string => typeof item === 'string')
    : []

  return {
    name,
    score,
    rationale,
    evidence,
    weight: 1 / DIMENSION_NAMES.length,
  }
}

function normalizeScoreOutput(raw: RawScoreOutput): {
  dimensions: DimensionScore[]
  summary: string
  basis: string
  missingFields: string[]
} {
  const rawDimensions = Array.isArray(raw.dimensions) ? raw.dimensions : []
  const dimensions = DIMENSION_NAMES.map((expectedName) => {
    const found = rawDimensions.find(
      (d) => typeof d.name === 'string' && d.name.includes(expectedName),
    )
    return found
      ? normalizeDimensionScore(found, expectedName)
      : normalizeDimensionScore({ name: expectedName, score: null, rationale: '数据缺失，未参与评分' }, expectedName)
  })

  const summary = typeof raw.summary === 'string' ? raw.summary : '未生成总结'
  const basis = typeof raw.basis === 'string' ? raw.basis : '未生成评分依据'
  const missingFields = Array.isArray(raw.missingFields)
    ? raw.missingFields.filter((item): item is string => typeof item === 'string')
    : []

  return { dimensions, summary, basis, missingFields }
}

function calculateOverallScore(dimensions: DimensionScore[]): number | null {
  return calculateWeightedScore(
    dimensions.map((d) => ({ name: d.name, score: d.score })),
    getEnabledStockFactorNames().map((name) => ({ name, weight: 1, enabled: true } as const)),
  )
}

export async function runIntelligentScore(
  input: RunIntelligentScoreInput,
  onProgress?: ScoreProgressCallback,
): Promise<DataLayerResult<IntelligentScore>> {
  const { symbol, files, reportText, llmConfig } = input

  const reportProgress = (step: ScoreStep, status: ScoreStepStatus['status'], message?: string): void => {
    onProgress?.({ step, status, message })
  }

  let currentStep: ScoreStep = 'fetchBasicData'

  try {
    currentStep = 'fetchBasicData'
    reportProgress(currentStep, 'running', '读取基础数据...')
    const stock = await dataLayer.stocks.get(symbol)
    const basicMissingFields = detectMissingBasicFields(stock)
    reportProgress(currentStep, 'done', stock ? `已读取 ${stock.name}(${stock.symbol})` : '未找到基础数据')

    currentStep = 'readSupplementaryFiles'
    reportProgress(currentStep, 'running', `读取 ${files.length} 个补充文件...`)
    const supplementaryTexts = await readSupplementaryFiles(files)
    reportProgress(currentStep, 'done', `已读取 ${files.length} 个文件`)

    currentStep = 'prepareReportText'
    reportProgress(currentStep, 'running', '整理行业报告资料...')
    reportProgress(currentStep, 'done', reportText ? '已整理报告资料' : '未提供报告资料')

    currentStep = 'llmAnalysis'
    reportProgress(currentStep, 'running', '调用大模型进行评分分析...')
    const messages = buildIntelligentScorePrompt({ symbol, stock, supplementaryTexts, reportText })
    const response = await chat(messages, llmConfig)
    reportProgress(currentStep, 'done', `模型 ${response.model} 返回分析结果`)

    currentStep = 'parseScore'
    reportProgress(currentStep, 'running', '解析评分结果...')
    const rawOutput = parseRawScoreOutput(response.content)
    const normalized = normalizeScoreOutput(rawOutput)
    const overallScore = calculateOverallScore(normalized.dimensions)
    reportProgress(currentStep, 'done', overallScore !== null ? `综合分 ${overallScore}` : '综合分无法计算')

    const finalMissingFields = Array.from(
      new Set([...basicMissingFields, ...normalized.missingFields]),
    )

    const score: IntelligentScore = {
      symbol,
      overallScore,
      dimensionScores: normalized.dimensions,
      summary: normalized.summary,
      basis: normalized.basis,
      missingFields: finalMissingFields,
      sourceSnapshot: {
        stock,
        fileNames: files.map((file) => file.name),
        reportLength: reportText.length,
      },
      configSnapshot: {
        model: llmConfig?.model ?? '',
        baseURL: llmConfig?.baseURL ?? '',
      },
      modelResponse: response.content,
      dataVersion: stock?.dataVersion ?? 0,
      scoredAt: Date.now(),
    }

    currentStep = 'saveResult'
    reportProgress(currentStep, 'running', '保存评分结果...')
    const saveResult = await dataLayer.intelligentScores.save(score)
    if (!saveResult.success) {
      reportProgress(currentStep, 'error', saveResult.error ?? '保存失败')
      return { success: false, error: saveResult.error ?? '保存评分结果失败' }
    }
    reportProgress(currentStep, 'done', '评分结果已保存')

    return { success: true, data: score }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    reportProgress(currentStep, 'error', message)
    return { success: false, error: message }
  }
}

/**
 * RotationSignalDetector — 轮动信号检测器
 *
 * 对价值洼地候选板块检测轮动信号，三项条件全满足时触发：
 * 1. 成交量突破 20% 历史分位
 * 2. 资金连续 N 日净流入
 * 3. 技术指标出现金叉
 *
 * 输出：RotationSignal { triggered: boolean, strength: 'weak'|'medium'|'strong' }
 *
 * @module services/scoring/rotationSignalDetector
 * @created 2026-06-27 - 基于双策略体系修正
 */

import { getDefaultDualStrategyRuleConfig, type DualStrategyRuleConfig } from '@/config/dualStrategyRules'
import { dataLayer } from '@/data/dataLayer'
import type { DataLayerResult, KlineBar, Signal, ValuePitScore } from '@/data/types'
import { getLogger } from '@/lib/logger'
import { ROTATION_SIGNAL_THRESHOLDS } from '@/config/thresholds'

const logger = getLogger()

// ============================================================
// 常量（P0-09: 提取魔法数字）
// ============================================================

/** 板块聚合时取近 N 日数据窗口 */
const RECENT_DATA_WINDOW_DAYS = 60

/** 个股参与聚合的最小历史天数门槛 */
const MIN_HISTORY_DAYS = 20

/** 板块聚合时最多取前 N 只股票（避免过重计算） */
const MAX_SECTOR_STOCKS_FOR_AGGREGATION = 10

// ============================================================
// 输入类型
// ============================================================

export interface VolumeData {
  /** 历史成交量序列（按时间升序） */
  history: number[]
}

export interface CapitalFlowData {
  /** 每日资金净流入序列（正值=流入，按时间升序） */
  dailyNetFlow: number[]
}

export interface GoldenCrossData {
  /** 收盘价序列（按时间升序） */
  closes: number[]
  /** 短期均线周期，默认 5 */
  shortPeriod?: number
  /** 长期均线周期，默认 20 */
  longPeriod?: number
}

/** 轮动信号检测聚合输入 */
export interface RotationSignalInput {
  sectorId: string
  volume: VolumeData
  capitalFlow: CapitalFlowData
  goldenCross: GoldenCrossData
}

// ============================================================
// 输出类型
// ============================================================

export interface RotationSignal {
  sectorId: string
  triggered: boolean
  conditions: {
    volumeBreakthrough: boolean
    capitalInflow: boolean
    goldenCross: boolean
  }
  strength: 'weak' | 'medium' | 'strong'
  detectedAt: number
}

// ============================================================
// 检测函数
// ============================================================

/**
 * 检测成交量是否突破指定历史分位。
 *
 * @param data 成交量数据
 * @param percentile 目标分位阈值（默认 20，即突破 20% 历史分位）
 * @returns 是否突破
 */
export function checkVolumeBreakthrough(
  data: VolumeData,
  percentile: number = 20,
): boolean {
  if (data.history.length < 5) {
    return false
  }

  // 取最近 5 日平均成交量
  const recent = data.history.slice(-5)
  const recentAvg = recent.reduce((a, b) => a + b, 0) / recent.length

  // 计算历史成交量的分位值
  const sorted = [...data.history].sort((a, b) => a - b)
  const idx = Math.ceil((percentile / 100) * sorted.length) - 1
  const threshold = sorted[Math.max(0, idx)]!

  // 近期均量超过分位阈值即为突破
  return recentAvg > threshold
}

/**
 * 检测资金是否连续 N 日净流入。
 *
 * @param data 资金流数据
 * @param days 连续流入天数阈值（默认 3）
 * @returns 是否满足
 */
export function checkCapitalInflow(
  data: CapitalFlowData,
  days: number = 3,
): boolean {
  if (data.dailyNetFlow.length < days) {
    return false
  }

  // 检查最近 N 天是否全部为正
  const recent = data.dailyNetFlow.slice(-days)
  return recent.every((flow) => flow > 0)
}

/**
 * 检测是否出现技术金叉。
 *
 * 金叉定义：短期均线上穿长期均线，且当前价格在短期均线之上。
 *
 * @param data 金叉检测数据
 * @returns 是否出现金叉
 */
export function checkGoldenCross(data: GoldenCrossData): boolean {
  const shortPeriod = data.shortPeriod ?? ROTATION_SIGNAL_THRESHOLDS.GOLDEN_CROSS_SHORT_PERIOD_DEFAULT
  const longPeriod = data.longPeriod ?? ROTATION_SIGNAL_THRESHOLDS.GOLDEN_CROSS_LONG_PERIOD_DEFAULT

  if (data.closes.length < longPeriod + 1) {
    return false
  }

  // 今日短期均线
  const todayShort = data.closes
    .slice(-shortPeriod)
    .reduce((a, b) => a + b, 0) / shortPeriod

  // 今日长期均线
  const todayLong = data.closes
    .slice(-longPeriod)
    .reduce((a, b) => a + b, 0) / longPeriod

  // 昨日短期均线
  const yesterdayShort = data.closes
    .slice(-(shortPeriod + 1), -1)
    .reduce((a, b) => a + b, 0) / shortPeriod

  // 昨日长期均线
  const yesterdayLong = data.closes
    .slice(-(longPeriod + 1), -1)
    .reduce((a, b) => a + b, 0) / longPeriod

  // 金叉：昨日短期 ≤ 长期，今日短期 > 长期，且当前价格 > 短期均线
  const currentPrice = data.closes[data.closes.length - 1]!
  const crossed = yesterdayShort <= yesterdayLong && todayShort > todayLong

  return crossed && currentPrice > todayShort
}

// ============================================================
// 信号强度判定
// ============================================================

/**
 * 根据成交量突破幅度判定信号强度。
 */
function getVolumeStrength(volume: VolumeData): 'weak' | 'medium' | 'strong' {
  if (volume.history.length < 5) return 'weak'

  const recent = volume.history.slice(-5)
  const recentAvg = recent.reduce((a, b) => a + b, 0) / recent.length
  const sorted = [...volume.history].sort((a, b) => a - b)

  const p50Idx = Math.ceil(0.5 * sorted.length) - 1
  const p80Idx = Math.ceil(0.8 * sorted.length) - 1
  const median = sorted[Math.max(0, p50Idx)]!
  const p80 = sorted[Math.max(0, p80Idx)]!

  if (recentAvg > p80) return 'strong'
  if (recentAvg > median) return 'medium'
  return 'weak'
}

// ============================================================
// 综合检测
// ============================================================

/**
 * 综合检测三个轮动触发条件，输出 RotationSignal。
 */
export function detect(input: RotationSignalInput): RotationSignal {
  const volumeBreakthrough = checkVolumeBreakthrough(input.volume)
  const capitalInflow = checkCapitalInflow(input.capitalFlow)
  const goldenCross = checkGoldenCross(input.goldenCross)

  const triggered = volumeBreakthrough && capitalInflow && goldenCross

  // 信号强度由成交量突破幅度主导
  let strength: RotationSignal['strength'] = 'weak'
  if (triggered) {
    strength = getVolumeStrength(input.volume)
  }

  return {
    sectorId: input.sectorId,
    triggered,
    conditions: {
      volumeBreakthrough,
      capitalInflow,
      goldenCross,
    },
    strength,
    detectedAt: Date.now(),
  }
}

// ============================================================
// 数据获取与编排
// ============================================================

/**
 * 根据 sectorId 从 dataLayer 获取板块数据并执行轮动信号检测。
 *
 * sectorId 匹配逻辑：
 * 1. 从 stocks 表查找属于该板块的股票
 * 2. 聚合板块内股票的成交量/资金流数据
 * 3. 执行三项检测
 */
export async function detectBySector(sectorId: string): Promise<RotationSignal | null> {
  try {
    logger.info(`[rotationSignalDetector] 开始检测板块 ${sectorId}`)

    // 获取板块内所有股票
    const allStocks = await dataLayer.stocks.list()
    const sectorStocks = allStocks.filter(
      (s) =>
        s.sector === sectorId ||
        s.industryCode === sectorId ||
        (s.sector !== undefined && s.sector.includes(sectorId)),
    )

    if (sectorStocks.length === 0) {
      logger.warn(`[rotationSignalDetector] 板块 ${sectorId} 无股票数据`)
      return null
    }

    // P0-09: 按日期对齐聚合板块内个股的成交量、资金流和收盘价
    // 旧实现按索引 i 聚合，但不同股票 recent 数组长度可能不同（历史不足 60 天），
    // 导致索引 i 对不同股票代表不同日期，产生时间错位。
    const stockBarMaps = new Map<string, Map<string, KlineBar>>()
    const allDates = new Set<string>()
    let count = 0

    for (const stock of sectorStocks.slice(0, MAX_SECTOR_STOCKS_FOR_AGGREGATION)) {
      const quotes = await dataLayer.dailyQuotes.get(stock.symbol).catch(() => undefined)
      if (!quotes || quotes.history.length < MIN_HISTORY_DAYS) {
        logger.warn(`[rotationSignalDetector] 股票历史数据不足，跳过`, {
          symbol: stock.symbol,
          historyLength: quotes?.history.length ?? 0,
          minLength: MIN_HISTORY_DAYS,
        })
        continue
      }

      // 取近 N 日数据，建立 date -> bar 映射
      const barMap = new Map<string, KlineBar>()
      for (const bar of quotes.history.slice(-RECENT_DATA_WINDOW_DAYS)) {
        barMap.set(bar.date, bar)
        allDates.add(bar.date)
      }
      stockBarMaps.set(stock.symbol, barMap)
      count++
    }

    // 按日期排序后聚合，确保不同股票在同一日期对齐
    const sortedDates = Array.from(allDates).sort()
    const sectorVolumes: number[] = new Array(sortedDates.length).fill(0)
    const sectorFlows: number[] = new Array(sortedDates.length).fill(0)
    const closes: number[] = new Array(sortedDates.length).fill(0)

    for (let i = 0; i < sortedDates.length; i++) {
      const date = sortedDates[i]!
      for (const [, barMap] of stockBarMaps) {
        const bar = barMap.get(date)
        if (bar) {
          sectorVolumes[i]! += bar.volume
          // 用收盘价-开盘价作为资金流代理（正=流入）
          const flow = (bar.close - bar.open) * bar.volume
          sectorFlows[i]! += flow
          closes[i]! += bar.close
        }
      }
    }

    if (sectorVolumes.length < MIN_HISTORY_DAYS) {
      logger.warn(`[rotationSignalDetector] 板块 ${sectorId} 数据不足`)
      return null
    }

    const result = detect({
      sectorId,
      volume: { history: sectorVolumes },
      capitalFlow: { dailyNetFlow: sectorFlows },
      goldenCross: {
        closes: count > 0 ? closes.map((c) => c / count) : [],
      },
    })

    logger.info(
      `[rotationSignalDetector] 板块 ${sectorId} 检测完成: triggered=${result.triggered}, strength=${result.strength}`,
    )
    return result
  } catch (error) {
    logger.error(`[rotationSignalDetector] 检测板块 ${sectorId} 失败`, { error: error instanceof Error ? error.message : String(error) })
    return null
  }
}

export interface RotationSignalDetectorOptions {
  ruleConfig?: DualStrategyRuleConfig
}

export interface RotationSignalResult {
  signals: Signal[]
  watchlistCandidates: Array<{ symbol: string; reason: string }>
}

/**
 * 对价值洼地候选列表检测轮动信号。
 *
 * 只处理 action 为 wait/probe 的候选；immediate/ignore 被跳过。
 * 对每只候选股票检测：成交量放大、价格站稳 MA20、板块资金流入。
 * 全部满足则生成 buy_rotation 信号，否则加入观察清单。
 */
export async function detectRotationSignals(
  valuePitScores: ValuePitScore[],
  options: RotationSignalDetectorOptions = {},
): Promise<DataLayerResult<RotationSignalResult>> {
  const ruleConfig = options.ruleConfig ?? getDefaultDualStrategyRuleConfig()
  const signals: Signal[] = []
  const watchlistCandidates: Array<{ symbol: string; reason: string }> = []

  const candidates = valuePitScores.filter(
    (s) => s.action === 'wait' || s.action === 'probe',
  )

  for (const score of candidates) {
    const stock = await dataLayer.stocks.get(score.symbol).catch(() => undefined)
    if (!stock) {
      watchlistCandidates.push({ symbol: score.symbol, reason: '基础数据缺失，无法检测轮动信号' })
      continue
    }

    const quotes = await dataLayer.dailyQuotes.get(score.symbol).catch(() => undefined)
    if (!quotes || quotes.history.length < 25) {
      watchlistCandidates.push({ symbol: score.symbol, reason: '行情数据不足，无法检测量价条件' })
      continue
    }

    const closes = quotes.history.map((b) => b.close)
    const volumes = quotes.history.map((b) => b.volume)

    const recentVolumes = volumes.slice(-5)
    const priorVolumes = volumes.slice(-25, -5)

    const recentAvgVolume = recentVolumes.reduce((a, b) => a + b, 0) / recentVolumes.length
    const priorAvgVolume = priorVolumes.length > 0
      ? priorVolumes.reduce((a, b) => a + b, 0) / priorVolumes.length
      : 0
    const volumeRatio = priorAvgVolume > 0 ? recentAvgVolume / priorAvgVolume : 0

    const ma20 = closes.slice(-20).reduce((a, b) => a + b, 0) / 20
    const latestPrice = closes[closes.length - 1]!
    const priceToMA20 = ma20 > 0 ? latestPrice / ma20 : 0

    const sector = stock.sector ?? stock.industryCode ?? ''
    const rotationScores = await dataLayer.rotationScores.listBySector(sector).catch(() => [])
    const latestRotation = rotationScores.length > 0
      ? rotationScores.sort((a, b) => b.scoreDate.localeCompare(a.scoreDate))[0]
      : undefined

    const fundFlowOk = latestRotation !== undefined && latestRotation.f2Zijin >= 20

    const volumeOk = volumeRatio >= ruleConfig.rotationVolumeSurgeRatio
    const priceOk = priceToMA20 >= ruleConfig.rotationPriceToMA20Threshold

    if (volumeOk && priceOk && fundFlowOk) {
      signals.push({
        id: `rot-${score.symbol}-${Date.now()}`,
        symbol: score.symbol,
        direction: 'buy',
        type: 'buy_rotation',
        strategy: 'rotation',
        confidence: Math.min(1, Math.round(score.score) / 5),
        rationale: `轮动信号触发：量比 ${volumeRatio.toFixed(2)}，价格/MA20 ${priceToMA20.toFixed(3)}，板块资金因子 ${latestRotation?.f2Zijin ?? 0}`,
        snapshot: {
          pePercentile: score.dimensions.valuation,
          volumeRatio,
        },
        createdAt: Date.now(),
      })
    } else {
      const reasons: string[] = []
      if (!volumeOk) reasons.push(`量比 ${volumeRatio.toFixed(2)} 低于阈值 ${ruleConfig.rotationVolumeSurgeRatio}`)
      if (!priceOk) reasons.push(`价格/MA20 ${priceToMA20.toFixed(3)} 低于阈值 ${ruleConfig.rotationPriceToMA20Threshold}`)
      if (!fundFlowOk) reasons.push('板块资金流入不足')
      watchlistCandidates.push({ symbol: score.symbol, reason: reasons.join('；') })
    }
  }

  return { success: true, data: { signals, watchlistCandidates } }
}

/**
 * L0 STEEP 宏观扫描 + L1 护城河 + L2 竞品 计算器
 *
 * 按 SKILL v4.3 评分 rubric 实现。
 */

import { getLogger } from '@/lib/logger'
import type { LayerInput, LayerScore, LayerCalculator } from '../types'
import type { LayerId } from '../types'
import { LAYER_LABELS } from '../types'
import { V6_CALCULATOR_THRESHOLDS } from '@/config/thresholds'
import { safeArrayGet, safeFirst, safeLast } from '@/utils/precision'

const logger = getLogger()

// ============================================================
// L0 STEEP 宏观扫描 — 权重 8%
// ============================================================

interface SteepSubItem {
  name: string
  score: number  // 0-10
  evidence: string
}

function evaluateSTEEP(input: LayerInput): { subs: SteepSubItem[]; score: number; summary: string } {
  const { stock, financials } = input
  const sector = (stock.sector ?? '').toLowerCase()
  const subs: SteepSubItem[] = []

  // S-社会：人口结构/消费习惯/ESG
  const isPharma = sector.includes('医药') || sector.includes('药') || sector.includes('生物')
  const isTech = sector.includes('ai') || sector.includes('芯片') || sector.includes('半导体') || sector.includes('科技')
  const isFinance = sector.includes('金融') || sector.includes('银行') || sector.includes('保险')

  subs.push({ name: 'S-人口结构', score: isPharma ? 8 : 6, evidence: isPharma ? '老龄化利好医药' : '中性影响' })
  subs.push({ name: 'S-消费习惯', score: isTech ? 7 : 6, evidence: isTech ? '科技消费升级' : '中性' })
  subs.push({ name: 'S-ESG', score: isTech ? 8 : 6, evidence: isTech ? '科技企业ESG表现较好' : '中性' })

  // T-技术：成熟度/迭代速度/替代风险
  subs.push({ name: 'T-技术成熟度', score: isTech ? 8 : 6, evidence: isTech ? '核心技术处于商业化阶段' : '一般' })
  subs.push({ name: 'T-技术迭代速度', score: isTech ? 7 : 5, evidence: isTech ? '迭代周期1-3年' : '较慢' })
  subs.push({ name: 'T-技术替代风险', score: isTech ? 7 : 6, evidence: isTech ? '远期存在替代风险' : '风险较低' })

  // E-经济：GDP相关性/利率敏感性/通胀传导
  subs.push({ name: 'E-GDP相关性', score: isFinance ? 6 : 5, evidence: isFinance ? '与GDP中等相关' : '弱相关' })
  subs.push({ name: 'E-利率敏感性', score: 6, evidence: '当前利率环境中性' })
  subs.push({ name: 'E-通胀传导', score: isTech ? 7 : 5, evidence: isTech ? '强传导能力' : '一般' })

  // E-环境：碳达峰/碳中和
  subs.push({ name: 'E-双碳政策', score: isTech ? 7 : 6, evidence: isTech ? '间接受益于双碳政策' : '中性' })

  // P-政策：国家战略/财政支持/监管风险
  subs.push({ name: 'P-国家战略', score: isTech ? 9 : 6, evidence: isTech ? '纳入国家战略规划' : '未明确提及' })
  subs.push({ name: 'P-财政支持', score: isTech ? 8 : 5, evidence: isTech ? '有专项资金支持' : '无明确支持' })
  subs.push({ name: 'P-监管风险', score: isFinance ? 5 : 7, evidence: isFinance ? '强监管收紧风险' : '监管风险较低' })

  const avg = subs.reduce((s, x) => s + x.score, 0) / subs.length
  const score = Math.min(V6_CALCULATOR_THRESHOLDS.SCORE_MAX, Math.max(V6_CALCULATOR_THRESHOLDS.SCORE_MIN, avg / V6_CALCULATOR_THRESHOLDS.L0_STEEP_NORMALIZE_DIVISOR)) // 归一化 0-10 → 0-5

  const topPos = subs.filter((s) => s.score >= V6_CALCULATOR_THRESHOLDS.L0_STEEP_POSITIVE_THRESHOLD).slice(0, 3).map((s) => s.name)
  const topNeg = subs.filter((s) => s.score <= V6_CALCULATOR_THRESHOLDS.L0_STEEP_NEGATIVE_THRESHOLD).slice(0, 2).map((s) => s.name)

  let summary = `STEEP 均值 ${avg.toFixed(1)}/10`
  if (topPos.length > 0) summary += `, 利好: ${topPos.join('、')}`
  if (topNeg.length > 0) summary += `, 风险: ${topNeg.join('、')}`

  // 财务数据补充
  if (financials.revenueYoY !== undefined && financials.revenueYoY > V6_CALCULATOR_THRESHOLDS.L0_REVENUE_YOY_HIGH) {
    summary += ', 营收高增印证行业景气'
  }

  return { subs, score, summary }
}

export const L0MacroCalculator: LayerCalculator = {
  layerId: 'l0' as LayerId,
  async calculate(input: LayerInput): Promise<LayerScore> {
    const { config } = input
    const weight = config.weights.l0
    const { subs, score, summary } = evaluateSTEEP(input)

    logger.info(`[L0] ${input.stock.symbol}: STEEP score=${score.toFixed(2)}`)

    return {
      layerId: 'l0' as LayerId,
      layerName: LAYER_LABELS.l0 ?? 'L0 STEEP 宏观扫描',
      score: Math.round(score * 100) / 100,
      summary,
      risks: subs.filter((s) => s.score <= V6_CALCULATOR_THRESHOLDS.L0_STEEP_NEGATIVE_THRESHOLD).map((s) => `${s.name}: ${s.evidence}`),
      evidence: subs.slice(0, 5).map((s) => `${s.name}: ${s.score}/10`),
      weight,
      weightedScore: score * weight,
      dataSources: ['宏观数据', '行业报告'],
    }
  },
}

// ============================================================
// L1 护城河分析 — 权重 15%
// ============================================================

function evaluateMoat(input: LayerInput): { score: number; summary: string; evidence: string[] } {
  const { stock, financials } = input
  const sector = (stock.sector ?? '').toLowerCase()
  const evidence: string[] = []
  let criteriaMet = 0

  // 技术独占性：研发/营收>10%, 顶尖团队
  if (financials.rdRatio !== undefined && financials.rdRatio > V6_CALCULATOR_THRESHOLDS.L1_MOAT_RD_HIGH) {
    criteriaMet++
    evidence.push(`研发/营收=${(financials.rdRatio * 100).toFixed(1)}%>8%`)
  } else if (financials.rdRatio !== undefined && financials.rdRatio > V6_CALCULATOR_THRESHOLDS.L1_MOAT_RD_MEDIUM) {
    criteriaMet += 0.5
    evidence.push(`研发/营收=${(financials.rdRatio * 100).toFixed(1)}%>5%`)
  }

  // 客户锁定：NRR>120% 或 使用年限>5年 或 深度嵌入流程
  if (financials.customerConcentration !== undefined && financials.customerConcentration < V6_CALCULATOR_THRESHOLDS.L1_MOAT_CUSTOMER_CONCENTRATION_LOW) {
    criteriaMet += 0.5
    evidence.push(`客户集中度低=${(financials.customerConcentration * 100).toFixed(0)}%`)
  }

  // 规模效应：翻倍成本降>15% 或 固定资产竞品3倍+ 或 渠道密度远超
  if (stock.marketCap !== undefined) {
    if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L1_MOAT_MARKET_CAP_LARGE) {
      criteriaMet++
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿，行业龙头`)
    } else if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L1_MOAT_MARKET_CAP_MEDIUM) {
      criteriaMet += 0.5
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿`)
    }
  }

  // 网络效应：双边/多边效应，份额>50%且提升
  const isTech = sector.includes('ai') || sector.includes('芯片') || sector.includes('半导体') || sector.includes('科技')
  if (isTech) {
    criteriaMet += 0.5
    evidence.push('科技行业存在网络效应')
  }

  // 资源独占：稀缺资源垄断/牌照/不可复制区位
  const isPharma = sector.includes('医药') || sector.includes('药') || sector.includes('生物')
  if (isPharma) {
    criteriaMet += 0.5
    evidence.push('医药行业存在专利/牌照壁垒')
  }

  // 满足4条=5分, 3条=4分, 2条=3分, 1条=2分, 0条=1分
  const scoreMap = V6_CALCULATOR_THRESHOLDS.L1_MOAT_CRITERIA_SCORE_MAP
  const score = scoreMap[Math.min(4, criteriaMet)] ?? 1

  const strengths = evidence.filter((e) => !e.includes('中性'))
  const summary = `护城河评估: ${criteriaMet.toFixed(1)}/4条标准满足, ${score >= 4 ? '强护城河' : score >= 3 ? '中等护城河' : '弱护城河'}`

  return { score, summary, evidence: strengths }
}

export const L1MoatCalculator: LayerCalculator = {
  layerId: 'l1' as LayerId,
  async calculate(input: LayerInput): Promise<LayerScore> {
    const { config } = input
    const weight = config.weights.l1
    const { score, summary, evidence } = evaluateMoat(input)

    logger.info(`[L1] ${input.stock.symbol}: 护城河 score=${score.toFixed(2)}`)

    return {
      layerId: 'l1' as LayerId,
      layerName: LAYER_LABELS.l1 ?? 'L1 护城河分析',
      score: Math.round(score * 100) / 100,
      summary,
      risks: score < V6_CALCULATOR_THRESHOLDS.L1_MOAT_RISK_THRESHOLD ? ['护城河较弱，需关注竞争压力'] : [],
      evidence,
      weight,
      weightedScore: score * weight,
      dataSources: ['财报数据', '行业分析'],
    }
  },
}

// ============================================================
// L2 竞品格局 — 权重 10%
// ============================================================

function evaluatePeer(input: LayerInput): { score: number; summary: string; evidence: string[] } {
  const { stock, financials } = input
  const evidence: string[] = []
  let dimensionScore = V6_CALCULATOR_THRESHOLDS.L2_PEER_BASELINE_SCORE // 基础分

  // 技术代差：领先2代+2.0, 1代+1.0, 持平0, 落后-1.0
  const sector = (stock.sector ?? '').toLowerCase()
  if (sector.includes('芯片') || sector.includes('半导体') || sector.includes('ai')) {
    dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_TECH_BOOST
    evidence.push('科技赛道，技术领先推断+1.0')
  }

  // 市场份额：龙头>30%扩大+1.5, 稳定+0.5
  if (stock.marketCap !== undefined) {
    if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L2_PEER_LARGE_CAP) {
      dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_LARGE_CAP_BOOST
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿，行业龙头+1.0`)
    } else if (stock.marketCap > V6_CALCULATOR_THRESHOLDS.L2_PEER_MEDIUM_CAP) {
      dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_MEDIUM_CAP_BOOST
      evidence.push(`市值=${(stock.marketCap / 1e8).toFixed(0)}亿，稳定份额+0.5`)
    }
  }

  // 客户认证：量产供货+1.5, 小批量+0.5
  if (financials.revenue !== undefined && financials.revenue > V6_CALCULATOR_THRESHOLDS.L2_PEER_REVENUE_THRESHOLD) {
    dimensionScore += V6_CALCULATOR_THRESHOLDS.L2_PEER_REVENUE_BOOST
    evidence.push(`营收=${financials.revenue.toFixed(0)}亿，量产阶段+0.5`)
  }

  const score = Math.min(V6_CALCULATOR_THRESHOLDS.SCORE_MAX, Math.max(1, dimensionScore))
  const tier = score >= 4 ? '第一梯队领先' : score >= 3.5 ? '并列第一梯队' : score >= 3 ? '第二梯队' : '落后'

  return { score, summary: `竞品评估: ${tier}`, evidence }
}

export const L2PeerCalculator: LayerCalculator = {
  layerId: 'l2' as LayerId,
  async calculate(input: LayerInput): Promise<LayerScore> {
    const { config } = input
    const weight = config.weights.l2
    const { score, summary, evidence } = evaluatePeer(input)

    logger.info(`[L2] ${input.stock.symbol}: 竞品 score=${score.toFixed(2)}`)

    return {
      layerId: 'l2' as LayerId,
      layerName: LAYER_LABELS.l2 ?? 'L2 竞品格局',
