// ============================================================
// 可测试纯函数 — 护城河 / 竞争格局
// ============================================================

/** 护城河评分 */
export function scoreMoat(input: LayerInput): number {
  const { financials, stock } = input
  let score = 3

  if (financials.grossMargin !== undefined) {
    const gm = financials.grossMargin
    if (gm >= 0.60) score = 5
    else if (gm >= 0.40) score = 4.5
    else if (gm >= 0.30) score = 4
    else if (gm >= 0.20) score = 3
    else if (gm >= 0.10) score = 2.5
    else score = 2
  }

  if (financials.revenueYoY !== undefined) {
    if (financials.revenueYoY > 1.0) score += 0.5
    else if (financials.revenueYoY > 0.5) score += 0.25
  }

  if (stock.roe !== undefined) {
    if (stock.roe > 0.20) score += 0.5
    else if (stock.roe > 0.15) score += 0.25
  }

  return Math.min(5, score)
}

/** 竞争格局评分
 * 毛利率趋势通过毛利率水平推断：
 * >40% 视为递增，<20% 视为递减，20%-40% 视为稳定
 */
export function scoreCompetition(input: LayerInput): number {
  const { financials } = input
  const gm = financials.grossMargin
  const growth = financials.revenueYoY

  if (gm === undefined || growth === undefined) return 2.5

  let trend = '稳定'
  if (gm > 0.40) trend = '递增'
  else if (gm < 0.20) trend = '递减'

  if (trend === '递减') {
    if (growth > 0.30) return 4.5
    if (growth > 0.10) return 4
    return 3.5
  }

  if (trend === '递增') {
    if (growth > 0.30) return 4
    if (growth > 0.10) return 3.5
    return 3
  }

  // 稳定
  if (growth > 0.30) return 4
  if (growth > 0.10) return 3.5
  return 3
}

/**
 * L4 情景推演 + L5 T-M矩阵 + L6 Hype周期 计算器
 *
 * 按 SKILL v4.3：
 * - L4：三情景（乐观/基准/悲观）+ 概率加权目标价推导
 * - L5：技术成熟度 × 市场成熟度 双轴矩阵
 * - L6：Gartner Hype Cycle 五阶段定位
 *
 * 权重：L4=8%, L5=5%, L6=7%
 * 类型：半确定性（L4价格计算为确定性，概率/阶段需LLM增强）
 */

import { getLogger } from '@/lib/logger'
import type { LayerInput, LayerScore, LayerCalculator } from '../types'
import type { LayerId } from '../types'
import { LAYER_LABELS } from '../types'
import { V6_CALCULATOR_THRESHOLDS } from '@/config/thresholds'
import { safeArrayGet } from '@/utils/precision'

const logger = getLogger()

// ============================================================
// L4 情景推演 — 权重 8%
// ============================================================

interface Scenario {
  name: string
  /** 概率 */
  probability: number
  /** 预测净利润（亿元） */
  netProfit: number
  /** 预测 PE 倍数 */
  pe: number
  /** 股价中枢 */
  priceTarget: number
}

function buildScenarios(
  currentPrice: number,
  netProfit: number | undefined,
  pe: number | undefined,
  revenueYoY: number | undefined,
): Scenario[] {
  const np = netProfit
  if (np == null) {
    logger.warn('[L4] netProfit is undefined, using conservative estimate')
  }
  const safeNp = np ?? 0
  const basePE = pe ?? V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_BASE_PE
  const growth = revenueYoY ?? V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_BASE_GROWTH

  // 上行：业绩超预期，PE 扩张
  const upNP = safeNp * (1 + Math.max(0.2, growth * 0.5))
  const upPE = basePE * V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_UP_MULTIPLIER
  const upPrice = (upNP / (safeNp || 1)) * currentPrice * (upPE / basePE)

  // 基准：符合预期
  const baseNP = safeNp * (1 + Math.min(0.15, growth * 0.3))
  const basePE_ = basePE
  const basePrice = (baseNP / (safeNp || 1)) * currentPrice

  // 下行：业绩不及预期，PE 收缩
  const downNP = safeNp * (1 - Math.max(0.05, Math.min(0.2, growth * 0.3)))
  const downPE = basePE * V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_DOWN_MULTIPLIER
  const downPrice = (downNP / (safeNp || 1)) * currentPrice * (downPE / basePE)

  return [
    { name: '乐观', probability: V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_BULL_PROB, netProfit: upNP, pe: upPE, priceTarget: upPrice },
    { name: '基准', probability: V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_BASE_PROB, netProfit: baseNP, pe: basePE_, priceTarget: basePrice },
    { name: '悲观', probability: V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_BEAR_PROB, netProfit: downNP, pe: downPE, priceTarget: downPrice },
  ]
}

function scoreScenario(input: LayerInput): { score: number; summary: string; evidence: string[]; scenarios: Scenario[] } {
  const { stock, financials } = input
  const currentPrice = stock.price ?? 1
  const evidence: string[] = []

  const scenarios = buildScenarios(currentPrice, financials.netProfit, stock.pe, financials.revenueYoY)

  // 概率加权合理价
  const weightedPrice = scenarios.reduce((sum, s) => sum + s.priceTarget * s.probability, 0)

  const upScenario = safeArrayGet(scenarios, 0)!
  const downScenario = safeArrayGet(scenarios, 2)!
  const baseScenario = safeArrayGet(scenarios, 1)!

  // 基准上行空间
  const baseUpside = baseScenario.priceTarget > currentPrice
    ? (baseScenario.priceTarget - currentPrice) / currentPrice
    : 0

  // 收益比
  const upGain = (upScenario.priceTarget - currentPrice) * upScenario.probability
  const downLoss = (currentPrice - downScenario.priceTarget) * downScenario.probability
  /** 亏损为零时的最大收益比哨兵值 */
  const MAX_REWARD_RATIO = 999
  /** 盈亏均为零时的默认收益比 */
  const DEFAULT_REWARD_RATIO = 1
  const rewardRatio = downLoss > 0 ? upGain / downLoss : upGain > 0 ? MAX_REWARD_RATIO : DEFAULT_REWARD_RATIO

  let score: number
  if (baseUpside > V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_UPSIDE_TIER1 && rewardRatio > V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_REWARD_RATIO_HIGH) {
    score = 5
  } else if (baseUpside > V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_UPSIDE_TIER1) {
    score = 4.5
  } else if (baseUpside > V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_UPSIDE_TIER2 && rewardRatio > V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_REWARD_RATIO_HIGH) {
    score = 4
  } else if (baseUpside > V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_UPSIDE_TIER2) {
    score = 3.5
  } else if (baseUpside > V6_CALCULATOR_THRESHOLDS.L4_SCENARIO_UPSIDE_TIER3) {
    score = 3
  } else if (baseUpside > 0) {
    score = 2.5
  } else {
    score = 2
  }

  evidence.push(
    `当前价: ${currentPrice.toFixed(2)}`,
    `乐观: ${upScenario.priceTarget.toFixed(2)} (${(upScenario.probability * 100).toFixed(0)}%)`,
    `基准: ${baseScenario.priceTarget.toFixed(2)} (${(baseScenario.probability * 100).toFixed(0)}%)`,
    `悲观: ${downScenario.priceTarget.toFixed(2)} (${(downScenario.probability * 100).toFixed(0)}%)`,
    `概率加权价: ${weightedPrice.toFixed(2)}`,
    `上行空间: ${(baseUpside * 100).toFixed(1)}%, 收益比: ${rewardRatio.toFixed(1)}`,
  )

  const summary = `基准上行 ${(baseUpside * 100).toFixed(0)}% | 收益比 ${rewardRatio.toFixed(1)}x | ${score >= 4 ? '情景积极' : score >= 3 ? '情景中性' : '情景偏弱'}`

  return { score, summary, evidence, scenarios }
}

