]

export function matchIndustry(symbol: string, sector?: string, name?: string): { sectorName: string; relevance: number } | null {
  // 1. 精确代码匹配
  const coreMatch = CORE_STOCK_MAP[symbol]
  if (coreMatch) return { sectorName: coreMatch.sector, relevance: coreMatch.relevance }

  // 2. 关键词匹配
  const searchText = `${sector ?? ''} ${name ?? ''}`.toLowerCase()
  for (const entry of KEYWORD_SECTOR_MAP) {
    if (entry.keywords.some((kw) => searchText.includes(kw.toLowerCase()))) {
      return { sectorName: entry.sector, relevance: entry.relevance }
    }
  }

  return null
}

export function calcSkillNBonus(allocationBias: string): number {
  if (allocationBias.includes('极度超配')) return 0.30
  if (allocationBias.includes('超配')) return 0.15
  return 0.00
}

export const LMinus1Calculator: LayerCalculator & { matchIndustry: typeof matchIndustry; calcSkillNBonus: typeof calcSkillNBonus } = {
  layerId: 'lMinus1' as LayerId,

  async calculate(input: LayerInput): Promise<LayerScore> {
    const { stock, industryScore, config } = input
    const weight = config.weights.lMinus1

    // 如果外部已传入行业评分数据，直接使用
    if (industryScore) {
      const bonus = LMinus1Calculator.calcSkillNBonus(industryScore.allocationBias ?? '')
      const score = Math.min(5, industryScore.skillCScore * industryScore.relevance + bonus)

      logger.info(`[L-1] ${stock.symbol}: 外部行业评分, score=${score.toFixed(2)}`)

      return {
        layerId: 'lMinus1' as LayerId,
        layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
        score: Math.round(score * 100) / 100,
        summary: `${industryScore.sectorName} | SKILL-C ${industryScore.skillCRating}(${industryScore.skillCScore}) | SKILL-N ${industryScore.skillNScore} | 关联度 ${industryScore.relevance}`,
        risks: [],
        evidence: [`SKILL-C: ${industryScore.skillCRating}(${industryScore.skillCScore})`, `SKILL-N: ${industryScore.skillNScore}`, `关联度: ${industryScore.relevance}`],
        weight,
        weightedScore: score * weight,
        dataSources: ['行业 SKILL 分析报告'],
      }
    }

    // 尝试匹配行业
    const matched = LMinus1Calculator.matchIndustry(stock.symbol, stock.sector, stock.name)
    if (!matched) {
      logger.info(`[L-1] ${stock.symbol}: 不在7行业覆盖范围，L-1不纳入`)
      return {
        layerId: 'lMinus1' as LayerId,
        layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
        score: 0,
        summary: '不在7行业覆盖范围（CoWoS/芯片设计/机器人/量子计算/AI应用/航天星链/创新药），L-1不纳入综合评分',
        risks: [],
        evidence: [],
        weight,
        weightedScore: 0,
        dataSources: [],
      }
    }

    const sectorData = INDUSTRY_SCORES[matched.sectorName]
    if (!sectorData) {
      return {
        layerId: 'lMinus1' as LayerId,
        layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
        score: 0,
        summary: `匹配到行业 ${matched.sectorName} 但无评分数据`,
        risks: [],
        evidence: [],
        weight,
        weightedScore: 0,
        dataSources: [],
      }
    }

    const bonus = LMinus1Calculator.calcSkillNBonus(sectorData.allocationBias)
    const score = Math.min(5, sectorData.skillC * matched.relevance + bonus)

    logger.info(`[L-1] ${stock.symbol}: ${matched.sectorName}, SKILL-C=${sectorData.skillC}, 关联度=${matched.relevance}, bonus=${bonus}, score=${score.toFixed(2)}`)

    return {
      layerId: 'lMinus1' as LayerId,
      layerName: LAYER_LABELS.lMinus1 ?? 'L-1 行业评分估值',
      score: Math.round(score * 100) / 100,
      summary: `${matched.sectorName} | ${sectorData.skillCRating} | SKILL-C ${sectorData.skillC} | SKILL-N ${sectorData.skillN} | ${sectorData.allocationBias}`,
      risks: [],
      evidence: [
        `行业: ${matched.sectorName}`,
        `SKILL-C: ${sectorData.skillCRating}(${sectorData.skillC})`,
        `SKILL-N: ${sectorData.skillN}`,
        `关联度: ${matched.relevance}`,
        `配置建议: ${sectorData.allocationBias}`,
      ],
      weight,
      weightedScore: score * weight,
      dataSources: ['行业 SKILL 分析报告'],
    }
  },

  matchIndustry,
  calcSkillNBonus,
}

/**
 * V6 评分引擎核心
 *
 * 设计原则：
 * - 零硬编码：所有阈值/权重/公式参数从 config 注入
 * - Backtestable：注入历史行情数据 → 输出历史评分
 * - OfflineMode：完全脱离网络运行（规则引擎层）
 * - AuditTrail：每层评分的完整审计链路
 */

import { getLogger } from '@/lib/logger'
import type {
  LayerId, LayerInput, LayerScore, CompositeScore, ScoreAuditTrail,
  AuditEntry, V6ScoreInput, LayerCalculator,
} from './types'
import { ALL_LAYER_IDS, LAYER_LABELS } from './types'
import { buildFactorContributions } from './factorContributions'
import type { V6ScoreEngineConfig, V6ScoreConfigOverride } from './config'
import { DEFAULT_ENGINE_CONFIG } from './config'

const logger = getLogger()
const ENGINE_VERSION = 'v6-engine-v1.0.0'

/**
 * 评分清理化工具函数
 * 
 * 处理边界条件：
 * - NaN/undefined → 0
 * - Infinity → 5（正无穷）或 0（负无穷）
 * - 超出 [0, 5] 范围 → 截断到边界
 * - 记录警告日志便于排查
 */
function sanitizeScore(score: unknown, layerId: string, context: string): number {
  if (typeof score !== 'number' || Number.isNaN(score)) {
    logger.warn(`[V6ScoreEngine] ${layerId} ${context}: 无效评分 ${String(score)}，降级为 0`)
    return 0
  }
  if (score === Infinity) {
    logger.warn(`[V6ScoreEngine] ${layerId} ${context}: 正无穷评分，截断为 5`)
    return 5
  }
  if (score === -Infinity) {
    logger.warn(`[V6ScoreEngine] ${layerId} ${context}: 负无穷评分，截断为 0`)
    return 0
  }
  if (score < 0) {
    logger.warn(`[V6ScoreEngine] ${layerId} ${context}: 负数评分 ${score}，截断为 0`)
    return 0
  }
  if (score > 5) {
    logger.warn(`[V6ScoreEngine] ${layerId} ${context}: 超范围评分 ${score}，截断为 5`)
    return 5
  }
  return score
}

// ============================================================
// V6ScoreEngine
// ============================================================

export class V6ScoreEngine {
  private config: V6ScoreEngineConfig
  private calculators: Map<LayerId, LayerCalculator> = new Map()
  private auditTrail: ScoreAuditTrail | null = null

  constructor(override?: V6ScoreConfigOverride) {
    this.config = { ...DEFAULT_ENGINE_CONFIG, ...override }
    logger.info(`[V6ScoreEngine] Initialized v${ENGINE_VERSION}, offlineMode=${this.config.offlineMode}`)
  }

  /** 注册层计算器 */
  registerCalculator(calculator: LayerCalculator): this {
    this.calculators.set(calculator.layerId, calculator)
    return this
  }

  /** 批量注册计算器 */
  registerCalculators(calculators: LayerCalculator[]): this {
    for (const calc of calculators) {
      this.calculators.set(calc.layerId, calc)
    }
    return this
  }

  /** 获取当前配置 */
  getConfig(): V6ScoreEngineConfig {
    return { ...this.config }
  }

  /** 更新配置 */
  updateConfig(override: V6ScoreConfigOverride): void {
    this.config = { ...this.config, ...override }
  }

  // ============================================================
  // 核心计算流程
  // ============================================================

  /** 计算单层得分 */
  async calculateLayer(layerId: LayerId, input: LayerInput): Promise<LayerScore> {
    const calculator = this.calculators.get(layerId)
    if (!calculator) {
      logger.warn(`[V6ScoreEngine] No calculator registered for ${layerId}, returning placeholder`)
      return this.placeholderLayer(layerId, input)
    }

    const audit: AuditEntry[] = []

    if (this.config.auditEnabled) {
      audit.push({
        timestamp: Date.now(),
        layerId,
        step: 'start',
        input: { symbol: input.stock.symbol, hasIndustryScore: input.industryScore !== undefined },
        output: {},
      })
    }

    try {
      const result = await calculator.calculate(input)

      // 防御性校验：验证计算器返回的 score 是否有效
      const sanitizedScore = sanitizeScore(result.score, layerId, 'calculateLayer 结果校验')

      const sanitizedResult = {
        ...result,
        score: sanitizedScore,
        weightedScore: sanitizedScore * (result.weight ?? (() => {
          logger.warn('[V6Engine] 字段缺失，使用默认值', { field: 'weight', context: `layer=${layerId}` })
          return 0
        })()),
      }

      if (this.config.auditEnabled) {
        audit.push({
          timestamp: Date.now(),
          layerId,
          step: 'complete',
          input: { score: result.score },
          output: { score: sanitizedScore, summary: sanitizedResult.summary },
          formula: `calculator.${layerId}.calculate()`,
        })
      }

      return {
        ...sanitizedResult,
        auditTrail: audit.length > 0 ? audit : undefined,
      }
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err)
      logger.error(`[V6ScoreEngine] ${layerId} calculation failed: ${msg}`)

      if (this.config.auditEnabled) {
        audit.push({
          timestamp: Date.now(),
          layerId,
          step: 'error',
          input: {},
          output: { error: msg },
        })
      }

      return this.placeholderLayer(layerId, input, msg)
    }
  }

  /** 计算所有层返回综合评分 */
  async calculateAll(input: V6ScoreInput): Promise<CompositeScore> {
    const layerInput: LayerInput = {
      ...input,
      config: this.config,
    }

    const layerResults: Record<string, LayerScore> = {}
    const allRisks: string[] = []

    if (this.config.auditEnabled) {
      this.auditTrail = {
        symbol: input.symbol,
        timestamp: Date.now(),
        config: this.config,
        layers: {} as Record<LayerId, AuditEntry[]>,
        composite: { weightedSum: 0, layers: {} as Record<LayerId, number>, rating: '' },
        factorContributions: [],
      }
    }

    for (const layerId of ALL_LAYER_IDS) {
      const result = await this.calculateLayer(layerId, layerInput)
      layerResults[layerId] = result
      allRisks.push(...result.risks)

      if (this.auditTrail && result.auditTrail) {
        this.auditTrail.layers[layerId] = result.auditTrail
      }
    }

    return this.aggregate(layerResults as Record<LayerId, LayerScore>, allRisks)
  }

  /** 聚合各层得分为综合评分 */
  aggregate(layers: Record<LayerId, LayerScore>, allRisks: string[]): CompositeScore {
    let weightedSum = 0
    let totalWeight = 0
    const failedLayers: string[] = []

    const { weights, thresholds } = this.config

    const weightMap: Record<LayerId, number> = {
      lMinus1: weights.lMinus1, l0: weights.l0, l1: weights.l1, l2: weights.l2,
      l3f: weights.l3f, l3v: weights.l3v, l4: weights.l4, l5: weights.l5,
      l6: weights.l6, l7: weights.l7, l8: weights.l8,
    }

    for (const layerId of ALL_LAYER_IDS) {
      const layer = layers[layerId]!
      if (layer) {
        const w = weightMap[layerId]!
        
        // NaN 防护：验证 layer.score 是否有效
        if (!Number.isFinite(layer.score)) {
          logger.warn(`[V6ScoreEngine] aggregate: ${layerId} 层评分无效 (${layer.score})，跳过该层`)
          failedLayers.push(layerId)
          continue
        }
        
        weightedSum += layer.score * w
        totalWeight += w
      }
    }

    // 归一化，防止除以零
    const normalizedScore = totalWeight > 0
      ? Math.max(0, Math.min(5, (weightedSum / totalWeight)))
      : 0

    // 最终结果再次验证
    const finalScore = Number.isFinite(normalizedScore) ? normalizedScore : 0

    const rating = this.mapRating(finalScore, thresholds)
    const recommendation = this.generateRecommendation(rating, allRisks)

    const result: CompositeScore = {
      score: Math.round(finalScore * 100) / 100,
      rating,
      layers,
      allRisks,
      recommendation,
      timestamp: Date.now(),
      engineVersion: ENGINE_VERSION,
    }

    if (this.auditTrail) {
      this.auditTrail.composite = {
        weightedSum: Math.round(weightedSum * 100) / 100,
        layers: ALL_LAYER_IDS.reduce((acc, id) => {
          acc[id] = layers[id]?.score ?? 0
          return acc
        }, {} as Record<LayerId, number>) as Record<LayerId, number>,
        rating,
      }
      
      // 记录失败层信息
      if (failedLayers.length > 0) {
        logger.warn(`[V6ScoreEngine] aggregate: ${failedLayers.length} 层评分无效，已跳过: ${failedLayers.join(', ')}`)
      }
      
      this.auditTrail.factorContributions = buildFactorContributions(this.auditTrail)
    }

    return result
  }

  /** 获取审计追踪 */
  audit(): ScoreAuditTrail | null {
    return this.auditTrail
  }

  // ============================================================
  // 辅助方法
  // ============================================================

  private placeholderLayer(layerId: LayerId, _input: LayerInput, errorMsg?: string): LayerScore {
    const w = this.config.weights
    const weightMap: Record<LayerId, number> = {
      lMinus1: w.lMinus1, l0: w.l0, l1: w.l1, l2: w.l2,
      l3f: w.l3f, l3v: w.l3v, l4: w.l4, l5: w.l5,
      l6: w.l6, l7: w.l7, l8: w.l8,
    }
    const weight = weightMap[layerId]

    const layerName = LAYER_LABELS[layerId] ?? layerId
    const summary = errorMsg
      ? `[计算失败] ${layerName} 层计算失败: ${errorMsg}`
      : `[未注册计算器] ${layerName} 层无可用计算器`

    return {
      layerId,
      layerName,
      score: 0,
      summary,
      risks: errorMsg ? [errorMsg] : [],
      evidence: [],
      weight,
      weightedScore: 0,
      dataSources: [],
    }
  }

  private mapRating(score: number, thresholds: V6ScoreEngineConfig['thresholds']): CompositeScore['rating'] {
    const { rating } = thresholds
    if (score >= rating.strongBuy) return 'strong_buy'
    if (score >= rating.buy) return 'buy'
    if (score >= rating.hold) return 'hold'
    if (score >= rating.sell) return 'sell'
    return 'strong_sell'
  }

  private generateRecommendation(rating: CompositeScore['rating'], risks: string[]): string {
    const base: Record<CompositeScore['rating'], string> = {
      strong_buy: '综合评分优秀，建议积极配置。',
      buy: '综合评分良好，建议关注买入机会。',
      hold: '综合评分中等，建议持有观望。',
      sell: '综合评分偏弱，建议减仓。',
      strong_sell: '综合评分较差，建议回避。',
    }
    const riskNote = risks.length > 0 ? ` 需关注风险：${risks.slice(0, 3).join('；')}` : ''
    return (base[rating] ?? '') + riskNote
  }
}

/**
 * LLMScoreEnhancer — LLM 增强装饰器
 *
 * 包装任一 LayerCalculator，在规则引擎输出的基础上调用 LLM 提升评分质量。
 * 仅对设计为"LLM 可增强"的层启用（L0/L1/L2/L4/L5/L6/L7），
 * 确定性层（L3a/L3v/L-1/L8）不调用 LLM。
 *
 * 架构：Enhancer 不替代计算器，而是在计算器结果之上做增强。
 * 离线模式或 LLM 不可用时，Enhancer 透传原始结果。
 */

import { getLogger } from '@/lib/logger'
import type { LayerInput, LayerScore, LayerCalculator } from './types'
import type { LlmConfig } from '@/config/llmConfig'
import { isLlmConfigured } from '@/config/llmConfig'
import { chat } from '@/services/llm/llmGateway'
import type { LlmMessage } from '@/services/llm/llmTypes'
import { LOG_SNIPPET_MAX_CHARS } from '@/config/mathConstants'

const logger = getLogger()

/** 可被 LLM 增强的层 */
const LLM_ENHANCEABLE_LAYERS = new Set(['l0', 'l1', 'l2', 'l4', 'l5', 'l6', 'l7'])

export class LLMScoreEnhancer {
  private llmConfig: LlmConfig | null = null
  private enabled = false

  /** 配置 LLM 增强 */
  configure(config: LlmConfig): void {
    if (isLlmConfigured(config)) {
      this.llmConfig = { ...config }
      this.enabled = true
      logger.info('[LLMScoreEnhancer] LLM 增强已启用')
    } else {
      this.enabled = false
      logger.warn('[LLMScoreEnhancer] LLM 配置不完整，增强已禁用')
    }
  }

  /** 禁用 LLM 增强 */
  disable(): void {
    this.enabled = false
    logger.info('[LLMScoreEnhancer] LLM 增强已禁用')
  }

  /** 是否启用 */
  isEnabled(): boolean {
    return this.enabled && this.llmConfig !== null
  }

  /**
   * 包装计算器为 LLM 增强版本
   * 返回一个新的计算器：先执行原始计算，再（可选）调用 LLM 增强。
   */
  enhance(calculator: LayerCalculator): LayerCalculator {
    return {
      layerId: calculator.layerId,
      calculate: async (input: LayerInput): Promise<LayerScore> => {
        // 1. 先执行规则引擎计算
        const baseResult = await calculator.calculate(input)

        // 防御性校验：验证 baseResult 结构完整性
        if (!baseResult || typeof baseResult.score !== 'number') {
          logger.warn(
            `[LLMScoreEnhancer] 层 ${calculator.layerId} baseResult 无效，跳过增强`,
            { score: baseResult?.score, hasLayerId: !!baseResult?.layerId },
          )
          return baseResult
        }

        // 2. 判断是否需要 LLM 增强
        if (!this.isEnabled() || !LLM_ENHANCEABLE_LAYERS.has(calculator.layerId)) {
          return baseResult
        }

        if (!this.llmConfig) {
          return baseResult
        }

        try {
          const enhanced = await this.callLLM(calculator.layerId, baseResult, input)
          // LLM 增强成功：合并结果
          const mergedScore = enhanced.score ?? baseResult.score
          const mergedEvidence = enhanced.rationale
            ? [...baseResult.evidence, `[LLM增强] ${enhanced.rationale}`]
            : [...baseResult.evidence]

          return {
            ...baseResult,
            score: mergedScore,
            summary: enhanced.summary ?? baseResult.summary,
            evidence: mergedEvidence,
            risks: [...baseResult.risks, ...(enhanced.risks ?? [])],
          }
        } catch (error) {
          logger.warn(
            `[LLMScoreEnhancer] 层 ${calculator.layerId} LLM 增强失败，回退到规则结果: ${
              error instanceof Error ? error.message : String(error)
            }`,
          )
          return baseResult
        }
      },
    }
  }

  private async callLLM(
    layerId: string,
    baseResult: LayerScore,
    input: LayerInput,
  ): Promise<{ score?: number; summary?: string; rationale?: string; risks?: string[] }> {
    // 输入防护：确保 score 可安全格式化为字符串
    const safeScore = Number.isFinite(baseResult.score) ? baseResult.score : 0
    const safeSummary = baseResult.summary ?? '无摘要'
    const safeEvidence = Array.isArray(baseResult.evidence) ? baseResult.evidence.join('；') : ''

    const systemPrompt = `你是一位专业的股票分析师，请对以下评分层的规则引擎结果进行复核和增强。

当前层：${baseResult.layerName}
规则引擎评分：${safeScore.toFixed(2)}/5
规则引擎摘要：${safeSummary}
已有证据：${safeEvidence}

请以 JSON 格式返回增强建议：
{
  "score": number,         // 修正后的评分（0-5），如果规则引擎评分合理则保持原值
  "summary": "string",     // 增强后的摘要
  "rationale": "string",   // 增强理由
  "risks": ["string"]      // 额外识别到的风险
}`

    const userPrompt = `请对以下股票进行 ${baseResult.layerName} 的复核增强：
股票：${input.stock.symbol} ${input.stock.name ?? ''}
行业：${input.stock.sector ?? '未知'}
规则引擎当前评分：${safeScore.toFixed(2)}/5
评分摘要：${safeSummary}

请返回 JSON 格式的增强建议。`

    const messages: LlmMessage[] = [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt },
    ]

    const response = await chat(messages, this.llmConfig!)
    logger.info(`[LLMScoreEnhancer] ${layerId} LLM 返回: ${response.content.slice(0, LOG_SNIPPET_MAX_CHARS)}`)

    return this.parseResponse(response.content)
  }

  private parseResponse(content: string): { score?: number; summary?: string; rationale?: string; risks?: string[] } {
    try {
      const jsonMatch = content.match(/```(?:json)?\s*\n?([\s\S]*?)```/)
      const jsonStr = jsonMatch?.[1] ?? content
      const parsed = JSON.parse(jsonStr.trim())
      const parsedScore = parsed.score
      return {
        score: typeof parsedScore === 'number' ? Math.max(0, Math.min(5, parsedScore)) : undefined,
        summary: typeof parsed.summary === 'string' ? parsed.summary : undefined,
        rationale: typeof parsed.rationale === 'string' ? parsed.rationale : undefined,
        risks: Array.isArray(parsed.risks) ? parsed.risks.map(String) : undefined,
      }
    } catch {
      logger.warn('[LLMScoreEnhancer] LLM 返回内容无法解析', { snippet: content.slice(0, LOG_SNIPPET_MAX_CHARS) })
      return {}
    }
  }
}

/** 全局单例 */
export const llmEnhancer = new LLMScoreEnhancer()

/**
 * @module factorContributions
 * @description 基于 V6ScoreEngine.audit() 输出计算各因子对综合评分的贡献明细。
 * 所有权重、阈值均来自引擎配置，禁止硬编码。
 */

import type { ScoreAuditTrail, FactorContribution, LayerId } from './types'
import { ALL_LAYER_IDS, LAYER_LABELS } from './types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 因子评分或权重缺失时的默认零值 */
const DEFAULT_MISSING_VALUE = 0

/**
 * 根据审计追踪计算因子贡献明细。
 *
 * 计算规则：
 * 1. 仅参与计算的层（score > 0 且 weight > 0）纳入总权重。
 * 2. 归一化权重 = 该层权重 / 总权重。
 * 3. 绝对贡献 = 层得分 × 归一化权重 × 100 / 层满分（默认 5）。
 * 4. 中性基准 = (layerScore.min + layerScore.max) / 2，来自阈值配置。
 * 5. signedContribution = (层得分 - 中性基准) × 归一化权重 × 100 / 层满分，
 *    用于瀑布图展示正向/负向贡献。
 */
export function buildFactorContributions(trail: ScoreAuditTrail): FactorContribution[] {
  const { config, composite } = trail
  const weights = config.weights
  const layerScores = composite.layers
  const { min, max } = config.thresholds.layerScore
  const baseline = (min + max) / 2
  const scale = max > 0 ? 100 / max : 20

  // 检测缺失的因子得分和权重
  const missingFactors: string[] = []
  const missingWeights: string[] = []
  for (const id of ALL_LAYER_IDS) {
    const lid = id as LayerId
    if (layerScores[lid] == null) missingFactors.push(LAYER_LABELS[lid] ?? lid)
    if (weights[lid as keyof typeof weights] == null) missingWeights.push(lid)
  }
  if (missingFactors.length > 0) {
    logger.warn('[V6Engine] 因子贡献度缺失', { factor: missingFactors.join(', ') })
  }
  if (missingWeights.length > 0) {
    logger.warn('[V6Engine] 因子权重缺失', { factor: missingWeights.join(', ') })
  }

  const activeLayers = ALL_LAYER_IDS.filter((id) => {
    const rawScore = layerScores[id as LayerId]
    const rawWeight = weights[id as keyof typeof weights]
    const score = rawScore ?? DEFAULT_MISSING_VALUE
    const weight = rawWeight ?? DEFAULT_MISSING_VALUE
    return score > 0 && weight > 0
  })

  const totalWeight = activeLayers.reduce((sum, id) => {
    const rawW = weights[id as keyof typeof weights]
    const w = rawW ?? DEFAULT_MISSING_VALUE
    return sum + w
  }, 0)

  if (totalWeight === 0 || activeLayers.length === 0) {
    return []
  }

  const weightedAverage =
    activeLayers.reduce((sum, id) => {
      const score = layerScores[id as LayerId] ?? 0
      const weight = weights[id as keyof typeof weights] ?? 0
      return sum + score * weight
    }, 0) / totalWeight
  const finalScaled = weightedAverage * scale

  return activeLayers.map((id) => {
    const score = layerScores[id as LayerId] ?? 0
    const weight = weights[id as keyof typeof weights] ?? 0
    const normalizedWeight = weight / totalWeight
    const contribution = score * normalizedWeight * scale
    const signedContribution = (score - baseline) * normalizedWeight * scale
    const contributionRate = finalScaled > 0 ? contribution / finalScaled : 0

    return {
      factorId: id as LayerId,
      label: LAYER_LABELS[id as LayerId] ?? id,
      weight,
      normalizedWeight,
      score,
      baseline,
      contribution,
      signedContribution,
      contributionRate,
    }
  })
}

