/**
 * @module pnlComputer
 * @description 盈亏计算模块 - 纯函数集合
 *
 * 职责：
 * - 从交易对计算盈亏汇总（胜率、盈亏比、月度盈亏、日度曲线）
 * - 计算已实现和未实现盈亏
 *
 * 所有函数均为纯函数，便于测试和复用。
 */

import type { SymbolTradePair } from './positionComputer'

// ============================================================
// 类型定义
// ============================================================

/** 盈亏汇总 */
export interface PnLSummary {
  /** 总已实现盈亏（金额，元） */
  totalRealizedPnl: number
  /** 总未实现盈亏（金额，元）—— 按最新价估算，暂无行情时为 0 */
  totalUnrealizedPnl: number
  /** 胜率 % */
  winRate: number
  /** 盈亏比 */
  profitFactor: number
  /** 总交易笔数（完成配对的） */
  totalTrades: number
  /** 盈利交易数 */
  profitTrades: number
  /** 亏损交易数 */
  lossTrades: number
  /** 月度盈亏列表 */
  monthlyPnL: Array<{ month: string; pnl: number; trades: number }>
  /** 日度累计盈亏曲线 */
  dailyCurve: Array<{ date: string; cumulativePnL: number }>
}

// ============================================================
// 常量
// ============================================================

/** 无亏损时的盈亏比占位值（表示"极优"） */
const PROFIT_FACTOR_NO_LOSS = 999

// ============================================================
// 工具函数
// ============================================================

/** 保留两位小数 */
function round2(value: number): number {
  return Math.round(value * 100) / 100
}

/** 保留一位小数 */
function round1(value: number): number {
  return Math.round(value * 10) / 10
}

// ============================================================
// 核心计算函数
// ============================================================

/**
 * 从交易对结果计算盈亏汇总。
 *
 * @param tradePairs - 交易对数组
 * @returns 盈亏汇总指标
 */
export function computePnLSummary(tradePairs: SymbolTradePair[]): PnLSummary {
  const flatPairs = tradePairs.flatMap((tp) => tp.pairs)
  const totalTrades = flatPairs.length

  if (totalTrades === 0) {
    return {
      totalRealizedPnl: 0,
      totalUnrealizedPnl: 0,
      winRate: 0,
      profitFactor: 0,
      totalTrades: 0,
      profitTrades: 0,
      lossTrades: 0,
      monthlyPnL: [],
      dailyCurve: [],
    }
  }

  const profitPairs = flatPairs.filter((p) => p.realizedAmount > 0)
  const lossPairs = flatPairs.filter((p) => p.realizedAmount < 0)
  const profitTrades = profitPairs.length
  const lossTrades = lossPairs.length

  const totalRealizedPnl = round2(flatPairs.reduce((sum, p) => sum + p.realizedAmount, 0))
  const winRate = round1((profitTrades / totalTrades) * 100)

  const totalProfit = profitPairs.length > 0
    ? profitPairs.reduce((sum, p) => sum + p.realizedAmount, 0)
    : 0
  const totalLoss = lossPairs.length > 0
    ? Math.abs(lossPairs.reduce((sum, p) => sum + p.realizedAmount, 0))
    : 0
  const profitFactor = totalLoss > 0
    ? round2(totalProfit / totalLoss)
    : totalProfit > 0
      ? PROFIT_FACTOR_NO_LOSS
      : 0

  // 月度盈亏（按卖出日期聚合）
  const monthlyMap = new Map<string, { pnl: number; trades: number }>()
  for (const pair of flatPairs) {
    const month = pair.sellDate.slice(0, 7)
    const existing = monthlyMap.get(month) ?? { pnl: 0, trades: 0 }
    existing.pnl += pair.realizedAmount
    existing.trades += 1
    monthlyMap.set(month, existing)
  }
  const monthlyPnL = Array.from(monthlyMap.entries())
    .map(([month, val]) => ({
      month,
      pnl: round2(val.pnl),
      trades: val.trades,
    }))
    .sort((a, b) => a.month.localeCompare(b.month))

  // 日度累计盈亏曲线（按卖出日期排序累加）
  const sortedByDate = [...flatPairs].sort((a, b) => a.sellDate.localeCompare(b.sellDate))
  let cumulative = 0
  const dailyCurve = sortedByDate.map((pair) => {
    cumulative += pair.realizedAmount
    return {
      date: pair.sellDate,
      cumulativePnL: round2(cumulative),
    }
  })

  // 未实现盈亏：暂无实时行情，暂计为 0
  // 后续可接入 dailyQuotes 后，用最新价 × 持仓数量 - 持仓成本计算
  const totalUnrealizedPnl = 0

  return {
    totalRealizedPnl,
    totalUnrealizedPnl,
    winRate,
    profitFactor,
    totalTrades,
    profitTrades,
    lossTrades,
    monthlyPnL,
    dailyCurve,
  }
}

import { CORE_RESOURCE_THEME, matchesTheme, type ThemeConfig } from '@/config/themeRegistry'
import { getDefaultTradingConfig } from '@/config/tradingConfig'
import type { Portfolio, PortfolioHolding, RebalanceAction, Stock } from '@/data/types'
import { getCompositeScores } from './scoringAdapter'
import { runStrategy } from './strategyEngine'
import type { StrategyRuleConfig } from '@/config/strategyRules'
import type { StrategyResult } from '@/data/types'

export interface PortfolioBuilderInput {
  theme: ThemeConfig
  /** 候选股票池，通常为 watching 池或全部 stocks */
  stocks: Stock[]
  /** 总资产净值，默认取 tradingConfig.risk.portfolioValue */
  totalPortfolioValue?: number
  /** 当前持仓股数（symbol -> shares），默认从空持仓开始 */
  currentHoldings?: Record<string, number>
  /** 评分适配器选项 */
  scoringOptions?: Parameters<typeof getCompositeScores>[1]
  /** 策略规则配置；若提供，则先通过 strategyEngine 进行 20 进 13 筛选 */
  ruleConfig?: StrategyRuleConfig
}

export interface PortfolioBuilderOptions {
  /** 最小价格，低于该价格的标的不纳入组合（避免低价股异常） */
  minPrice?: number
  /** 是否跳过主题匹配（策略引擎已提前筛选时使用） */
  skipThemeMatch?: boolean
}

const DEFAULT_OPTIONS: PortfolioBuilderOptions = {
  minPrice: 0.01,
  skipThemeMatch: false,
}

/**
 * 根据主题与评分构建目标投资组合。
 *
 * 流程：
 * 1. 从候选池中筛选匹配主题的标的。
 * 2. 获取综合评分，剔除低于 minCompositeScore 的标的。
 * 3. 按综合评分降序排序。
 * 4. 在主题总仓位内等权分配，受 singleMaxPct / singleMinPct 约束。
 * 5. 根据当前持仓生成再平衡计划。
 */
export async function buildThemePortfolio(
  input: PortfolioBuilderInput,
  options: PortfolioBuilderOptions = {},
): Promise<Portfolio> {
  const opts = { ...DEFAULT_OPTIONS, ...options }
  const theme = input.theme
  const totalValue = input.totalPortfolioValue ?? getDefaultTradingConfig().risk.portfolioValue
  const currentHoldings = input.currentHoldings ?? {}

  // 1. 主题匹配 + 基础过滤
  const matchedStocks = input.stocks.filter((stock) => {
    const price = stock.price ?? 0
    if (price <= (opts.minPrice ?? 0)) return false
    return opts.skipThemeMatch ? true : matchesTheme(stock, theme)
  })

  if (matchedStocks.length === 0) {
    return emptyPortfolio(theme, totalValue)
  }

  // 2. 获取评分
  const scores = await getCompositeScores(matchedStocks, input.scoringOptions)
  const scoredMap = new Map(scores.map((s) => [s.symbol, s]))

  // 3. 按评分排序并过滤
  const qualified = matchedStocks
    .map((stock) => ({ stock, score: scoredMap.get(stock.symbol) }))
    .filter(({ score }) => (score?.composite ?? 0) >= theme.minCompositeScore)
    .sort((a, b) => (b.score?.composite ?? 0) - (a.score?.composite ?? 0))

  if (qualified.length === 0) {
    return emptyPortfolio(theme, totalValue)
  }

  // 4. 权重分配
  const allocations = allocateWeights(qualified.length, theme)

  // 5. 构建持仓明细
  const themeValue = totalValue * (theme.totalAllocationPct / 100)
  const cashReserve = themeValue * (theme.cashReservePct / 100)
  const investableValue = themeValue - cashReserve

  const holdings: PortfolioHolding[] = qualified.map(({ stock, score }, index) => {
    const targetWeight = allocations[index] ?? 0
    const targetValue = investableValue * targetWeight
    const price = stock.price ?? 0
    const roundLot = getDefaultTradingConfig().kelly.roundLot
    const targetShares = price > 0 ? Math.floor(targetValue / price / roundLot) * roundLot : 0
    const marketValue = targetShares * price
    const currentShares = currentHoldings[stock.symbol] ?? 0

    return {
      symbol: stock.symbol,
      name: stock.name,
      currentShares,
      currentWeight: 0, // 当前权重将在后续统一计算
      targetWeight,
      targetShares,
      price,
      marketValue,
      score: score?.composite ?? 0,
      rationale: score?.rationale ?? '无评分',
    }
  })

  // 6. 重新计算当前权重（基于当前持仓）
  holdings.forEach((h) => {
    const currentMarketValue = h.currentShares * h.price
    h.currentWeight = totalValue > 0 ? currentMarketValue / totalValue : 0
  })

  // 7. 生成再平衡计划
  const rebalancePlan = buildRebalancePlan(holdings, theme)

  return {
    id: `${theme.id}-${Date.now()}`,
    name: theme.name,
    theme: theme.id,
    totalValue,
    cashReserve,
    holdings,
    rebalancePlan,
    createdAt: Date.now(),
    updatedAt: Date.now(),
  }
}

/**
 * 分配主题内权重。
 *
 * 说明：
 * - theme.singleMaxPct / singleMinPct 均指“占总资产净值的百分比”。
 * - 主题内权重需转换为占总资产的比例后再受约束。
 * - 为简化 MVP，采用等权分配；若等权导致单只超出上限，则对高评分标的按上限封顶，
 *   其余标的权重归零（由调用方按评分排序后传入）。
 */
function allocateWeights(count: number, theme: ThemeConfig): number[] {
  if (count <= 0) return []

  const investableRatio = (1 - theme.cashReservePct / 100)
  // 单只标的在主题内允许的最大权重（使其实际占比不超过 singleMaxPct）
  const effectiveMax = (theme.singleMaxPct / 100) / ((theme.totalAllocationPct / 100) * investableRatio)
  const effectiveMin = (theme.singleMinPct / 100) / ((theme.totalAllocationPct / 100) * investableRatio)

  const equalWeight = 1 / count

  if (equalWeight <= effectiveMax) {
    return Array(count).fill(Math.max(effectiveMin, equalWeight))
  }

  // 等权超出上限：仅前 floor(1/effectiveMax) 只标的按上限配置，其余为 0
  const cappedCount = Math.min(count, Math.floor(1 / effectiveMax))
  const weights = Array(count).fill(0)
  for (let i = 0; i < cappedCount; i++) {
    weights[i] = effectiveMax
  }

  return weights
}

function buildRebalancePlan(
  holdings: PortfolioHolding[],
  theme: ThemeConfig,
): RebalanceAction[] {
  const plan: RebalanceAction[] = []

  for (const h of holdings) {
    const diff = h.targetShares - h.currentShares
    const drift = Math.abs(h.targetWeight - h.currentWeight)

    if (Math.abs(diff) < getDefaultTradingConfig().kelly.roundLot) {
      plan.push({
        symbol: h.symbol,
        action: 'hold',
        shares: 0,
        reason: '已接近目标仓位',
      })
      continue
    }

    if (drift < theme.rebalanceThreshold) {
      plan.push({
        symbol: h.symbol,
        action: 'hold',
        shares: 0,
        reason: `偏离度 ${(drift * 100).toFixed(2)}% 低于再平衡阈值 ${theme.rebalanceThreshold * 100}%`,
      })
      continue
    }

    if (diff > 0) {
      plan.push({
        symbol: h.symbol,
        action: 'buy',
        shares: diff,
        reason: `目标 ${h.targetShares} 股，当前 ${h.currentShares} 股，需补仓`,
      })
    } else {
      plan.push({
        symbol: h.symbol,
        action: 'sell',
        shares: Math.abs(diff),
        reason: `目标 ${h.targetShares} 股，当前 ${h.currentShares} 股，需减仓`,
      })
    }
  }

  return plan
}

export interface StrategyPortfolioResult {
  portfolio: Portfolio
  strategyResult: StrategyResult
}

/**
 * 先通过 strategyEngine 进行 20 进 13 筛选与分类，再构建主题组合。
 *
 * 适用于需要应用核心稀缺策略规则引擎的场景。
 */
export async function buildStrategyFilteredPortfolio(
  input: PortfolioBuilderInput,
  options: PortfolioBuilderOptions = {},
): Promise<StrategyPortfolioResult> {
  const strategyResult = await runStrategy(input.stocks, {
    theme: input.theme,
    ruleConfig: input.ruleConfig,
  })

  const selectedSymbols = new Set(strategyResult.selected.map((c) => c.symbol))
  const selectedStocks = input.stocks.filter((s) => selectedSymbols.has(s.symbol))

  const portfolio = await buildThemePortfolio(
    {
      ...input,
      stocks: selectedStocks,
    },
    { ...options, skipThemeMatch: true },
  )

  return { portfolio, strategyResult }
}

function emptyPortfolio(theme: ThemeConfig, totalValue: number): Portfolio {
  const themeValue = totalValue * (theme.totalAllocationPct / 100)
  const cashReserve = themeValue * (theme.cashReservePct / 100)

  return {
    id: `${theme.id}-${Date.now()}`,
    name: theme.name,
    theme: theme.id,
    totalValue,
    cashReserve,
    holdings: [],
    rebalancePlan: [],
    createdAt: Date.now(),
    updatedAt: Date.now(),
  }
}

/**
 * 便捷函数：为“第四次工业革命稀缺核心资源”主题构建投资组合。
 */
export async function buildCoreResourcePortfolio(
  stocks: Stock[],
  orders: Array<{ symbol: string; direction: 'buy' | 'sell'; quantity: number }>,
  totalPortfolioValue?: number,
): Promise<Portfolio> {
  return buildThemePortfolio({
    theme: CORE_RESOURCE_THEME,
    stocks,
    totalPortfolioValue,
    currentHoldings: computeHoldingsFromOrders(orders),
  })
}

/**
 * 计算当前持仓股数（基于订单流水）。
 */
export function computeHoldingsFromOrders(
  orders: Array<{ symbol: string; direction: 'buy' | 'sell'; quantity: number }>,
): Record<string, number> {
  const holdings: Record<string, number> = {}

  for (const order of orders) {
    const current = holdings[order.symbol] ?? 0
    holdings[order.symbol] = current + (order.direction === 'buy' ? order.quantity : -order.quantity)
  }

  return holdings
}

/**
 * @module positionComputer
 * @description 持仓计算模块 - 纯函数集合
 * 
 * 职责：
 * - 从订单列表构建交易对（FIFO 配对）
 * - 计算当前持仓（未平仓头寸）
 * - 计算已实现盈亏
 * 
 * 所有函数均为纯函数，便于测试和复用。
 */

import type { Order } from '@/data/types'
import type { TradePair } from '@/services/trading/tradeReviewAI.types'

// 重新导出规范 TradePair 类型，便于消费方从本模块直接导入
export type { TradePair }

// ============================================================
// 类型定义
// ============================================================

/** 单笔匹配的交易对明细（扩展规范 TradePair，增加持仓计算特有字段） */
export interface MatchedTradePair extends TradePair {
  /** 买入日期 YYYY-MM-DD */
  buyDate: string
  /** 卖出日期 YYYY-MM-DD */
  sellDate: string
  /** 配对数量（股） */
  quantity: number
  /** 已实现盈亏金额（元） */
  realizedAmount: number
}

/** 按 symbol 聚合的交易对与持仓信息 */
export interface SymbolTradePair {
  /** 股票代码 */
  symbol: string
  /** 买入订单列表 */
  buyOrders: Order[]
  /** 卖出订单列表 */
  sellOrders: Order[]
  /** 买入总金额 */
  totalBuy: number
  /** 卖出总金额 */
  totalSell: number
  /** 已实现盈亏（金额，元） */
  realizedPnl: number
  /** 未平仓数量（股） */
  openPositions: number
  /** 未平仓平均成本价 */
  avgCostPrice: number
  /** 内部配对明细，用于 UI 曲线/月度聚合 */
  pairs: MatchedTradePair[]
}

/** 当前持仓项 */
export interface PositionItem {
  /** 股票代码 */
  symbol: string
  /** 持仓数量（股） */
  quantity: number
  /** 平均成本价 */
  avgCost: number
  /** 持仓市值（按成本价计） */
  costValue: number
  /** 持仓方向 */
  direction: 'buy' | 'sell'
  /** 首次买入时间戳 */
  firstBuyAt: number
  /** 最近一次变动时间戳 */
  lastChangedAt: number
}

// ============================================================
// 工具函数
// ============================================================

/** 保留两位小数 */
function round2(value: number): number {
  return Math.round(value * 100) / 100
}

/** 时间戳转日期字符串 YYYY-MM-DD */
function formatDate(timestamp: number): string {
  return new Date(timestamp).toISOString().slice(0, 10)
}

/** 计算持仓天数（两个时间戳之间的自然日差，向上取整） */
function computeHoldDays(buyTimestamp: number, sellTimestamp: number): number {
  return Math.ceil((sellTimestamp - buyTimestamp) / (24 * 60 * 60 * 1000))
}

// ============================================================
// 核心计算函数
// ============================================================

/**
 * 按 symbol 对订单进行 FIFO 配对，计算已实现盈亏与未平仓头寸。
 *
 * @param orders - 订单列表
 * @returns 按 symbol 聚合的交易对数组
 *
 * @remarks
 * 配对算法：
 * 1. 按 symbol 分组
 * 2. 每组内按 createdAt 升序排列
 * 3. 买单入队，卖单从队头取买单进行 FIFO 配对
 * 4. 未配对的买单累积为当前持仓，计算平均成本价
 */
export function buildTradePairs(orders: Order[]): SymbolTradePair[] {
  const bySymbol = new Map<string, Order[]>()

  for (const order of orders) {
    const list = bySymbol.get(order.symbol) ?? []
    list.push(order)
    bySymbol.set(order.symbol, list)
  }

  const tradePairs: SymbolTradePair[] = []

  for (const [symbol, symOrders] of bySymbol) {
    const buyOrders = symOrders.filter((o) => o.direction === 'buy')
    const sellOrders = symOrders.filter((o) => o.direction === 'sell')
    const totalBuy = buyOrders.reduce((sum, o) => sum + o.amount, 0)
    const totalSell = sellOrders.reduce((sum, o) => sum + o.amount, 0)

    const sorted = [...symOrders].sort((a, b) => a.createdAt - b.createdAt)

    // FIFO 配对队列：每个元素为 { id, price, quantity, createdAt, amount }
    interface BuyQueueItem {
      id: string
      price: number
      quantity: number
      createdAt: number
      amount: number
    }
    const buyQueue: BuyQueueItem[] = []
    const pairs: MatchedTradePair[] = []
    let realizedPnl = 0

    for (const order of sorted) {
      if (order.direction === 'buy') {
        buyQueue.push({
          id: order.id,
          price: order.price,
          quantity: order.quantity,
          createdAt: order.createdAt,
          amount: order.amount,
        })
      } else if (order.direction === 'sell' && buyQueue.length > 0) {
        // 卖单与买单 FIFO 配对
        let remainingQty = order.quantity

        while (remainingQty > 0 && buyQueue.length > 0) {
          const buy = buyQueue[0]!
          const matchQty = Math.min(remainingQty, buy.quantity)
          const buyAmount = (matchQty / buy.quantity) * buy.amount
          const sellAmount = matchQty * order.price
          const realized = sellAmount - buyAmount

          pairs.push({
            buyId: buy.id ?? '',
            sellId: order.id ?? '',
            profitPct: buy.price > 0 ? round2(((order.price - buy.price) / buy.price) * 100) : 0,
            holdDays: computeHoldDays(buy.createdAt, order.createdAt),
            buyDate: formatDate(buy.createdAt),
            sellDate: formatDate(order.createdAt),
            quantity: matchQty,
            realizedAmount: round2(realized),
          })

          realizedPnl += realized
          remainingQty -= matchQty

          if (matchQty >= buy.quantity) {
            buyQueue.shift()
          } else {
            buy.quantity -= matchQty
            buy.amount -= buyAmount
          }
        }
      }
    }

    // 计算未平仓持仓
    const openPositions = buyQueue.reduce((sum, b) => sum + b.quantity, 0)
    const totalOpenCost = buyQueue.reduce((sum, b) => sum + b.amount, 0)
    const avgCostPrice = openPositions > 0 ? round2(totalOpenCost / openPositions) : 0

    tradePairs.push({
      symbol,
      buyOrders,
      sellOrders,
      totalBuy: round2(totalBuy),
      totalSell: round2(totalSell),
      realizedPnl: round2(realizedPnl),
      openPositions,
      avgCostPrice,
      pairs,
    })
  }

  return tradePairs
}

/**
 * 从交易对结果派生出当前持仓列表。
 *
 * @param tradePairs - 交易对数组
 * @returns 净持仓 > 0 的持仓项数组，按市值降序
 */
export function buildPositions(tradePairs: SymbolTradePair[]): PositionItem[] {
  const positions: PositionItem[] = []

  for (const tp of tradePairs) {
    if (tp.openPositions <= 0) continue

    // 找出首次买入和最近一次变动时间
    const allOrders = [...tp.buyOrders, ...tp.sellOrders]
    const firstBuy = tp.buyOrders.reduce(
      (earliest, o) => (o.createdAt < earliest ? o.createdAt : earliest),
      Infinity,
    )
    const lastChanged = allOrders.reduce(
      (latest, o) => (o.createdAt > latest ? o.createdAt : latest),
      0,
    )

    positions.push({
      symbol: tp.symbol,
      quantity: tp.openPositions,
      avgCost: tp.avgCostPrice,
      costValue: round2(tp.openPositions * tp.avgCostPrice),
      direction: 'buy',
      firstBuyAt: isFinite(firstBuy) ? firstBuy : 0,
      lastChangedAt: lastChanged,
    })
  }

  // 按成本市值降序排列
  positions.sort((a, b) => b.costValue - a.costValue)
  return positions
}

import { getDefaultTradingConfig } from '@/config/tradingConfig'
import type { SignalDirection } from '@/config/tradingConfig'
import { dataLayer } from '@/data/dataLayer'
import { getLogger } from '@/lib/logger'

const logger = getLogger()


export interface OrderRiskInput {
  symbol: string
  direction: SignalDirection
  quantity: number
  price: number
  portfolioValue: number
}

export interface RiskCheckResult {
  ok: boolean
  warnings: string[]
  blocks: string[]
}

function isWithinHours(timestamp: number, hours: number): boolean {
  return Date.now() - timestamp < hours * 60 * 60 * 1000
}

function startOfDayTimestamp(timestamp: number): number {
  const d = new Date(timestamp)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

/**
 * 风控检查
 *
 * 阻塞项：
 *   - 价格或数量非法
 *   - 同标的存在未完成买入且在冷却期内
 *   - 超出当日最大交易次数
 *   - 买入后超出单笔/总仓位上限
 *   - 行情数据过期
 * 警告项：
 *   - 单日交易次数接近上限
 *   - 仓位接近上限
 */
export async function checkOrderRisk(input: OrderRiskInput): Promise<RiskCheckResult> {
  const config = getDefaultTradingConfig()
  const risk = config.risk
  const warnings: string[] = []
  const blocks: string[] = []

  if (input.price <= 0 || input.quantity <= 0 || !Number.isFinite(input.price * input.quantity)) {
    blocks.push('价格或数量非法')
    return { ok: false, warnings, blocks }
  }

  if (input.portfolioValue <= 0) {
    blocks.push('组合净值非法')
    return { ok: false, warnings, blocks }
  }

  const normalized = input.symbol.trim().toUpperCase()

  // 1. 行情数据新鲜度
  const quotes = await dataLayer.dailyQuotes.get(normalized)
  if (!quotes || !quotes.updatedAt) {
    blocks.push('无有效行情数据')
  } else if (!isWithinHours(quotes.updatedAt, risk.dataFreshnessHours)) {
    blocks.push(`行情数据超过 ${risk.dataFreshnessHours} 小时未更新`)
  }

  // 2. 同标的冷却期
  const orders = await dataLayer.orders.list()

  // 检测 createdAt 缺失的订单
  const missingCreatedAtOrders = orders.filter((o) => o.symbol === normalized && o.createdAt == null)
  if (missingCreatedAtOrders.length > 0) {
    logger.warn('[RiskEngine] 字段缺失，使用默认值', {
      field: 'createdAt',
      context: `symbol=${normalized}, missingCount=${missingCreatedAtOrders.length}`,
    })
  }
  const symbolOrders = orders
    .filter((o) => o.symbol === normalized)
    .sort((a, b) => {
      const ta = a.createdAt ?? 0
      const tb = b.createdAt ?? 0
      return tb - ta
    })
  const latestOrder = symbolOrders[0]
  if (latestOrder) {
    // 保守策略：createdAt 缺失时视为在冷却期内，阻断交易
    const orderTime = latestOrder.createdAt ?? Date.now()
    if (isWithinHours(orderTime, risk.sameSymbolCooldownHours)) {
      blocks.push(
        `${normalized} 在 ${risk.sameSymbolCooldownHours} 小时冷却期内，上次交易时间 ${new Date(orderTime).toLocaleString()}`,
      )
    }
  }

  // 3. 当日交易次数
  const todayTs = startOfDayTimestamp(Date.now())
  const todayTrades = orders.filter((o) => (o.createdAt ?? 0) >= todayTs).length
  if (todayTrades >= risk.maxTradesPerDay) {
    blocks.push(`今日交易次数已达上限 ${risk.maxTradesPerDay}`)
  } else if (todayTrades >= risk.maxTradesPerDay - 1) {
    warnings.push(`今日交易次数接近上限 ${risk.maxTradesPerDay}`)
  }

  // 4. 仓位上限（仅买入）
  if (input.direction === 'buy') {
    const holdingShares = orders
      .filter((o) => o.symbol === normalized)
      .reduce((sum, o) => sum + (o.direction === 'buy' ? o.quantity : -o.quantity), 0)
    const holdingValue = holdingShares * input.price

    const totalShares = orders.reduce(
      (sum, o) => sum + (o.direction === 'buy' ? o.quantity : -o.quantity),
      0,
    )
    const totalValue = totalShares * input.price

    const afterSingleValue = holdingValue + input.quantity * input.price
    const afterTotalValue = totalValue + input.quantity * input.price
    const singleLimit = (risk.maxSinglePositionPct / 100) * input.portfolioValue
    const totalLimit = (risk.maxTotalPositionPct / 100) * input.portfolioValue

    if (afterSingleValue > singleLimit) {
      blocks.push(
        `买入后 ${normalized} 仓位 ${afterSingleValue.toFixed(0)} 超出单笔上限 ${singleLimit.toFixed(0)}`,
      )
    } else if (afterSingleValue > singleLimit * 0.9) {
      warnings.push(`${normalized} 仓位接近单笔上限`)
    }

    if (afterTotalValue > totalLimit) {
      blocks.push(
        `买入后总仓位 ${afterTotalValue.toFixed(0)} 超出总仓位上限 ${totalLimit.toFixed(0)}`,
      )
    } else if (afterTotalValue > totalLimit * 0.9) {
      warnings.push('总仓位接近上限')
    }
  }

  // 5. 卖出必须有持仓
  if (input.direction === 'sell') {
    const holdingShares = orders
      .filter((o) => o.symbol === normalized)
      .reduce((sum, o) => sum + (o.direction === 'buy' ? o.quantity : -o.quantity), 0)
    if (holdingShares < input.quantity) {
      blocks.push(`卖出数量 ${input.quantity} 超过当前持仓 ${holdingShares}`)
    }
  }

  return { ok: blocks.length === 0, warnings, blocks }
}

import { dataLayer } from '@/data/dataLayer'
import type { IndustryScore, IntelligentScore, Stock, V6Score } from '@/data/types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/**
 * 综合评分视图。
 *
 * 将 V6 自动评分、V6 个股智能评分、V4 行业评分聚合为单一视图，
 * 供交易舱 / 组合构建器使用。
 */
export interface CompositeScoreView {
  symbol: string
  /** V6 自动评分（0-5） */
  v6Score: number | null
  /** V6 个股智能评分（0-5） */
  intelligentScore: number | null
  /** 行业/主题评分（0-5） */
  industryScore: number | null
  /** V6 估值因子分（0-5），策略规则引擎用 */
  valuationScore: number | null
  /** 聚合后的综合评分（0-5），用于组合排序 */
  composite: number | null
  /** 评分来源摘要 */
  rationale: string
  /** 数据新鲜度：最近一次评分时间 */
  scoredAt: number | null
}

export interface ScoringAdapterOptions {
  /**
   * 综合评分计算时各评分来源的权重。
   * 默认：v6 50%、intelligent 30%、industry 20%。
   */
  weights?: {
    v6: number
    intelligent: number
    industry: number
  }
  /**
   * 智能评分缺失时是否回退到 V6 自动评分。
   * 默认 true。
   */
  fallbackToV6?: boolean
}

const DEFAULT_WEIGHTS = {
  v6: 0.5,
  intelligent: 0.3,
  industry: 0.2,
}

function weightedAverage(values: Array<{ value: number | null; weight: number }>): number | null {
  let totalWeight = 0
  let weightedSum = 0

  for (const { value, weight } of values) {
    if (value === null || Number.isNaN(value)) continue
    weightedSum += value * weight
    totalWeight += weight
  }

  if (totalWeight === 0) return null
  return Math.round((weightedSum / totalWeight) * 100) / 100
}

/**
 * 为单只股票计算综合评分视图。
 */
export async function getCompositeScore(
  stock: Stock,
  options?: ScoringAdapterOptions,
): Promise<CompositeScoreView> {
  const weights = { ...DEFAULT_WEIGHTS, ...options?.weights }
  const fallbackToV6 = options?.fallbackToV6 ?? true

  let v6Score: V6Score | undefined
  let intelligentScore: IntelligentScore | undefined
  let industryScore: IndustryScore | undefined

  try {
    v6Score = await dataLayer.v6Scores.get(stock.symbol)
  } catch (e) {
    logger.warn('[scoringAdapter] 读取 V6 评分失败', { symbol: stock.symbol, error: e })
  }

  try {
    intelligentScore = await dataLayer.intelligentScores.getLatestBySymbol(stock.symbol)
  } catch (e) {
    logger.warn('[scoringAdapter] 读取智能评分失败', { symbol: stock.symbol, error: e })
  }

  // 行业评分：优先通过股票 sector 名称匹配行业评分 code
  try {
    if (stock.sector) {
      const allIndustryScores = await dataLayer.industryScores.list()
      const matched = allIndustryScores
        .filter((s) => s.name.includes(stock.sector!) || stock.sector!.includes(s.name))
      const missingScoredAt = matched.filter((s) => s.scoredAt == null)
      if (missingScoredAt.length > 0) {
        logger.warn('[ScoringAdapter] 字段缺失，使用默认值', { field: 'scoredAt', symbol: stock.symbol, missingCount: missingScoredAt.length })
      }
      industryScore = matched
        .sort((a, b) => {
          const ta = a.scoredAt ?? 0
          const tb = b.scoredAt ?? 0
          return tb - ta
        })[0]
    }
  } catch (e) {
    logger.warn('[scoringAdapter] 读取行业评分失败', { symbol: stock.symbol, error: e })
  }

  const v6Value = v6Score?.score ?? null
  const intelligentValue = intelligentScore?.overallScore ?? null
  const industryValue = industryScore?.sectorSnapshot?.composite ?? industryScore?.overallScore ?? null
  const valuationValue = v6Score?.factors?.估值 ?? null

  let composite = weightedAverage([
    { value: v6Value, weight: weights.v6 },
    { value: intelligentValue, weight: weights.intelligent },
    { value: industryValue, weight: weights.industry },
  ])

  // 若智能评分缺失且允许回退，则回退到 V6 评分
  if (composite === null && fallbackToV6 && v6Value !== null) {
    composite = v6Value
  }

  const rationale = buildRationale(v6Value, intelligentValue, industryValue, valuationValue, composite)

  // 检测评分时间戳缺失
  const scoredAtSources = {
    v6CalculatedAt: v6Score?.calculatedAt ?? null,
    intelligentScoredAt: intelligentScore?.scoredAt ?? null,
    industryScoredAt: industryScore?.scoredAt ?? null,
  }
  const missingTimestamps = Object.entries(scoredAtSources)
    .filter(([, v]) => v == null)
    .map(([k]) => k)
  if (missingTimestamps.length > 0 && missingTimestamps.length < 3) {
    logger.warn('[ScoringAdapter] 评分因子缺失', { factor: 'scoredAt', symbol: stock.symbol, missingFields: missingTimestamps })
  }

  const scoredAt = Math.max(
    v6Score?.calculatedAt ?? 0,
    intelligentScore?.scoredAt ?? 0,
    industryScore?.scoredAt ?? 0,
  ) || null

  return {
    symbol: stock.symbol,
    v6Score: v6Value,
    intelligentScore: intelligentValue,
    industryScore: industryValue,
    valuationScore: valuationValue,
    composite,
    rationale,
    scoredAt,
  }
}

function buildRationale(
  v6: number | null,
  intelligent: number | null,
  industry: number | null,
  valuation: number | null,
  composite: number | null,
): string {
  const parts: string[] = []
  if (v6 !== null) parts.push(`V6自动评分 ${v6}`)
  if (intelligent !== null) parts.push(`智能评分 ${intelligent}`)
  if (industry !== null) parts.push(`行业评分 ${industry}`)
  if (valuation !== null) parts.push(`估值分 ${valuation}`)

  if (parts.length === 0) return '暂无评分数据'

  const compositeText = composite !== null ? `；综合 ${composite}` : ''
  return `${parts.join(' / ')}${compositeText}`
}

/**
 * 批量获取一组股票的综合评分视图。
 */
export async function getCompositeScores(
  stocks: Stock[],
  options?: ScoringAdapterOptions,
): Promise<CompositeScoreView[]> {
  const results = await Promise.all(stocks.map((stock) => getCompositeScore(stock, options)))
  return results
}

import { getDefaultTradingConfig } from '@/config/tradingConfig'
import type { SignalDirection } from '@/config/tradingConfig'
import { dataLayer } from '@/data/dataLayer'
import type { DailyQuotes, KlineBar, Signal, SignalSnapshot } from '@/data/types'
import { generateId } from '@/data/db'
import { SIGNAL_GENERATOR_THRESHOLDS } from '@/config/thresholds'

export type TradingSignal = Signal

function computeMA(values: number[], period: number): number | undefined {
  if (values.length < period) return undefined
  const slice = values.slice(-period)
  return slice.reduce((a, b) => a + b, 0) / period
}

function computeRSI14(closes: number[]): number | undefined {
  if (closes.length < SIGNAL_GENERATOR_THRESHOLDS.RSI_MIN_CLOSES) return undefined
  const window = closes.slice(-(SIGNAL_GENERATOR_THRESHOLDS.RSI_MIN_CLOSES + 1))
  let gains = 0
  let losses = 0
  for (let i = 1; i < window.length; i++) {
    const delta = window[i]! - window[i - 1]!
    if (delta > 0) gains += delta
    else losses -= delta
  }
  if (losses === 0) return 100
  const rs = gains / losses
  return 100 - 100 / (1 + rs)
}

function computeVolumeRatio(history: KlineBar[]): number | undefined {
  if (history.length < SIGNAL_GENERATOR_THRESHOLDS.VOLUME_RATIO_MIN_BARS) return undefined
  const recent = history[history.length - 1]!.volume
  const avg = history.slice(-(SIGNAL_GENERATOR_THRESHOLDS.VOLUME_RATIO_MIN_BARS), -1).reduce((sum, bar) => sum + bar.volume, 0) / (SIGNAL_GENERATOR_THRESHOLDS.VOLUME_RATIO_MIN_BARS - 1)
  if (avg === 0) return undefined
  return recent / avg
}

function computeMACDDirection(closes: number[]): 'red' | 'green' | 'neutral' {
  if (closes.length < SIGNAL_GENERATOR_THRESHOLDS.MACD_MIN_CLOSES) return 'neutral'
  const ema = (values: number[], period: number): number => {
    const k = 2 / (period + 1)
    let result: number = values[0]!
    for (let i = 1; i < values.length; i++) {
      result = values[i]! * k + result * (1 - k)
    }
    return result
  }
  const ema12 = ema(closes.slice(-12), 12)
  const ema26 = ema(closes.slice(-26), 26)
  const diff = ema12 - ema26
  // 简化：只用当前 DIF 正负判断方向
  return diff > 0 ? 'red' : diff < 0 ? 'green' : 'neutral'
}

function buildSnapshot(_stock: unknown, quotes: DailyQuotes): SignalSnapshot {
  const closes = quotes.history.map((bar) => bar.close)
  const ma20 = computeMA(closes, 20)
  const ma60 = computeMA(closes, 60)
  const latest = quotes.latest.close
  return {
    pePercentile: undefined,
    pbPercentile: undefined,
    priceToMA20: ma20 !== undefined && ma20 !== 0 ? (latest - ma20) / ma20 : undefined,
    priceToMA60: ma60 !== undefined && ma60 !== 0 ? (latest - ma60) / ma60 : undefined,
    volumeRatio: computeVolumeRatio(quotes.history),
    rsi14: computeRSI14(closes),
    macdDirection: computeMACDDirection(closes),
  }
}

function generateBuySignals(snapshot: SignalSnapshot): TradingSignal[] {
  const signals: TradingSignal[] = []
  const config = getDefaultTradingConfig().signalThresholds

  // buy_safety_margin：基于绝对估值启发式（因历史百分位数据缺失）
  // if (stock.pe !== undefined && stock.pb !== undefined) {
  //   // 保守映射：PE < 15 且 PB < 2 视为安全边际
  // }

  // buy_dip：价格低于 MA20 8% 且 RSI < 30
  if (
    snapshot.priceToMA20 !== undefined &&
    snapshot.priceToMA20 < -config.dipToMA20Pct / 100 &&
    snapshot.rsi14 !== undefined &&
    snapshot.rsi14 < config.dipRsi14Max
  ) {
    signals.push({
      id: '',
      symbol: '',
      direction: 'buy',
      type: 'buy_dip',
      strategy: 'signal',
      confidence: 0.55,
      rationale: `价格低于 MA20 ${(snapshot.priceToMA20 * 100).toFixed(1)}%，RSI14 ${snapshot.rsi14.toFixed(1)} 处于超卖区间`,
      snapshot,
      createdAt: 0,
    })
  }

  // buy_pivot：突破 MA20 + 放量 + MACD 红柱
  if (
    snapshot.priceToMA20 !== undefined &&
    snapshot.priceToMA20 > 0 &&
    snapshot.volumeRatio !== undefined &&
    snapshot.volumeRatio > config.pivotVolumeRatioMin &&
    snapshot.macdDirection === 'red'
  ) {
    signals.push({
      id: '',
      symbol: '',
      direction: 'buy',
      type: 'buy_pivot',
      strategy: 'signal',
      confidence: 0.65,
      rationale: `价格站上 MA20，量比 ${snapshot.volumeRatio.toFixed(2)}，MACD 红柱`,
      snapshot,
      createdAt: 0,
    })
  }

  return signals
}

function generateSellSignals(
  snapshot: SignalSnapshot,
  history: KlineBar[],
): TradingSignal[] {
  const signals: TradingSignal[] = []
  const config = getDefaultTradingConfig().signalThresholds
  const latest = history[history.length - 1]!.close

  // sell_profit_taking：价格高于 MA20 15% 且 RSI > 70
  if (
    snapshot.priceToMA20 !== undefined &&
    snapshot.priceToMA20 > config.profitTakingToMA20Pct / 100 &&
    snapshot.rsi14 !== undefined &&
    snapshot.rsi14 > config.profitTakingRsi14Min
  ) {
    signals.push({
      id: '',
      symbol: '',
      direction: 'sell',
      type: 'sell_profit_taking',
      strategy: 'signal',
      confidence: 0.55,
      rationale: `价格高于 MA20 ${(snapshot.priceToMA20 * 100).toFixed(1)}%，RSI14 ${snapshot.rsi14.toFixed(1)} 处于超买区间`,
      snapshot,
      createdAt: 0,
    })
  }

  // sell_trailing_stop：从近期最高点回撤 10%
  const highest = Math.max(...history.slice(-60).map((bar) => bar.high))
  if (highest > 0 && (highest - latest) / highest > config.trailingStopDrawdownPct / 100) {
    signals.push({
      id: '',
      symbol: '',
      direction: 'sell',
      type: 'sell_trailing_stop',
      strategy: 'signal',
      confidence: 0.7,
      rationale: `从近期高点 ${highest.toFixed(2)} 回撤 ${(((highest - latest) / highest) * 100).toFixed(1)}%`,
      snapshot,
      createdAt: 0,
    })
  }

  return signals
}

/**
 * 为单只股票生成交易信号
 */
export async function generateSignalsForSymbol(
  symbol: string,
): Promise<TradingSignal[]> {
  const normalized = symbol.trim().toUpperCase()
  const stock = await dataLayer.stocks.get(normalized)
  const quotes = await dataLayer.dailyQuotes.get(normalized)

  if (!stock) {
    return []
  }

  if (!quotes || quotes.history.length < 20) {
    return [
      {
        id: generateId(),
        symbol: normalized,
        direction: 'watch',
        type: 'watch',
        strategy: 'signal',
        confidence: 0.1,
        rationale: '行情数据不足，保持观察',
        snapshot: {},
        createdAt: Date.now(),
      },
    ]
  }

  const snapshot = buildSnapshot(stock, quotes)
  const buySignals = generateBuySignals(snapshot)
  const sellSignals = generateSellSignals(snapshot, quotes.history)
  const rawSignals = [...buySignals, ...sellSignals]

  const now = Date.now()
  const signals: TradingSignal[] = rawSignals.map((s) => ({
    ...s,
    id: generateId(),
    symbol: normalized,
    createdAt: now,
  }))

  // 综合共振：同方向多个独立信号时生成 composite
  const buyCount = signals.filter((s) => s.direction === 'buy').length
  const sellCount = signals.filter((s) => s.direction === 'sell').length

  if (buyCount >= 2) {
    const baseConfidence = Math.max(...signals.filter((s) => s.direction === 'buy').map((s) => s.confidence))
    signals.push({
      id: generateId(),
      symbol: normalized,
      direction: 'buy',
      type: 'composite_buy',
      strategy: 'signal',
      confidence: Math.min(1, baseConfidence + 0.2 * (buyCount - 1)),
      rationale: `共振：同时触发 ${buyCount} 个买入信号`,
      snapshot,
      createdAt: now,
    })
  }

  if (sellCount >= 2) {
    const baseConfidence = Math.max(...signals.filter((s) => s.direction === 'sell').map((s) => s.confidence))
    signals.push({
      id: generateId(),
      symbol: normalized,
      direction: 'sell',
      type: 'composite_sell',
      strategy: 'signal',
      confidence: Math.min(1, baseConfidence + 0.2 * (sellCount - 1)),
      rationale: `共振：同时触发 ${sellCount} 个卖出信号`,
      snapshot,
      createdAt: now,
    })
  }

  if (signals.length === 0) {
    signals.push({
      id: generateId(),
      symbol: normalized,
      direction: 'hold',
      type: 'hold',
      strategy: 'signal',
      confidence: 0.15,
      rationale: '无明确信号，建议持有/观望',
      snapshot,
      createdAt: now,
    })
  }

  return signals
}

/**
 * 从一组信号中挑选最强信号（买入优先于卖出，再按置信度）
 */
export function pickStrongestSignal(signals: TradingSignal[]): TradingSignal | undefined {
  if (signals.length === 0) return undefined
  const priority: Record<SignalDirection, number> = { buy: 3, sell: 2, watch: 1, hold: 0 }
  return signals.slice().sort((a, b) => {
    const pa = priority[a.direction] ?? 0
    const pb = priority[b.direction] ?? 0
    if (pa !== pb) return pb - pa
    return b.confidence - a.confidence
  })[0]
}

import type { ThemeConfig } from '@/config/themeRegistry'
import {
  getDefaultStrategyRuleConfig,
  type StrategyRuleConfig,
} from '@/config/strategyRules'
import { dataLayer } from '@/data/dataLayer'
import type {
  Stock,
  StrategyCandidate,
  StrategyClassification,
  StrategyResult,
} from '@/data/types'
import { hotSectorQueryUseCase } from '@/services/useCase/hotSectorQuery.useCase'
import type { HotSector } from '@/services/input/hotSectorService'
import { matchesTheme } from '@/config/themeRegistry'
import { getLogger } from '@/lib/logger'
import { getCompositeScores } from './scoringAdapter'

const logger = getLogger()

export interface RunStrategyOptions {
  /** 主题配置；未指定则使用「第四次工业革命稀缺核心资源」主题 */
  theme?: ThemeConfig
  /** 策略规则配置；默认使用 DEFAULT_STRATEGY_RULE_CONFIG */
  ruleConfig?: StrategyRuleConfig
  /** 外部注入的动量快照（symbol -> priceToMA20），未提供则内部读取 dailyQuotes */
  momentumMap?: Record<string, number>
}

/**
 * 策略规则引擎。
 *
 * 依据 v6-pro-cockpit 核心稀缺策略实现：
 * 1. 对输入股票池进行分类：core-scarce / value-bargain / hot-momentum / excluded。
 * 2. 应用 20 进 13 规则筛选入选标的。
 * 3. 返回结构化 StrategyResult，供 portfolioBuilder 直接消费。
 */
export async function runStrategy(
  stocks: Stock[],
  options: RunStrategyOptions = {},
): Promise<StrategyResult> {
  logger.info('[strategyEngine] runStrategy 开始', {
    stockCount: stocks.length,
    hasTheme: !!options.theme,
    hasMomentumMap: !!options.momentumMap,
    hasRuleConfig: !!options.ruleConfig,
  })

  const ruleConfig = options.ruleConfig ?? getDefaultStrategyRuleConfig()
  const theme = options.theme

  if (stocks.length === 0) {
    logger.warn('[strategyEngine] runStrategy 输入股票池为空，返回空结果')
    return emptyResult()
  }

  logger.info('[strategyEngine] runStrategy 加载评分、动量、热门板块数据', {
    stockCount: stocks.length,
    useExternalMomentum: !!options.momentumMap,
  })

  const [scoreViews, momentumMap, topHotSectors] = await Promise.all([
    getCompositeScores(stocks),
    options.momentumMap ? Promise.resolve(options.momentumMap) : fetchMomentumMap(stocks),
    fetchTopHotSectors(ruleConfig.hotMomentumTopSectors),
  ])

  logger.info('[strategyEngine] runStrategy 数据加载完成', {
    scoreViewsCount: scoreViews.length,
    momentumMapCount: Object.keys(momentumMap).length,
    topHotSectorsCount: topHotSectors.length,
    topHotSectors: topHotSectors.map((s) => ({ name: s.name, score: s.score })),
  })

  const scoreMap = new Map(scoreViews.map((s) => [s.symbol, s]))

  logger.info('[strategyEngine] runStrategy 开始分类候选股票')

  const candidates: StrategyCandidate[] = stocks.map((stock) => {
    const score = scoreMap.get(stock.symbol)
    const composite = score?.composite ?? 0
    const valuationScore = score?.valuationScore ?? null
    const industryScore = score?.industryScore ?? null
    const momentum = momentumMap[stock.symbol] ?? null
    const sector = stock.sector ?? null

    const classification = classify(
      stock,
      composite,
      valuationScore,
      sector,
      momentum,
      theme,
      ruleConfig,
      topHotSectors,
    )

    logger.info('[strategyEngine] runStrategy 股票分类完成', {
      symbol: stock.symbol,
      name: stock.name,
      composite: composite.toFixed(2),
      valuationScore: valuationScore?.toFixed(2) ?? 'null',
      momentum: momentum !== null ? (momentum * 100).toFixed(1) + '%' : 'null',
      sector,
      classification,
    })

    return {
      symbol: stock.symbol,
      name: stock.name,
      composite,
      valuationScore,
      industryScore,
      momentum,
      sector,
      classification,
      reasons: buildReasons(classification, composite, valuationScore, sector, momentum, ruleConfig),
    }
  })

  const coreScarce = candidates.filter((c) => c.classification === 'core-scarce')
  const valueBargain = candidates.filter((c) => c.classification === 'value-bargain')
  const hotMomentum = candidates.filter((c) => c.classification === 'hot-momentum')
  const excluded = candidates.filter((c) => c.classification === 'excluded')

  logger.info('[strategyEngine] runStrategy 分类统计', {
    coreScarceCount: coreScarce.length,
    valueBargainCount: valueBargain.length,
    hotMomentumCount: hotMomentum.length,
    excludedCount: excluded.length,
    coreScarceSymbols: coreScarce.map((c) => c.symbol),
    valueBargainSymbols: valueBargain.map((c) => c.symbol),
    hotMomentumSymbols: hotMomentum.map((c) => c.symbol),
  })

  // 20 进 13：先合并可入选池，再应用 R2 低估值过滤，最后按综合分截断
  const pool = [...coreScarce, ...valueBargain, ...hotMomentum]

  logger.info('[strategyEngine] runStrategy 应用 R2 低估值过滤', {
    poolSize: pool.length,
    lowValuationThreshold: ruleConfig.lowValuationThreshold,
    lowValuationCompositeExempt: ruleConfig.lowValuationCompositeExempt,
  })

  const afterR2 = pool.filter((c) => {
    if (
      c.valuationScore !== null &&
      c.valuationScore < ruleConfig.lowValuationThreshold &&
      c.composite < ruleConfig.lowValuationCompositeExempt
    ) {
      logger.info('[strategyEngine] runStrategy R2 过滤触发', {
        symbol: c.symbol,
        name: c.name,
        valuationScore: c.valuationScore.toFixed(2),
        composite: c.composite.toFixed(2),
      })
      c.classification = 'excluded'
      c.reasons.push(
        `R2：估值分 ${c.valuationScore.toFixed(2)} 低于 ${ruleConfig.lowValuationThreshold} 且综合分 ${c.composite.toFixed(2)} 低于 ${ruleConfig.lowValuationCompositeExempt}`,
      )
      excluded.push(c)
      return false
    }
    return true
  })

  logger.info('[strategyEngine] runStrategy R2 过滤完成', {
    beforeCount: pool.length,
    afterCount: afterR2.length,
    filteredCount: pool.length - afterR2.length,
  })

  const selected = afterR2
    .sort((a, b) => b.composite - a.composite || a.symbol.localeCompare(b.symbol))
    .slice(0, ruleConfig.selectedMaxCount)

  logger.info('[strategyEngine] runStrategy 最终入选股票', {
    selectedCount: selected.length,
    maxCount: ruleConfig.selectedMaxCount,
    selectedSymbols: selected.map((c) => ({
      symbol: c.symbol,
      name: c.name,
      composite: c.composite.toFixed(2),
      classification: c.classification,
    })),
  })

  // 未进入 Top13 的候选也移入 rejected 以便展示
  afterR2.forEach((c) => {
    if (!selected.includes(c)) {
      logger.info('[strategyEngine] runStrategy 未入选股票', {
        symbol: c.symbol,
        name: c.name,
        composite: c.composite.toFixed(2),
        classification: c.classification,
      })
      c.reasons.push(`未进入综合分前 ${ruleConfig.selectedMaxCount} 名`)
      excluded.push(c)
    }
  })

  logger.info('[strategyEngine] runStrategy 完成', {
    total: candidates.length,
    selectedCount: selected.length,
    coreScarceCount: coreScarce.length,
    valueBargainCount: valueBargain.length,
    hotMomentumCount: hotMomentum.length,
    rejectedCount: excluded.length,
  })

  return {
    selected,
    coreScarce,
    valueBargain,
    hotMomentum,
    rejected: excluded,
    summary: {
      total: candidates.length,
      selectedCount: selected.length,
      coreScarceCount: coreScarce.length,
      valueBargainCount: valueBargain.length,
      hotMomentumCount: hotMomentum.length,
    },
  }
}

function classify(
  stock: Stock,
  composite: number,
  valuationScore: number | null,
  sector: string | null,
  momentum: number | null,
  theme: ThemeConfig | undefined,
  rules: StrategyRuleConfig,
  topHotSectors: HotSector[],
): StrategyClassification {
  // core-scarce：匹配主题且综合分达到主题门槛
  if (theme && matchesTheme(stock, theme) && composite >= theme.minCompositeScore) {
    return 'core-scarce'
  }

  // value-bargain：估值分高、综合分中等
  if (
    composite >= rules.valueBargainCompositeMin &&
    valuationScore !== null &&
    valuationScore >= rules.valueBargainValuationMin
  ) {
    return 'value-bargain'
  }

  // hot-momentum：sector 属于热门板块 TOP N 且动量达标
  if (
    composite >= rules.compositeMin &&
    sector !== null &&
    momentum !== null &&
    momentum >= rules.hotMomentumMinMomentum &&
    isHotSector(sector, topHotSectors)
  ) {
    return 'hot-momentum'
  }

  return 'excluded'
}

function buildReasons(
  classification: StrategyClassification,
  composite: number,
  valuationScore: number | null,
  sector: string | null,
  momentum: number | null,
  rules: StrategyRuleConfig,
): string[] {
  switch (classification) {
    case 'core-scarce':
      return [`核心稀缺主题匹配，综合分 ${composite.toFixed(2)}`]
    case 'value-bargain':
      return [
        `价值洼地：估值分 ${valuationScore?.toFixed(2) ?? '-'}，综合分 ${composite.toFixed(2)}`,
      ]
    case 'hot-momentum':
      return [
        `热门追涨：板块 ${sector ?? '-'}，动量 ${((momentum ?? (() => {
          logger.warn('[strategyEngine] 字段缺失，使用默认值', { field: 'momentum', context: 'hot-momentum' })
          return 0
        })()) * 100).toFixed(1)}%`,
      ]
    case 'excluded':
    default: {
      const reasons: string[] = []
      if (composite < rules.compositeMin) {
        reasons.push(`综合分 ${composite.toFixed(2)} 低于门槛 ${rules.compositeMin}`)
      }
      if (valuationScore !== null && valuationScore < rules.valueBargainValuationMin) {
        reasons.push(`估值分 ${valuationScore.toFixed(2)} 未达价值洼地标准`)
      }
      if (sector === null || momentum === null || momentum < rules.hotMomentumMinMomentum) {
        reasons.push('不满足热门追涨动量/板块条件')
      }
      if (reasons.length === 0) {
        reasons.push('未匹配任何策略分类规则')
      }
      return reasons
    }
  }
}

async function fetchMomentumMap(stocks: Stock[]): Promise<Record<string, number>> {
  const map: Record<string, number> = {}

  await Promise.all(
    stocks.map(async (stock) => {
      const quotes = await dataLayer.dailyQuotes.get(stock.symbol)
      if (!quotes || quotes.history.length < 20) return

      const closes = quotes.history.map((bar) => bar.close)
      const ma20 = closes.slice(-20).reduce((a, b) => a + b, 0) / 20
      const latest = quotes.latest?.close ?? closes[closes.length - 1]
      if (ma20 && ma20 !== 0 && latest !== undefined) {
        map[stock.symbol] = (latest - ma20) / ma20
      }
    }),
  )

  return map
}

async function fetchTopHotSectors(topN: number): Promise<HotSector[]> {
  try {
    const result = await hotSectorQueryUseCase({ topN })
    return result.hotSectors
  } catch {
    return []
  }
}

function isHotSector(sector: string, topHotSectors: HotSector[]): boolean {
  const normalized = sector.toLowerCase()
  return topHotSectors.some((s) =>
    normalized.includes(s.name.toLowerCase()) ||
    s.name.toLowerCase().includes(normalized),
  )
}

function emptyResult(): StrategyResult {
  return {
    selected: [],
    coreScarce: [],
    valueBargain: [],
    hotMomentum: [],
    rejected: [],
    summary: {
      total: 0,
      selectedCount: 0,
      coreScarceCount: 0,
      valueBargainCount: 0,
      hotMomentumCount: 0,
    },
  }
}

/**
 * 策略快照服务（V6 Pro 迁移）
 *
 * 将股票按核心稀缺 / 热点动量 / 价值 bargain 三策略分组，
 * 生成策略快照并持久化到 IndexedDB 的 strategy_snapshots 存储。
 */

import { dataLayer } from '@/data/dataLayer'
import type {
  DataLayerResult,
  RotationSectorScore,
  Stock,
  StrategyGroupSnapshot,
  StrategySnapshot,
  V6Score,
} from '@/data/types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

export interface StrategyGroupItem {
  symbol: string
  name: string
  composite: number
  l3v: number
  l1Score?: number
  l3fScore?: number
  l7Score?: number
  resonance?: number
  classification: 'core' | 'hot' | 'value'
  reasons: string[]
}

export interface ClassifyStocksInput {
  stocks: Stock[]
  v6Scores: V6Score[]
  rotationScores: RotationSectorScore[]
}

function pickFactor(factors: Record<string, number> | undefined, keys: string[]): number {
  if (!factors) return 0
  for (const key of keys) {
    if (key in factors) {
      return factors[key] ?? 0
    }
  }
  return 0
}

function buildRotationScoreMap(rotationScores: RotationSectorScore[]): Map<string, RotationSectorScore> {
  const map = new Map<string, RotationSectorScore>()
  for (const score of rotationScores) {
    const keys: string[] = [
      score.sectorCode,
      score.sectorName,
      score.swLevel1,
      score.swLevel2,
      score.swLevel3,
    ].filter((k): k is string => typeof k === 'string' && k.length > 0)
    for (const key of keys) {
      if (!map.has(key)) {
        map.set(key, score)
      }
    }
  }
  return map
}

function getResonance(stock: Stock, rotationScoreMap: Map<string, RotationSectorScore>): number {
  const keys = [stock.industryCode, stock.sector].filter((k): k is string => Boolean(k))
  for (const key of keys) {
    const match = rotationScoreMap.get(key)
    if (match) {
      return match.resonance ?? 0
    }
  }
  return 0
}

function classify(
  stock: Stock,
  v6Score: V6Score | undefined,
  rotationScoreMap: Map<string, RotationSectorScore>,
): StrategyGroupItem | undefined {
  if (!v6Score) return undefined

  const factors = v6Score.factors
  const composite = v6Score.score
  const l3v = pickFactor(factors, ['L3V', '质量'])
  const l1Score = pickFactor(factors, ['L1', '估值'])
  const l3fScore = pickFactor(factors, ['L3F', '质量'])
  const l7Score = pickFactor(factors, ['L7', '情绪'])
  const resonance = getResonance(stock, rotationScoreMap)

  if (composite >= 4.0 && l7Score >= 3.5 && l1Score >= 3.5) {
    return {
      symbol: stock.symbol,
      name: stock.name,
      composite,
      l3v,
      l1Score,
      l7Score,
      resonance,
      classification: 'core',
      reasons: [
        `符合核心稀缺策略：综合分 ${composite.toFixed(2)} ≥ 4.0，估值(L1) ${l1Score.toFixed(2)} ≥ 3.5，情绪(L7) ${l7Score.toFixed(2)} ≥ 3.5`,
      ],
    }
  }

  if (composite >= 3.0 && l3v < 2.5 && resonance >= 60) {
    return {
      symbol: stock.symbol,
      name: stock.name,
      composite,
      l3v,
      l1Score,
      l3fScore,
      l7Score,
      resonance,
      classification: 'hot',
      reasons: [
        `符合热点动量策略：综合分 ${composite.toFixed(2)} ≥ 3.0，估值(L3V) ${l3v.toFixed(2)} < 2.5，板块共振 ${resonance.toFixed(2)} ≥ 60`,
      ],
    }
  }

  if (composite >= 3.0 && l3v < 3.0 && resonance < 50 && l3fScore >= 3.0) {
    return {
      symbol: stock.symbol,
      name: stock.name,
      composite,
      l3v,
      l1Score,
      l3fScore,
      l7Score,
      resonance,
      classification: 'value',
      reasons: [
        `符合价值 bargain 策略：综合分 ${composite.toFixed(2)} ≥ 3.0，估值(L3V) ${l3v.toFixed(2)} < 3.0，板块共振 ${resonance.toFixed(2)} < 50，质量(L3F) ${l3fScore.toFixed(2)} ≥ 3.0`,
      ],
    }
  }

  return undefined
}

export function classifyStocks(input: ClassifyStocksInput): StrategyGroupItem[] {
  const { stocks, v6Scores, rotationScores } = input
  const v6ScoreMap = new Map(v6Scores.map((score) => [score.symbol, score]))
  const rotationScoreMap = buildRotationScoreMap(rotationScores)

  const items: StrategyGroupItem[] = []
  for (const stock of stocks) {
    const item = classify(stock, v6ScoreMap.get(stock.symbol), rotationScoreMap)
    if (item) {
      items.push(item)
    }
  }
  return items
}

export function buildGroupSnapshot(items: StrategyGroupItem[]): StrategyGroupSnapshot {
  const count = items.length
  const composites = items.map((item) => item.composite)
  const avgComposite = count > 0 ? Math.round((composites.reduce((a, b) => a + b, 0) / count) * 100) / 100 : 0
  const maxComposite = count > 0 ? Math.max(...composites) : 0
  const symbols = items.map((item) => item.symbol)
  const snapshotItems = items.map((item) => ({
    symbol: item.symbol,
    name: item.name,
    composite: item.composite,
    classification: item.classification,
  }))

  return {
    count,
    avgComposite,
    maxComposite,
    symbols,
    items: snapshotItems,
  }
}

function snapshotItemMap(snapshot: StrategyGroupSnapshot): Map<string, { name: string; composite: number }> {
  return new Map(snapshot.items.map((item) => [item.symbol, { name: item.name, composite: item.composite }]))
}

function diffSymbols(prev: string[], current: string[]): { added: string[]; removed: string[] } {
  const prevSet = new Set(prev)
  const currentSet = new Set(current)
  const added = current.filter((symbol) => !prevSet.has(symbol))
  const removed = prev.filter((symbol) => !currentSet.has(symbol))
  return { added, removed }
}

export function buildChangeLog(
  prev: StrategySnapshot | undefined,
  current: { core: StrategyGroupSnapshot; hot: StrategyGroupSnapshot; value: StrategyGroupSnapshot; stockCount: number },
): NonNullable<StrategySnapshot['changeFromPrev']> {
  const prevCore = prev?.core
  const prevHot = prev?.hot
  const prevValue = prev?.value

  const prevTotal = (prevCore?.count ?? 0) + (prevHot?.count ?? 0) + (prevValue?.count ?? 0)
  const currentTotal = current.core.count + current.hot.count + current.value.count
  const totalChange = currentTotal - prevTotal

  const coreChange = diffSymbols(prevCore?.symbols ?? [], current.core.symbols)
  const hotChange = diffSymbols(prevHot?.symbols ?? [], current.hot.symbols)
  const valueChange = diffSymbols(prevValue?.symbols ?? [], current.value.symbols)

  const currentMap = new Map<string, { name: string; composite: number }>([
    ...snapshotItemMap(current.core),
    ...snapshotItemMap(current.hot),
    ...snapshotItemMap(current.value),
  ])

  const emptySnapshot: StrategyGroupSnapshot = { count: 0, avgComposite: 0, maxComposite: 0, symbols: [], items: [] }
  const prevMap = new Map<string, { name: string; composite: number }>([
    ...snapshotItemMap(prevCore ?? emptySnapshot),
    ...snapshotItemMap(prevHot ?? emptySnapshot),
    ...snapshotItemMap(prevValue ?? emptySnapshot),
  ])

  const scoreChanges: Array<{ symbol: string; name: string; oldComposite: number; newComposite: number; delta: number }> =
    []
  for (const [symbol, currentItem] of currentMap.entries()) {
    const prevItem = prevMap.get(symbol)
    if (!prevItem) continue
    const delta = Math.round((currentItem.composite - prevItem.composite) * 100) / 100
    if (Math.abs(delta) >= 0.3) {
      scoreChanges.push({
        symbol,
        name: currentItem.name,
        oldComposite: prevItem.composite,
        newComposite: currentItem.composite,
        delta,
      })
    }
  }

  return {
    totalChange,
    coreChange,
    hotChange,
    valueChange,
    scoreChanges,
  }
}

export async function getNextVersion(): Promise<number> {
  const latestResult = await getLatestSnapshot()
  if (!latestResult.success || !latestResult.data) {
    return 1
  }
  return latestResult.data.version + 1
}

export async function saveStrategySnapshot(
  input: ClassifyStocksInput,
  trigger?: string,
): Promise<DataLayerResult<StrategySnapshot>> {
  try {
    const items = classifyStocks(input)
    const coreItems = items.filter((item) => item.classification === 'core')
    const hotItems = items.filter((item) => item.classification === 'hot')
    const valueItems = items.filter((item) => item.classification === 'value')

    const core = buildGroupSnapshot(coreItems)
    const hot = buildGroupSnapshot(hotItems)
    const value = buildGroupSnapshot(valueItems)

    const prevResult = await getLatestSnapshot()
    const prevSnapshot = prevResult.success ? prevResult.data : undefined

    const changeFromPrev = buildChangeLog(prevSnapshot, {
      core,
      hot,
      value,
      stockCount: input.stocks.length,
    })

    const nextVersion = await getNextVersion()
    const timestamp = Date.now()

    const snapshot: StrategySnapshot = {
      id: `snapshot_${timestamp}`,
      version: nextVersion,
      timestamp,
      date: new Date().toISOString().slice(0, 10),
      time: new Date().toTimeString().slice(0, 8),
      stockCount: input.stocks.length,
      scoreCount: input.v6Scores.length,
      rotationCount: input.rotationScores.length,
      core,
      hot,
      value,
      changeFromPrev,
      trigger: trigger ?? 'manual',
    }

    const result = await dataLayer.strategySnapshots.save(snapshot)
    if (!result.success) {
      return { success: false, error: result.error }
    }
    return { success: true, data: snapshot }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error('保存策略快照失败', { error: message })
    return { success: false, error: message }
  }
}

export async function getLatestSnapshot(): Promise<DataLayerResult<StrategySnapshot | undefined>> {
  try {
    const snapshot = await dataLayer.strategySnapshots.getLatest()
    return { success: true, data: snapshot }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error('获取最新策略快照失败', { error: message })
    return { success: false, error: message }
  }
}

export async function listSnapshots(limit?: number): Promise<DataLayerResult<StrategySnapshot[]>> {
  try {
    const list = await dataLayer.strategySnapshots.list()
    const sorted = list.sort((a, b) => b.timestamp - a.timestamp)
    return { success: true, data: limit ? sorted.slice(0, limit) : sorted }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error('列出策略快照失败', { error: message })
    return { success: false, error: message }
  }
}

