    },
  ]

  // 6. 里程碑（与 tradeReview.types.ts 对齐）
  const milestones: SkillDevelopment['milestones'] = dimensions.map((d, idx) => ({
    id: `milestone_${d.code}_${Date.now()}_${idx}`,
