/**
 * 交易复盘 AI 工具函数
 *
 * 提供共享的辅助函数，避免循环依赖
 */

import type { Order } from '@/data/types'
import type { TradePair } from './tradeReviewAI.types'

/**
 * 将订单配对为交易对（买→卖）
 */
export function buildTradePairs(orders: Order[]): TradePair[] {
  const pairs: TradePair[] = []
  const bySymbol = new Map<string, Order[]>()

  for (const order of orders) {
    const list = bySymbol.get(order.symbol) ?? []
    list.push(order)
    bySymbol.set(order.symbol, list)
  }

  for (const [, symOrders] of bySymbol) {
    symOrders.sort((a, b) => a.createdAt - b.createdAt)
    const buys: Order[] = []
    for (const order of symOrders) {
      if (order.direction === 'buy') {
        buys.push(order)
      } else if (buys.length > 0) {
        const buy = buys.shift()!
        const profitPct = ((order.price - buy.price) / buy.price) * 100
        const holdDays = Math.round((order.createdAt - buy.createdAt) / (24 * 60 * 60 * 1000))
        pairs.push({
          buyId: buy.id,
          sellId: order.id,
          profitPct: Math.round(profitPct * 100) / 100,
          holdDays,
        })
      }
    }
  }

  return pairs
}

import { dataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import {
  MODULE_ID,
  ENVELOPE_TARGET,
  ENVELOPE_ACTION,
  ORDER_DIRECTION,
  ORDER_STATUS,
  RESEARCH_STATUS,
} from '@/config/dbConfig'
import { getDefaultTradingConfig } from '@/config/tradingConfig'
import { dataLayer } from '@/data/dataLayer'
import type { DataLayerResult, Order, Stock } from '@/data/types'
import {
  generateSignalsForSymbol,
  pickStrongestSignal,
  type TradingSignal,
} from './signalGenerator'
import { calculatePosition, type PositionSizingResult } from './positionSizer'
import { checkOrderRisk, type RiskCheckResult } from './riskEngine'

export interface CreateOrderInput {
  symbol: string
  direction: 'buy' | 'sell'
  quantity: number
  price: number
  accountType?: 'paper' | 'real'
}

const DEFAULT_BUY_QUANTITY = 100

function generateId(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
}

function buildOrder(input: CreateOrderInput): Order {
  const quantity = Math.max(1, Math.floor(input.quantity))
  const price = Math.max(0, input.price)
  const amount = price * quantity

  return {
    id: generateId(),
    symbol: input.symbol,
    direction: input.direction === 'buy' ? ORDER_DIRECTION.buy : ORDER_DIRECTION.sell,
    quantity,
    price,
    amount,
    status: ORDER_STATUS.filled,
    accountType: input.accountType ?? 'paper',
    createdAt: Date.now(),
  }
}

export interface TradeAdvice {
  signal: TradingSignal
  sizing: PositionSizingResult
  risk: RiskCheckResult
}

async function computePositionForSignal(
  signal: TradingSignal,
  stock: Stock,
): Promise<DataLayerResult<PositionSizingResult>> {
  if (stock.price === undefined || stock.price <= 0) {
    return { success: false, error: '股票价格无效' }
  }

  const orders = await dataLayer.orders.list()
  const price = stock.price
  const portfolioValue = getDefaultTradingConfig().risk.portfolioValue

  const holdingShares = orders
    .filter((o) => o.symbol === signal.symbol)
    .reduce((sum, o) => sum + (o.direction === ORDER_DIRECTION.buy ? o.quantity : -o.quantity), 0)
  const holdingValue = holdingShares * price

  const totalValue = orders.reduce(
    (sum, o) => sum + (o.direction === ORDER_DIRECTION.buy ? o.quantity : -o.quantity) * o.price,
    0,
  )

  return {
    success: true,
    data: calculatePosition({
      direction: signal.direction,
      price,
      portfolioValue,
      currentHoldingShares: holdingShares,
      currentHoldingValue: holdingValue,
      currentTotalPositionValue: totalValue,
    }),
  }
}

/**
 * 扫描观察池全部股票的交易信号
 */
export async function scanWatchingSignals(): Promise<TradingSignal[]> {
  const result = await getWatchlistStocks()
  if (!result.success || !result.data) return []

  const allSignals: TradingSignal[] = []
  for (const stock of result.data) {
    const signals = await generateSignalsForSymbol(stock.symbol)
    for (const signal of signals) {
      const envelope = EnvelopeFactory.create(
        {
          source: MODULE_ID.tradinghub,
          target: ENVELOPE_TARGET.db,
          action: ENVELOPE_ACTION.insertSignal,
          traceId: `signal-${Date.now()}-${signal.symbol}`,
        },
        signal,
      )
      await dataBridge.forward(envelope)
    }
    allSignals.push(...signals)
  }
  return allSignals
}

/**
 * 为单只股票生成交易建议：信号 + 仓位 + 风控
 */
export async function adviseForStock(stock: Stock): Promise<DataLayerResult<TradeAdvice>> {
  if (!stock.symbol) {
    return { success: false, error: '股票代码不能为空' }
  }

  const signals = await generateSignalsForSymbol(stock.symbol)
  const signal = pickStrongestSignal(signals)
  if (!signal) {
    return { success: false, error: '未生成有效信号' }
  }

  // watch / hold 为非交易信号，直接返回中性建议，避免无意义的风控/仓位计算
  if (signal.direction === 'watch' || signal.direction === 'hold') {
    return {
      success: true,
      data: {
        signal,
        sizing: {
          action: 'hold',
          targetShares: 0,
          targetValue: 0,
          positionPct: 0,
          kellyPct: 0,
          roundedDown: false,
          cappedBy: 'none',
        },
        risk: { ok: true, warnings: [], blocks: [] },
      },
    }
  }

  const sizingResult = await computePositionForSignal(signal, stock)
  if (!sizingResult.success || !sizingResult.data) {
    return { success: false, error: sizingResult.error ?? '仓位计算失败' }
  }
  const sizing = sizingResult.data
  const price = stock.price
  if (price === undefined || price <= 0) {
    return { success: false, error: '股票价格无效' }
  }
  const risk = await checkOrderRisk({
    symbol: stock.symbol,
    direction: signal.direction,
    quantity: sizing.targetShares,
    price,
    portfolioValue: getDefaultTradingConfig().risk.portfolioValue,
  })

  return { success: true, data: { signal, sizing, risk } }
}

async function createOrderWithRiskCheck(
  input: CreateOrderInput,
): Promise<DataLayerResult<Order>> {
  const price = Math.max(0, input.price)
  if (price <= 0 || input.quantity <= 0) {
    return { success: false, error: '价格或数量非法' }
  }

  const risk = await checkOrderRisk({
    symbol: input.symbol,
    direction: input.direction,
    quantity: input.quantity,
    price,
    portfolioValue: getDefaultTradingConfig().risk.portfolioValue,
  })

  if (!risk.ok) {
    return {
      success: false,
      error: `风控未通过：${risk.blocks.join('；')}`,
    }
  }

  const order = buildOrder(input)

  const envelope = EnvelopeFactory.create(
    {
      source: MODULE_ID.tradinghub,
      target: ENVELOPE_TARGET.db,
      action: ENVELOPE_ACTION.insertOrder,
      traceId: `trading-${Date.now()}-${input.symbol}`,
    },
    order,
  )

  try {
    await dataBridge.forward(envelope)
    return { success: true, data: order }
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

/**
 * 获取观察池中的股票列表
 */
export async function getWatchlistStocks(): Promise<DataLayerResult<Stock[]>> {
  try {
    const list = await dataLayer.stocks.listByStatus(RESEARCH_STATUS.watching)
    return { success: true, data: list }
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

/**
 * 获取全部订单
 */
export async function getOrders(): Promise<DataLayerResult<Order[]>> {
  try {
    const list = await dataLayer.orders.list()
    return { success: true, data: list }
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

/**
 * 创建买入订单
 *
 * 通过 DataBridge.forward() 写入，确保 ACL 校验与审计日志。
 */
export async function createBuyOrder(
  stock: Stock,
  quantity: number = DEFAULT_BUY_QUANTITY,
): Promise<DataLayerResult<Order>> {
  if (!stock.symbol) {
    return { success: false, error: '股票代码不能为空' }
  }
  if (stock.price === undefined || stock.price <= 0) {
    return { success: false, error: '价格或数量非法' }
  }

  return createOrderWithRiskCheck({
    symbol: stock.symbol,
    direction: 'buy',
    quantity,
    price: stock.price,
  })
}

/**
 * 创建卖出订单
 */
export async function createSellOrder(
  stock: Stock,
  quantity: number = DEFAULT_BUY_QUANTITY,
): Promise<DataLayerResult<Order>> {
  if (!stock.symbol) {
    return { success: false, error: '股票代码不能为空' }
  }
  if (stock.price === undefined || stock.price <= 0) {
    return { success: false, error: '价格或数量非法' }
  }

  return createOrderWithRiskCheck({
    symbol: stock.symbol,
    direction: 'sell',
    quantity,
    price: stock.price,
  })
}

/**
 * @module services/useCase/createExecutionPlan.useCase
 * @description 创建执行计划用例 — 从 executionStore.createPlan 提取的业务编排逻辑
 *
 * 业务流程（5步）：
 * 1. 获取股票信息（股价）用于仓位计算
 * 2. 计算当前持仓 & 仓位 sizing（Kelly 公式）
 * 3. 风控检查（阻断/警告）
 * 4. 构造 ExecutionPlan 对象
 * 5. 通过 dataLayer 持久化
 *
 * @see Clean Architecture Use Case Interactor 模式
 */

import { getLogger } from '@/lib/logger'
import { dataLayer } from '@/data/dataLayer'
import type { AccountType } from '@/config/dbConfig'
import type { Signal, ExecutionPlan, RiskCheckItem } from '@/data/types'
import { getDefaultTradingConfig } from '@/config/tradingConfig'
import { calculatePosition, type PositionSizingResult } from '@/services/trading/positionSizer'
import { checkOrderRisk, type RiskCheckResult } from '@/services/trading/riskEngine'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

export interface CreateExecutionPlanInput {
  /** 交易信号 */
  signal: Signal
  /** 账户类型，默认 'paper' */
  accountType?: AccountType
}

export interface CreateExecutionPlanResult {
  /** 是否成功 */
  success: boolean
  /** 创建的执行计划（失败时为 undefined） */
  plan?: ExecutionPlan
  /** 错误信息（成功时为 undefined） */
  error?: string
}

// ============================================================
// 工具函数
// ============================================================

/** 生成执行计划 ID */
function generatePlanId(): string {
  return `ep-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`
}

// ============================================================
// UseCase
// ============================================================

/**
 * 创建执行计划用例
 *
 * 根据交易信号获取股价、计算仓位、执行风控检查，
 * 构造 ExecutionPlan 并持久化到 dataLayer。
 *
 * @param input 创建参数
 * @returns 创建结果（包含 plan 或 error）
 */
export async function createExecutionPlanUseCase(
  input: CreateExecutionPlanInput,
): Promise<CreateExecutionPlanResult> {
  const { signal, accountType } = input
  const planId = generatePlanId()

  logger.info('[createExecutionPlanUseCase] 开始', {
    planId,
    signalId: signal.id,
    symbol: signal.symbol,
    direction: signal.direction,
  })

  // 非交易信号（hold/watch）不创建执行计划
  if (signal.direction === 'hold' || signal.direction === 'watch') {
    logger.info('[createExecutionPlanUseCase] 跳过: direction 为 hold/watch', {
      symbol: signal.symbol,
    })
    return { success: false, error: '非交易信号，不创建执行计划' }
  }

  try {
    // 1. 获取股票信息用于仓位计算
    const stock = await dataLayer.stocks.get(signal.symbol)
    const price = stock?.price ?? 0
    if (!stock?.price) {
      logger.warn('[createExecutionPlanUseCase] 股价缺失，使用零值', {
        symbol: stock?.symbol ?? signal.symbol,
      })
    }

    // 2. 计算仓位
    const orders = await dataLayer.orders.list()
    const portfolioValue = getDefaultTradingConfig().risk.portfolioValue

    const holdingShares = orders
      .filter((o) => o.symbol === signal.symbol)
      .reduce((sum, o) => sum + (o.direction === 'buy' ? o.quantity : -o.quantity), 0)
    const holdingValue = holdingShares * price

    const totalShares = orders.reduce(
      (sum, o) => sum + (o.direction === 'buy' ? o.quantity : -o.quantity),
      0,
    )
    const totalValue = totalShares * price

    const sizingResult: PositionSizingResult = calculatePosition({
      direction: signal.direction as 'buy' | 'sell' | 'hold',
      price,
      portfolioValue,
      currentHoldingShares: holdingShares,
      currentHoldingValue: holdingValue,
      currentTotalPositionValue: totalValue,
    })

    // 3. 风控检查
    const riskResult: RiskCheckResult = await checkOrderRisk({
      symbol: signal.symbol,
      direction: signal.direction as 'buy' | 'sell' | 'hold' | 'watch',
      quantity: sizingResult.targetShares,
      price,
      portfolioValue,
    })

    // 将风控结果转换为 RiskCheckItem[]
    const riskChecks: RiskCheckItem[] = []
    for (const block of riskResult.blocks) {
      riskChecks.push({
        id: `risk-${planId}-block-${riskChecks.length}`,
        name: 'blocker',
        label: '风控阻断',
        passed: false,
        message: block,
        detail: block,
        severity: 'blocker',
      })
    }
    for (const warning of riskResult.warnings) {
      riskChecks.push({
        id: `risk-${planId}-warn-${riskChecks.length}`,
        name: 'warning',
        label: '风控预警',
        passed: true,
        message: warning,
        detail: warning,
        severity: 'warning',
      })
    }

    const hasBlocker = riskResult.blocks.length > 0

    // 4. 生成 ExecutionPlan
    const plan: ExecutionPlan = {
      id: planId,
      signalId: signal.id,
      symbol: signal.symbol,
      name: signal.symbol,
      direction: signal.direction === 'buy' || signal.direction === 'sell'
        ? signal.direction
        : 'buy',
      quantity: sizingResult.targetShares,
      targetPrice: price,
      rationale: sizingResult.cappedBy !== 'none'
        ? `仓位受${sizingResult.cappedBy}上限约束`
        : 'Kelly 公式计算',
      phase: 'plan',
      confidence: signal.confidence,
      riskChecks,
      sizing: {
        quantity: sizingResult.targetShares,
        positionPct: sizingResult.positionPct,
        reason: sizingResult.cappedBy !== 'none'
          ? `仓位受${sizingResult.cappedBy}上限约束`
          : 'Kelly 公式计算',
      },
      risk: {
        passed: !hasBlocker,
        preCheck: true,
        postCheck: false,
        issueCount: riskResult.blocks.length,
        checks: riskChecks,
        warnings: riskResult.warnings,
      },
      accountType: accountType ?? 'paper',
      createdAt: Date.now(),
      result: hasBlocker ? 'failed' : undefined,
      errorMessage: hasBlocker ? riskResult.blocks.join('；') : undefined,
    }

    // 5. 持久化
    await dataLayer.executionPlans.save(plan)

    logger.info('[createExecutionPlanUseCase] 创建成功', {
      planId,
      symbol: signal.symbol,
      passed: plan.risk?.passed,
      quantity: plan.sizing?.quantity,
    })

    return { success: true, plan }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error('[createExecutionPlanUseCase] 创建失败', {
      error: message,
      symbol: signal.symbol,
    })
    return { success: false, error: message }
  }
}

/**
 * @module services/useCase/executePlan.useCase
 * @lifecycle @Global
 * @description 执行计划用例 — 将 executionStore.executePlan 中的多步骤编排逻辑提取为独立用例
 *
 * 业务流程（6步）：
 * 1. 设置 isProcessing 状态
 * 2. 更新计划状态为 pending
 * 3. 获取最新股票价格
 * 4. 根据 direction 创建买入/卖出订单
 * 5. 根据结果更新计划状态为 executed 或 cancelled
 * 6. 清理 isProcessing
 *
 * @see Clean Architecture Use Case Interactor 模式
 */

import { getLogger } from '@/lib/logger'
import { runInTransaction } from '@/core/transaction'
import { STORE_NAME } from '@/config/dbConfig'
import type { ExecutionPlan, Stock } from '@/data/types'

// 注意：dataLayer 通过 runInTransaction 间接使用，无需直接导入

const logger = getLogger()

export interface ExecutePlanContext {
  /** 获取执行计划 */
  getPlan: (planId: string) => ExecutionPlan | undefined
  /** 更新执行计划状态 */
  updatePlanState: (planId: string, updates: Partial<ExecutionPlan>) => void
  /** 设置处理中标志 */
  setProcessing: (planId: string, isProcessing: boolean) => void
  /** 创建买入订单 */
  createBuyOrder: (symbol: string, price: number, quantity: number) => Promise<string | null>
  /** 创建卖出订单 */
  createSellOrder: (symbol: string, price: number, quantity: number) => Promise<string | null>
}

export interface ExecutePlanResult {
  success: boolean
  planId: string
  orderId?: string
  error?: string
  phase: ExecutionPlan['phase']
}

/**
 * 执行交易计划用例
 *
 * @param planId 计划ID
 * @param ctx 依赖上下文（由调用方注入 Store action）
 * @returns 执行结果
 */
export async function executePlanUseCase(
  planId: string,
  ctx: ExecutePlanContext,
): Promise<ExecutePlanResult> {
  logger.info(`[executePlanUseCase] 开始执行计划: ${planId}`)

  // Step 1: 设置处理中状态
  ctx.setProcessing(planId, true)

  try {
    const plan = ctx.getPlan(planId)
    if (!plan) {
      throw new Error(`计划不存在: ${planId}`)
    }

    if (plan.phase !== 'confirmed') {
      throw new Error(`计划状态不允许执行（当前: ${plan.phase}，需 confirmed）`)
    }

    // Step 2: 更新为 pending
    ctx.updatePlanState(planId, { phase: 'pending' })
    logger.info(`[executePlanUseCase] 计划 ${planId} 状态更新为 pending`)

    // Step 3: 在事务中获取最新价格（保证读取一致性）
    const stock = await runInTransaction<Stock | undefined>(
      [STORE_NAME.stocks],
      'readonly',
      async (tx) => {
        const store = tx.objectStore(STORE_NAME.stocks)
        return new Promise<Stock | undefined>((resolve, reject) => {
          const request = store.get(plan.symbol)
          request.onsuccess = () => resolve(request.result as Stock | undefined)
          request.onerror = () => reject(request.error instanceof Error ? request.error : new Error(String(request.error)))
        })
      },
    )

    if (!stock) {
      throw new Error(`股票 ${plan.symbol} 不存在`)
    }

    const currentPrice = stock.price ?? 0
    if (currentPrice <= 0) {
      throw new Error(`股票 ${plan.symbol} 当前价格无效: ${currentPrice}`)
    }

    logger.info(`[executePlanUseCase] 获取价格成功: ${plan.symbol} = ${currentPrice}`)

    // Step 4: 根据 direction 创建订单
    const quantity = plan.sizing?.quantity ?? 0
    if (quantity <= 0 || !Number.isFinite(quantity)) {
      throw new Error(`计划 ${planId} 交易数量无效: ${quantity}`)
    }

    let orderId: string | null = null

    if (plan.direction === 'buy') {
      orderId = await ctx.createBuyOrder(plan.symbol, currentPrice, quantity)
    } else if (plan.direction === 'sell') {
      orderId = await ctx.createSellOrder(plan.symbol, currentPrice, quantity)
    } else {
      throw new Error(`不支持的方向: ${String(plan.direction)}`)
    }

    // Step 5: 根据结果更新计划状态
    if (orderId) {
      ctx.updatePlanState(planId, {
        phase: 'executed',
        executedAt: Date.now(),
        orderId,
      })
      logger.info(`[executePlanUseCase] 计划 ${planId} 执行成功, orderId=${orderId}`)

      return {
        success: true,
        planId,
        orderId,
        phase: 'executed',
      }
    } else {
      ctx.updatePlanState(planId, {
        phase: 'cancelled',
        errorMessage: '订单创建失败',
      })
      logger.warn(`[executePlanUseCase] 计划 ${planId} 因订单创建失败而取消`)

      return {
        success: false,
        planId,
        error: '订单创建失败',
        phase: 'cancelled',
      }
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error(`[executePlanUseCase] 计划 ${planId} 执行异常: ${message}`)

    ctx.updatePlanState(planId, {
      phase: 'cancelled',
      errorMessage: message,
    })

    return {
      success: false,
      planId,
      error: message,
      phase: 'cancelled',
    }
  } finally {
    // Step 6: 清理处理中状态
    ctx.setProcessing(planId, false)
  }
}

/**
 * @module services/useCase/fetchSectorAnalysis.useCase
 * @description 板块分析数据加载用例 — 从 sectorAnalysisStore.fetchSectorAnalysis 提取的业务编排逻辑
 *
 * 业务流程（4步）：
 * 1. 并行查询板块轮动评分 + 行业评分
 * 2. 空数据时触发默认计算（calculateAndSaveDefault*）
 * 3. 排序（轮动按 total 降序，行业按 scoredAt 降序）
 * 4. 返回合并结果
 *
 * @see Clean Architecture Use Case Interactor 模式
 */

import { getLogger } from '@/lib/logger'
import type { RotationSectorScore, IndustryScore } from '@/data/types'
import {
  calculateAndSaveDefaultRotationScores,
  calculateAndSaveDefaultIndustryScores,
  getRotationScores,
  getIndustryScores,
} from '@/services/analysis/sectorAnalysisEngine'

const logger = getLogger()

// ============================================================
// 类型定义
// ============================================================

export interface FetchSectorAnalysisInput {
  /** 预留：未来可扩展过滤条件（如日期范围、行业筛选等） */
  _filter?: undefined
}

export interface FetchSectorAnalysisResult {
  /** 是否成功 */
  success: boolean
  /** 板块轮动评分列表（按 total 降序） */
  rotationScores: RotationSectorScore[]
  /** 行业评分列表（按 scoredAt 降序） */
  industryScores: IndustryScore[]
  /** 错误信息（成功时为 undefined） */
  error?: string
}

// ============================================================
// UseCase
// ============================================================

/**
 * 板块分析数据加载用例
 *
 * 并行查询板块轮动评分和行业评分，空数据时自动触发默认计算，
 * 排序后返回合并结果。
 *
 * @param _input 查询参数（预留扩展）
 * @returns 合并后的板块分析数据
 */
export async function fetchSectorAnalysisUseCase(
  _input: FetchSectorAnalysisInput = {},
): Promise<FetchSectorAnalysisResult> {
  logger.info('[fetchSectorAnalysisUseCase] 开始加载板块分析数据')

  try {
    // 1. 并行查询板块轮动评分 + 行业评分
    logger.info('[fetchSectorAnalysisUseCase] 发起并行查询', {
      channels: ['rotation_scores', 'industry_scores'],
    })
    const [rotationResult, industryResult] = await Promise.all([
      getRotationScores(),
      getIndustryScores(),
    ])
    logger.info('[fetchSectorAnalysisUseCase] 并行查询返回', {
      rotationSuccess: rotationResult.success,
      rotationCount: rotationResult.data?.length ?? 0,
      industrySuccess: industryResult.success,
      industryCount: industryResult.data?.length ?? 0,
    })

    let rotation: RotationSectorScore[] = []
    let industry: IndustryScore[] = []

    // 2a. 处理板块轮动评分
    if (!rotationResult.success) {
      logger.error('[fetchSectorAnalysisUseCase] 板块轮动评分查询失败', {
        error: rotationResult.error,
      })
      return {
        success: false,
        rotationScores: [],
        industryScores: [],
        error: rotationResult.error ?? '板块轮动评分查询失败',
      }
    }

    if (rotationResult.data && rotationResult.data.length > 0) {
      rotation = rotationResult.data
      const sample = rotation[0]
      logger.info('[fetchSectorAnalysisUseCase] 加载板块轮动评分', {
        count: rotation.length,
        sample: sample
          ? { id: sample.id, sectorName: sample.sectorName, total: sample.total, alertLevel: sample.alertLevel }
          : null,
      })
    } else {
      // 数据为空时，计算并保存默认评分
      logger.info('[fetchSectorAnalysisUseCase] 板块轮动评分为空，计算默认数据')
      const calcResult = await calculateAndSaveDefaultRotationScores()
      if (calcResult.success && calcResult.data) {
        rotation = calcResult.data
        const sample = rotation[0]
        logger.info('[fetchSectorAnalysisUseCase] 默认板块轮动评分计算成功', {
          count: rotation.length,
          sample: sample
            ? { id: sample.id, sectorName: sample.sectorName, total: sample.total }
            : null,
        })
      } else if (calcResult.error) {
        logger.error('[fetchSectorAnalysisUseCase] 计算默认板块轮动评分失败', {
          error: calcResult.error,
        })
        return {
          success: false,
          rotationScores: [],
          industryScores: [],
          error: calcResult.error,
        }
      }
    }

    // 2b. 处理行业评分
    if (!industryResult.success) {
      logger.error('[fetchSectorAnalysisUseCase] 行业评分查询失败', {
        error: industryResult.error,
      })
      return {
        success: false,
        rotationScores: [],
        industryScores: [],
        error: industryResult.error ?? '行业评分查询失败',
      }
    }

    if (industryResult.data && industryResult.data.length > 0) {
      industry = industryResult.data
      const sample = industry[0]
      logger.info('[fetchSectorAnalysisUseCase] 加载行业评分', {
        count: industry.length,
        sample: sample
          ? { id: sample.id, name: sample.name, overallScore: sample.overallScore, model: sample.configSnapshot.model }
          : null,
      })
    } else {
      // 数据为空时，计算并保存默认评分
      logger.info('[fetchSectorAnalysisUseCase] 行业评分为空，计算默认数据')
      const calcResult = await calculateAndSaveDefaultIndustryScores()
      if (calcResult.success && calcResult.data) {
        industry = calcResult.data
        const sample = industry[0]
        logger.info('[fetchSectorAnalysisUseCase] 默认行业评分计算成功', {
          count: industry.length,
          sample: sample
            ? { id: sample.id, name: sample.name, overallScore: sample.overallScore }
            : null,
        })
      } else if (calcResult.error) {
        logger.error('[fetchSectorAnalysisUseCase] 计算默认行业评分失败', {
          error: calcResult.error,
        })
        return {
          success: false,
          rotationScores: [],
          industryScores: [],
          error: calcResult.error,
        }
      }
    }

    // 3. 排序
    // 板块轮动按 total 降序
    const sortedRotation = [...rotation].sort((a, b) => b.total - a.total)

    // 行业评分按 scoredAt 降序（无时间戳的条目排至末尾）
    const missingTimestampIndustry = industry.filter((i) => i.scoredAt == null)
    if (missingTimestampIndustry.length > 0) {
      logger.warn('[fetchSectorAnalysisUseCase] scoredAt 缺失，条目排至末尾', {
        missingCount: missingTimestampIndustry.length,
        totalCount: industry.length,
      })
    }
    const sortedIndustry = [...industry].sort((a, b) => {
      const aTime = a.scoredAt ?? 0
      const bTime = b.scoredAt ?? 0
      if (aTime === 0 && bTime === 0) return 0
      if (aTime === 0) return 1
      if (bTime === 0) return -1
      return bTime - aTime
    })

    logger.info('[fetchSectorAnalysisUseCase] 排序完成', {
      rotationTop: sortedRotation[0]
        ? { sectorName: sortedRotation[0].sectorName, total: sortedRotation[0].total }
        : null,
      rotationBottom: sortedRotation[sortedRotation.length - 1]
        ? { sectorName: sortedRotation[sortedRotation.length - 1]!.sectorName, total: sortedRotation[sortedRotation.length - 1]!.total }
        : null,
      industryLatest: sortedIndustry[0]
        ? { name: sortedIndustry[0].name, scoredAt: sortedIndustry[0].scoredAt }
        : null,
    })

    logger.info('[fetchSectorAnalysisUseCase] 数据加载完成', {
      rotation: sortedRotation.length,
      industry: sortedIndustry.length,
    })

    return {
      success: true,
      rotationScores: sortedRotation,
      industryScores: sortedIndustry,
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    const stack = err instanceof Error ? err.stack : undefined
    logger.error('[fetchSectorAnalysisUseCase] 数据加载失败', { error: message, stack })
    return {
      success: false,
      rotationScores: [],
      industryScores: [],
      error: message,
    }
  }
}

/**
 * @module services/useCase/getUnifiedStockView.useCase
 * @description 统一股票视图融合用例
 *
 * 将原先 unifiedStockService 中跨 dataLayer 多源读取的长流程逻辑抽取为 UseCase，
 * 使 Service 层保持薄入口，复杂编排下沉到 UseCase。
 */

import { dataLayer } from '@/data/dataLayer'
import { getLogger } from '@/lib/logger'
import type {
  DailyQuotes,
  DataLayerResult,
  IndustryScore,
  IntelligentScore,
  PortfolioHolding,
  RotationSectorScore,
  Signal,
  Stock,
  V6Score,
} from '@/data/types'

const logger = getLogger()

export interface UnifiedStockView {
  /** 股票基础信息 */
  stock: Stock
  /** K线数据（可选） */
  quotes?: DailyQuotes
  /** V6 自动评分（可选） */
  v6Score?: V6Score
  /** 智能评分（可选） */
  intelligentScore?: IntelligentScore
  /** 行业评分（可选） */
  industryScore?: IndustryScore
  /** 板块轮动评分（可选） */
  rotationScore?: RotationSectorScore
  /** 最新信号（可选） */
  signal?: Signal
  /** 持仓信息（可选） */
  holding?: PortfolioHolding
  /** 数据质量指标 */
  quality: {
    /** 数据完整度 (0-100) */
    completeness: number
    /** 数据新鲜度（最新更新时间） */
    freshness: number
    /** 缺失数据源列表 */
    missing: string[]
  }
  /** 融合时间戳 */
  fusedAt: number
}

export interface FusionOptions {
  includeQuotes?: boolean
  includeV6Score?: boolean
  includeIntelligentScore?: boolean
  includeIndustryScore?: boolean
  includeRotationScore?: boolean
  includeSignal?: boolean
  includeHolding?: boolean
}

const DEFAULT_OPTIONS: FusionOptions = {
  includeQuotes: true,
  includeV6Score: true,
  includeIntelligentScore: false,
  includeIndustryScore: false,
  includeRotationScore: false,
  includeSignal: false,
  includeHolding: false,
}

export async function getUnifiedStockViewUseCase(
  symbol: string,
  options: FusionOptions = DEFAULT_OPTIONS,
): Promise<DataLayerResult<UnifiedStockView>> {
  try {
    const opts = { ...DEFAULT_OPTIONS, ...options }

    const stock = await dataLayer.stocks.get(symbol)
    if (!stock) {
      return { success: false, error: `Stock not found: ${symbol}` }
    }

    const missing: string[] = []
    const timestamps: number[] = [stock.updatedAt ?? Date.now()]

    let quotes: DailyQuotes | undefined
    if (opts.includeQuotes) {
      quotes = await dataLayer.dailyQuotes.get(symbol)
      if (quotes) {
        timestamps.push(quotes.updatedAt ?? Date.now())
      } else {
        missing.push('quotes')
      }
    }

    let v6Score: V6Score | undefined
    if (opts.includeV6Score) {
      v6Score = await dataLayer.v6Scores.get(symbol)
      if (v6Score) {
        timestamps.push(v6Score.calculatedAt)
      } else {
        missing.push('v6Score')
      }
    }

    let intelligentScore: IntelligentScore | undefined
    if (opts.includeIntelligentScore) {
      intelligentScore = await dataLayer.intelligentScores.getLatestBySymbol(symbol)
      if (intelligentScore) {
        timestamps.push(intelligentScore.scoredAt)
      } else {
        missing.push('intelligentScore')
      }
    }

    let industryScore: IndustryScore | undefined
    if (opts.includeIndustryScore) {
      const scores = await dataLayer.industryScores.listByCode(stock.sector ?? '')
      industryScore = scores[0]
      if (industryScore) {
        timestamps.push(industryScore.scoredAt)
      } else {
        missing.push('industryScore')
      }
    }

    let rotationScore: RotationSectorScore | undefined
    if (opts.includeRotationScore) {
      const scores = await dataLayer.rotationScores.list()
      rotationScore = scores.find((s) => s.sectorCode === stock.industryCode)
      if (rotationScore) {
        timestamps.push(rotationScore.createdAt ? new Date(rotationScore.createdAt).getTime() : Date.now())
      } else {
        missing.push('rotationScore')
      }
    }

    let signal: Signal | undefined
    if (opts.includeSignal) {
      const signals = await dataLayer.signals.listBySymbol(symbol)
      signal = signals[0]
      if (signal) {
        timestamps.push(signal.createdAt)
      } else {
        missing.push('signal')
      }
    }

    let holding: PortfolioHolding | undefined
    if (opts.includeHolding) {
      // TODO: 待 dataLayer 实现 holdings 存储后启用
      missing.push('holding')
    }

    const totalSources = Object.keys(opts).filter((k) => k.startsWith('include') && opts[k as keyof FusionOptions]).length
    const completeness = ((totalSources - missing.length) / totalSources) * 100
    const freshness = Math.max(...timestamps)

    logger.info(`[GetUnifiedStockViewUseCase] ${symbol} 融合完成`, {
      completeness: `${completeness.toFixed(0)}%`,
      missing,
      sources: totalSources,
    })

    return {
      success: true,
      data: {
        stock,
        quotes,
        v6Score,
        intelligentScore,
        industryScore,
        rotationScore,
        signal,
        holding,
        quality: {
          completeness,
          freshness,
          missing,
        },
        fusedAt: Date.now(),
      },
    }
  } catch (err) {
    const error = err instanceof Error ? err.message : String(err)
    logger.error(`[GetUnifiedStockViewUseCase] ${symbol} 融合失败`, { error })
    return { success: false, error }
  }
}

export async function getUnifiedStockViewsUseCase(
  symbols: string[],
  options: FusionOptions = DEFAULT_OPTIONS,
): Promise<DataLayerResult<UnifiedStockView[]>> {
  try {
    const results = await Promise.all(symbols.map((symbol) => getUnifiedStockViewUseCase(symbol, options)))
    const failed = results.filter((r) => !r.success)
    if (failed.length > 0) {
      const errors = failed.map((r) => r.error ?? 'unknown').join('; ')
      logger.warn(`[GetUnifiedStockViewsUseCase] 批量融合部分失败`, { failed: failed.length, total: symbols.length })
      return { success: false, error: errors }
    }
    return { success: true, data: results.map((r) => r.data!) }
  } catch (err) {
    const error = err instanceof Error ? err.message : String(err)
    logger.error('[GetUnifiedStockViewsUseCase] 批量融合失败', { error })
    return { success: false, error }
  }
}

export async function getUnifiedStockViewsByStatusUseCase(
  status: string,
  options: FusionOptions = DEFAULT_OPTIONS,
): Promise<DataLayerResult<UnifiedStockView[]>> {
  try {
    const stocks = await dataLayer.stocks.list()
    const filtered = stocks.filter((s) => s.researchStatus === status)
    return getUnifiedStockViewsUseCase(filtered.map((s) => s.symbol), options)
  } catch (err) {
    const error = err instanceof Error ? err.message : String(err)
    return { success: false, error }
  }
}

export async function getScoreViewUseCase(symbol: string): Promise<DataLayerResult<{
  stock: Stock
  v6Score?: V6Score
  intelligentScore?: IntelligentScore
  industryScore?: IndustryScore
  completeness: number
}>> {
  const result = await getUnifiedStockViewUseCase(symbol, {
    includeQuotes: false,
    includeV6Score: true,
    includeIntelligentScore: true,
    includeIndustryScore: true,
    includeRotationScore: false,
    includeSignal: false,
    includeHolding: false,
  })

  if (!result.success) {
    return { success: false, error: result.error }
  }

  const view = result.data!
  return {
    success: true,
    data: {
      stock: view.stock,
      v6Score: view.v6Score,
      intelligentScore: view.intelligentScore,
      industryScore: view.industryScore,
      completeness: view.quality.completeness,
    },
  }
}

export async function getTradingViewUseCase(symbol: string): Promise<DataLayerResult<{
  stock: Stock
  quotes?: DailyQuotes
  v6Score?: V6Score
  signal?: Signal
  holding?: PortfolioHolding
  completeness: number
}>> {
  const result = await getUnifiedStockViewUseCase(symbol, {
    includeQuotes: true,
    includeV6Score: true,
    includeIntelligentScore: false,
    includeIndustryScore: false,
    includeRotationScore: false,
    includeSignal: true,
    includeHolding: true,
  })

  if (!result.success) {
    return { success: false, error: result.error }
  }

  const view = result.data!
  return {
    success: true,
    data: {
      stock: view.stock,
      quotes: view.quotes,
      v6Score: view.v6Score,
      signal: view.signal,
      holding: view.holding,
      completeness: view.quality.completeness,
    },
  }
}

/**
 * @module services/useCase/hotSectorQuery.useCase
 * @description 热门板块查询执行用例
 *
 * 封装对 input/hotSectorService 的跨域调用，使 trading/strategy 等域
 * 可通过 UseCase 合法获取热门板块数据，避免 Service 之间的直接耦合。
 */

import { getLogger } from '@/lib/logger'
import { getHotSectors, type HotSector } from '@/services/input/hotSectorService'

const logger = getLogger()

export interface HotSectorQueryInput {
  /** 返回的板块数量上限 */
  topN?: number
}

export interface HotSectorQueryResult {
  /** 热门板块列表（按 score 降序） */
  hotSectors: HotSector[]
}

/**
 * 热门板块查询执行用例
 *
 * @param input 查询参数
 * @returns 热门板块列表
 */
export async function hotSectorQueryUseCase(
  input: HotSectorQueryInput = {},
): Promise<HotSectorQueryResult> {
  const topN = input.topN ?? 10

  logger.info('[hotSectorQueryUseCase] 开始查询热门板块', { topN })

  try {
    const allSectors = getHotSectors()
    const sorted = allSectors.sort((a, b) => b.score - a.score)
    const hotSectors = sorted.slice(0, topN)

    logger.info('[hotSectorQueryUseCase] 查询完成', {
      totalCount: allSectors.length,
      returnedCount: hotSectors.length,
      topSectors: hotSectors.map((s) => ({ name: s.name, score: s.score })),
    })

    return { hotSectors }
  } catch (err) {
    logger.error('[hotSectorQueryUseCase] 查询失败', {
      error: err instanceof Error ? err.message : String(err),
    })
    return { hotSectors: [] }
  }
}

/**
 * @module services/useCase/runDualStrategy.useCase
 * @description 双策略执行用例
 *
 * 将原先 trading/dualStrategyEngine 中的跨域编排逻辑抽取为独立 UseCase，
 * 使其可合法调用 scoring 域的 analyzer/detector，避免 Service 之间的直接耦合。
 */

import {
  getDefaultDualStrategyRuleConfig,
  type DualStrategyRuleConfig,
} from '@/config/dualStrategyRules'
import type { DataLayerResult, DualStrategyResult, Signal, Stock } from '@/data/types'
import { generateId } from '@/data/db'
import { getLogger } from '@/lib/logger'
import { analyzeHotSectors } from '@/services/scoring/hotSectorAnalyzer'
import { analyzeValuePits } from '@/services/scoring/valuePitAnalyzer'
import { detectBySector } from '@/services/scoring/rotationSignalDetector'

const logger = getLogger()

export interface RunDualStrategyInput {
  stocks: Stock[]
  ruleConfig?: DualStrategyRuleConfig
  persistScores?: boolean
}

/** 旧版接口别名，保持兼容性 */
export type RunDualStrategyOptions = RunDualStrategyInput

/**
 * 双策略执行用例
 *
 * 对输入 symbol 列表同时执行：
 * 1. 热门板块策略评分（scoring/hotSectorAnalyzer）
 * 2. 价值洼地策略评分（scoring/valuePitAnalyzer）
 * 3. 价值洼地轮动信号检测（scoring/rotationSignalDetector）
 *
 * @returns DualStrategyResult 或错误信息
 */
export async function runDualStrategyUseCase(
  input: RunDualStrategyInput,
): Promise<DataLayerResult<DualStrategyResult>> {
  const ruleConfig = input.ruleConfig ?? getDefaultDualStrategyRuleConfig()
  const stocks = input.stocks

  if (stocks.length === 0) {
    return {
      success: true,
      data: {
        hotSectorScores: [],
        valuePitScores: [],
        signals: [],
        watchlistCandidates: [],
        summary: {
          total: 0,
          hotSectorCount: 0,
          valuePitCount: 0,
          signalCount: 0,
          watchlistCount: 0,
        },
      },
    }
  }

  logger.info(`[runDualStrategyUseCase] 开始执行双策略，标的数 ${stocks.length}`)

  const [hotResult, pitResult] = await Promise.all([
    analyzeHotSectors(stocks, { ruleConfig }),
    analyzeValuePits(stocks, { ruleConfig }),
  ])

  const hotSectorScores = hotResult.data ?? []
  const valuePitScores = pitResult.data ?? []

  const signals: Signal[] = []
  const watchlistCandidates: Array<{ symbol: string; reason: string }> = []

  for (const score of valuePitScores) {
    if (score.action !== 'immediate' && score.action !== 'probe' && score.action !== 'wait') {
      continue
    }

    const rotation = await detectBySector(score.name)
    const isRotationTriggered = rotation?.triggered ?? false

    // 更新 score 的 rotationSignal 标志
    score.rotationSignal = isRotationTriggered

    if (isRotationTriggered && (score.action === 'probe' || score.action === 'wait')) {
      signals.push({
        id: generateId(),
        symbol: score.symbol,
        direction: 'buy',
        type: 'buy_rotation',
        strategy: 'dual',
        confidence: Math.min(0.9, 0.5 + score.score / 10),
        rationale: `价值洼地轮动信号触发：板块 ${score.name} 成交量/资金/技术金叉条件满足`,
        snapshot: {
          priceToMA20: undefined,
          priceToMA60: undefined,
        },
        createdAt: Date.now(),
      })
    } else if (!isRotationTriggered && score.action === 'wait') {
      watchlistCandidates.push({
        symbol: score.symbol,
        reason: `板块 ${score.name} 轮动信号尚未触发`,
      })
    }
  }

  const result: DualStrategyResult = {
    hotSectorScores,
    valuePitScores,
    signals,
    watchlistCandidates,
    summary: {
      total: stocks.length,
      hotSectorCount: hotSectorScores.length,
      valuePitCount: valuePitScores.length,
      signalCount: signals.length,
      watchlistCount: watchlistCandidates.length,
    },
  }

  logger.info(
    `[runDualStrategyUseCase] 完成：热门 ${result.summary.hotSectorCount} / 洼地 ${result.summary.valuePitCount} / 信号 ${result.summary.signalCount} / 观察 ${result.summary.watchlistCount}`,
  )
  return { success: true, data: result }
}

/**
 * @module services/useCase/strategySnapshotSave.useCase
 * @lifecycle @Global
 * @description 策略快照保存用例 — 将策略运行时的配置、持仓、评分等关键状态持久化到本地数据库
 *
 * 业务流程（3步）：
 * 1. 参数校验与默认值填充
 * 2. 构造策略快照 payload（含 configHash、version、traceId）
 * 3. 通过 DataBridge 信封协议持久化到 strategySnapshots store
 */

import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import { ENVELOPE_ACTION, ENVELOPE_TARGET, MODULE_ID } from '@/config/dbConfig'

const logger = getLogger()

export interface StrategySnapshotPosition {
  symbol: string
  quantity: number
  avgCost: number
}

export interface SaveStrategySnapshotInput {
  strategyName: string
  description?: string
  positions: StrategySnapshotPosition[]
  config?: Record<string, unknown>
  score?: number
  version?: number
}

export interface SaveStrategySnapshotResult {
  success: boolean
  snapshotId?: string
  error?: string
}

interface StrategySnapshotPayload {
  id: string
  strategyName: string
  description: string
  positions: StrategySnapshotPosition[]
  config: Record<string, unknown>
  score: number
  version: number
  configHash: number
  createdAt: number
  traceId: string
}

function computeConfigHash(config: Record<string, unknown>): number {
  const str = JSON.stringify(config, Object.keys(config).sort())
  let hash = 0
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i)
    hash = (hash << 5) - hash + char
    hash |= 0
  }
  return hash
}

/**
 * 保存策略快照用例
 *
 * @param input 策略快照输入参数
 * @returns 保存结果（含 snapshotId 或 error）
 */
export async function strategySnapshotSaveUseCase(
  input: SaveStrategySnapshotInput,
): Promise<SaveStrategySnapshotResult> {
  logger.info('[strategySnapshotSaveUseCase] 开始保存策略快照', { strategyName: input.strategyName })

  // Step 1: 参数校验
  if (!input.strategyName || input.strategyName.trim().length === 0) {
    return { success: false, error: '策略名称不能为空' }
  }

  if (!Array.isArray(input.positions)) {
    return { success: false, error: 'positions 必须是数组' }
  }

  for (const pos of input.positions) {
    if (!pos.symbol || pos.symbol.trim().length === 0) {
      return { success: false, error: '持仓股票代码不能为空' }
    }
    if (pos.quantity < 0 || !Number.isFinite(pos.quantity)) {
      return { success: false, error: `持仓数量无效: ${pos.symbol}` }
    }
    if (pos.avgCost < 0 || !Number.isFinite(pos.avgCost)) {
      return { success: false, error: `持仓成本无效: ${pos.symbol}` }
    }
  }

  // Step 2: 构造 payload
  const now = Date.now()
  const traceId = `uc-snapshot-${now}-${input.strategyName}`
  const snapshotId = `snap_${now}_${Math.random().toString(36).slice(2, 8)}`
  const config = input.config ?? {}
  const configHash = computeConfigHash(config)

  const snapshot: StrategySnapshotPayload = {
    id: snapshotId,
    strategyName: input.strategyName,
    description: input.description ?? '',
    positions: input.positions,
    config,
    score: input.score ?? 0,
    version: input.version ?? 1,
    configHash,
    createdAt: now,
    traceId,
  }

  logger.info('[strategySnapshotSaveUseCase] 快照构造完成', { snapshotId, strategyName: snapshot.strategyName })

  // Step 3: 通过 DataBridge 持久化
  try {
    const envelope = EnvelopeFactory.create(
      { source: MODULE_ID.strategy, target: ENVELOPE_TARGET.db, action: ENVELOPE_ACTION.saveStrategySnapshots, traceId },
      snapshot,
    )

    await dataBridge.forward(envelope)

    logger.info('[strategySnapshotSaveUseCase] 策略快照保存成功', { snapshotId })

    return { success: true, snapshotId }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error('[strategySnapshotSaveUseCase] 策略快照保存失败', { error: message, snapshotId })

    return { success: false, error: message }
  }
}

/**
 * @module services/useCase/submitOrder.useCase
 * @lifecycle @Global
 * @description 提交订单用例 — 封装订单提交的完整业务流程
 *
 * 业务流程（4步）：
 * 1. 参数校验（金额精度、数量合法性、方向有效性）
 * 2. 构造完整 Order 对象（生成 id/createdAt/traceId）
 * 3. 通过 DataBridge 信封协议持久化
 * 4. 广播 ORDERS_CHANGED 事件通知其他 Store/Tab
 */

import { getLogger } from '@/lib/logger'
import { dataBridge } from '@/core/databridge'
import { EnvelopeFactory } from '@/core/envelope'
import { ENVELOPE_ACTION, ENVELOPE_TARGET, MODULE_ID, ORDER_STATUS, ACCOUNT_TYPE, STORE_NAME } from '@/config/dbConfig'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { withBroadcast } from '@/lib/withBroadcast'
import { startOperation, succeedOperation, failOperation } from '@/services/feedbackService'
import { runInTransaction } from '@/core/transaction'
import type { Order } from '@/data/types'

const logger = getLogger()

export interface SubmitOrderInput {
  symbol: string
  direction: 'buy' | 'sell'
  quantity: number
  price: number
  note?: string
}

export interface SubmitOrderResult {
  success: boolean
  orderId?: string
  error?: string
}

/**
 * 提交订单用例
 *
 * @param input 订单输入参数
 * @returns 提交结果（含 orderId 或 error）
 */
export async function submitOrderUseCase(
  input: SubmitOrderInput,
): Promise<SubmitOrderResult> {
  const opId = startOperation('submitOrder', {
    message: `提交${input.direction === 'buy' ? '买入' : '卖出'}订单: ${input.symbol} × ${input.quantity} @ ¥${input.price}`,
    metadata: { symbol: input.symbol, direction: input.direction },
  })

  logger.info('[submitOrderUseCase] 开始提交订单', { symbol: input.symbol, direction: input.direction })

  // Step 1: 参数校验
  if (!input.symbol || input.symbol.trim().length === 0) {
    return { success: false, error: '股票代码不能为空' }
  }

  if (input.quantity <= 0 || !Number.isFinite(input.quantity)) {
    return { success: false, error: '交易数量必须为正数' }
  }

  if (input.price <= 0 || !Number.isFinite(input.price)) {
    return { success: false, error: '交易价格必须为正数' }
  }

  if (input.direction !== 'buy' && input.direction !== 'sell') {
    return { success: false, error: `不支持的方向: ${String(input.direction)}` }
  }

  // Step 2: 构造完整 Order 对象
  const now = Date.now()
  const traceId = `uc-submit-${now}-${input.symbol}`
  const orderId = `ord_${now}_${Math.random().toString(36).slice(2, 8)}`
  const roundedPrice = Math.round(input.price * 100) / 100
  const roundedAmount = Math.round(input.quantity * roundedPrice * 100) / 100

  const order: Order = {
    id: orderId,
    symbol: input.symbol.toUpperCase(),
    direction: input.direction,
    quantity: input.quantity,
    price: roundedPrice,
    amount: roundedAmount,
    status: ORDER_STATUS.pending,
    accountType: ACCOUNT_TYPE.paper,
    createdAt: now,
  }

  logger.info('[submitOrderUseCase] 订单构造完成', { orderId, symbol: order.symbol })

  // Step 3: 在事务中通过 DataBridge 持久化
  try {
    await runInTransaction<void>(
      [STORE_NAME.orders],
      'readwrite',
      async (_tx) => {
        const envelope = EnvelopeFactory.create(
          { source: MODULE_ID.trading, target: ENVELOPE_TARGET.db, action: ENVELOPE_ACTION.insertOrder, traceId },
          order,
        )

        await dataBridge.forward(envelope)
      },
    )

    // Step 4: 广播事件
    withBroadcast(EVENT_NAMES.ORDERS_CHANGED, { action: 'add', id: orderId, traceId })

    logger.info('[submitOrderUseCase] 订单提交成功', { orderId })
    succeedOperation(opId, { message: `订单 ${orderId} 提交成功` })

    return { success: true, orderId }
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    logger.error('[submitOrderUseCase] 订单提交失败', { error: message, orderId })
    failOperation(opId, message, { message: `订单提交失败: ${message}` })

    return { success: false, error: message }
  }
}
